diff --git a/src/soc_ifc/rtl/sha512_acc_iccm_hash.sv b/src/soc_ifc/rtl/sha512_acc_iccm_hash.sv
index 0bbff094..c87cbf05 100644
--- a/src/soc_ifc/rtl/sha512_acc_iccm_hash.sv
+++ b/src/soc_ifc/rtl/sha512_acc_iccm_hash.sv
@@ -61,6 +61,7 @@ module sha512_acc_iccm_hash
   // ICCM hash mode signals
   logic iccm_mode_done;
   logic iccm_armed;
+  logic iccm_hash_trigger;

   // PCR write via kv_write_client
   logic iccm_pcr_dest_done;
@@ -96,14 +97,18 @@ module sha512_acc_iccm_hash
 // iccm_lock_i for the zero-length case. The OR with the live trigger
 // engages the same cycle the snoop fires to capture the first dword
 // without a one-cycle slip.
-always_comb iccm_mode = (iccm_armed | ((iccm_hash_dv_i | iccm_lock_i) & ~soc_has_lock)) & ~iccm_mode_done;
+// iccm_hash_trigger is gated so the hash does NOT arm while the SHA acc LOCK
+// is already held (e.g. the KAT holds the lock out of reset, LOCK resets to 1).
+// The sticky iccm_armed term keeps iccm_mode asserted after the hash acquires
+// the lock itself, so this gate only blocks arming against a pre-existing lock.
+always_comb iccm_hash_trigger = (iccm_hash_dv_i | iccm_lock_i) & ~soc_has_lock & ~lock_value;
+
+always_comb iccm_mode = (iccm_armed | iccm_hash_trigger) & ~iccm_mode_done;

 // HW SHA acc lock acquire: pulse hwset on the very first ICCM activity
 // (snoop or iccm_lock_i). Gated by ~iccm_armed so the pulse fires exactly
 // once at the start of the measurement, not again during release.
-always_comb iccm_lock_acquire = (iccm_hash_dv_i | iccm_lock_i) &
-                                ~soc_has_lock & ~iccm_armed & ~iccm_mode_done &
-                                ~lock_value;
+always_comb iccm_lock_acquire = iccm_hash_trigger & ~iccm_armed & ~iccm_mode_done;

 // HW lock release: clear LOCK back to 0 (free) after the full extend
 // sequence completes (EXTEND_DONE). Using extend_fsm_ps == EXTEND_DONE
@@ -138,7 +143,7 @@ always_ff @(posedge clk or negedge rst_b) begin
     iccm_armed <= 1'b0;
   else if (iccm_unlock_i)
     iccm_armed <= 1'b0;
-  else if ((iccm_hash_dv_i | iccm_lock_i) & ~soc_has_lock & ~iccm_mode_done)
+  else if (iccm_hash_trigger & ~iccm_mode_done)
     iccm_armed <= 1'b1;
 end

diff --git a/src/soc_ifc/rtl/soc_ifc_internal_reg.rdl b/src/soc_ifc/rtl/soc_ifc_internal_reg.rdl
index bb5ec284..f916a406 100644
--- a/src/soc_ifc/rtl/soc_ifc_internal_reg.rdl
+++ b/src/soc_ifc/rtl/soc_ifc_internal_reg.rdl
@@ -282,10 +282,17 @@ reg {
             the four ICCM address registers cannot be modified until the next reset.
             Setting this register also arms the boot flow monitor -- any ICCM fetch
             before this lock is set triggers a fatal error.
+            [br][br]This lock is hardware-cleared at the end of every reset flow,
+            including a firmware-update (hitless) reset, via the same iccm_unlock
+            pulse used for internal_iccm_lock. A hitless update only asserts
+            cptra_uc_rst_b (not cptra_noncore_rst_b), so without this hardware
+            clear the lock would persist and freeze stale ICCM region boundaries.
+            ROM must therefore reprogram all four ICCM region address registers and
+            re-set this lock on every boot, including after a hitless update.
             [br]Caliptra Access: RW1S
             [br]SOC Access:      RO (writes rejected via swwel)";

-    field {desc = "Lock bit for ICCM region registers. Write 1 to set -- cannot be cleared by SW."; hw = r; sw = rw; onwrite = woset; swwel = soc_req; resetsignal = cptra_rst_b;} lock = 1'b0;
+    field {desc = "Lock bit for ICCM region registers. Write 1 to set -- cannot be cleared by SW. Hardware-cleared at end of every reset flow (incl. hitless update) so ROM can reprogram and re-lock."; hw = r; hwclr = true; sw = rw; onwrite = woset; precedence = hw; swwel = soc_req; resetsignal = cptra_rst_b;} lock = 1'b0;
 } internal_iccm_region_lock;

 reg {
