+++ b/src/soc_ifc/rtl/soc_ifc_reg_pkg.sv
@@ -662,6 +662,14 @@ package soc_ifc_reg_pkg;
         logic wr_ack;
     } soc_ifc_reg__internal_iccm_rt_end_addr__external__in_t;

+    typedef struct packed{
