+    } soc_ifc_reg__internal_iccm_region_lock__in_t;
+
     typedef struct packed{
         logic hwset;
     } soc_ifc_reg__intr_block_t__error_intr_t_error_bad_fuse_sts_23f67582_error_cmd_fail_sts_b85845f8_error_iccm_blocked_sts_e81e6ad2_error_internal_sts_caad62e2_error_inv_dev_sts_6693e7db_error_mbox_ecc_unc_sts_30bff330_error_wdt_timer1_timeout_sts_6aaa9655_error_wdt_timer2_timeout_sts_cda8789f__error_internal_sts_enable_d33001bb_next_52b75ffa_resetsignal_f7aac87a__in_t;
@@ -823,6 +831,7 @@ package soc_ifc_reg_pkg;
         soc_ifc_reg__internal_iccm_fmc_end_addr__external__in_t internal_iccm_fmc_end_addr;
         soc_ifc_reg__internal_iccm_rt_start_addr__external__in_t internal_iccm_rt_start_addr;
         soc_ifc_reg__internal_iccm_rt_end_addr__external__in_t internal_iccm_rt_end_addr;
+        soc_ifc_reg__internal_iccm_region_lock__in_t internal_iccm_region_lock;
         soc_ifc_reg__intr_block_t__in_t intr_block_rf;
     } soc_ifc_reg__in_t;

diff --git a/src/soc_ifc/rtl/soc_ifc_top.sv b/src/soc_ifc/rtl/soc_ifc_top.sv
index 7db06c46..a51af145 100644
--- a/src/soc_ifc/rtl/soc_ifc_top.sv
+++ b/src/soc_ifc/rtl/soc_ifc_top.sv
@@ -1093,6 +1093,8 @@ always_comb soc_ifc_reg_hwif_in.intr_block_rf.error_internal_intr_r.error_wdt_ti
 always_comb soc_ifc_reg_hwif_in.intr_block_rf.error_internal_intr_r.error_wdt_timer2_timeout_sts.hwset = t2_timeout_p && timer2_en;

 always_comb soc_ifc_reg_hwif_in.internal_iccm_lock.lock.hwclr    = iccm_unlock;
+// Clear the ICCM region lock after hitless update
+always_comb soc_ifc_reg_hwif_in.internal_iccm_region_lock.lock.hwclr = iccm_unlock;


 logic [SOC_IFC_DATA_W-1:0] s_cpuif_wr_biten;
@@ -1166,9 +1168,14 @@ logic       shadow_update_err;

 // Sticky committed flags -- once a successful 2-phase write occurs, committed
 // stays set until reset. This gates the effective lock in the boot flow monitor.
+// Also cleared by iccm_unlock at the end of every reset flow (incl. hitless/fw-update
+// reset) so the effective lock cannot re-arm with stale boundaries: ROM must re-commit
+// all four region address registers after a hitless update before the monitor arms.
 always_ff @(posedge clk or negedge cptra_noncore_rst_b) begin
     if (!cptra_noncore_rst_b)
         iccm_shadow_committed <= 4'b0;
+    else if (iccm_unlock)
+        iccm_shadow_committed <= 4'b0;
     else
         iccm_shadow_committed <= iccm_shadow_committed | iccm_shadow_qe;
 end

