diff --git a/tools/dv-classes/ahb_agent/ahb_agent_pkg.sv b/tools/dv-classes/ahb_agent/ahb_agent_pkg.sv
new file mode 100644
index 00000000..bb10712e
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_agent_pkg.sv
@@ -0,0 +1,59 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+package ahb_agent_pkg;
+  import uvm_pkg::*;
+  `include "uvm_macros.svh"
+
+  typedef enum bit [1:0] {
+    TransIdle = 0,
+    TransBusy = 1,
+    TransNonSequential = 2,
+    TransSequential = 3
+  } trans_e;
+
+  typedef enum bit [2:0] {
+    BurstSingle = 0,
+    BurstIncr   = 1,
+    BurstWrap4  = 2,
+    BurstIncr4  = 3,
+    BurstWrap8  = 4,
+    BurstIncr8  = 5,
+    BurstWrap16 = 6,
+    BurstIncr16 = 7
+  } burst_e;
+
+  // A structure representing an address range and a particular subordinate index. A queue of these
+  // structures defines a partial map from address to subordinate index (take the first item that
+  // matches the address).
+  //
+  // This is used in ahb_mgr_agent, but also in ahb_mgr_register_layer_vseq.
+  typedef struct {
+    bit [63:0]   addr_min;        // Minimum address in the range
+    bit [63:0]   addr_max;        // Maximum address in the range (inclusive)
+    int unsigned subordinate_idx; // Index of the associated subordinate.
+  } sub_addr_range_t;
+
+  `include "ahb_status_item.svh"
+  `include "ahb_reg_op_item.svh"
+
+  `include "ahb_txn_request_item.svh"
+  `include "ahb_txn_response_item.svh"
+  `include "ahb_txn_item.svh"
+
+  `include "ahb_monitor.svh"
+
+  `include "ahb_mgr_driver.svh"
+  `include "ahb_mgr_reg_adapter.svh"
+
+  typedef uvm_sequencer#(ahb_reg_op_item)                         ahb_reg_op_sequencer_t;
+  typedef uvm_sequencer#(ahb_txn_request_item, uvm_sequence_item) ahb_txn_sequencer_t;
+
+  `include "seq_lib/ahb_transfer_seq.svh"
+  `include "seq_lib/ahb_single_read_seq.svh"
+  `include "seq_lib/ahb_single_write_seq.svh"
+  `include "seq_lib/ahb_mgr_register_layer_vseq.svh"
+
+  `include "ahb_mgr_agent.svh"
+endpackage
diff --git a/tools/dv-classes/ahb_agent/ahb_if.sv b/tools/dv-classes/ahb_agent/ahb_if.sv
new file mode 100644
index 00000000..1b8221fb
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_if.sv
@@ -0,0 +1,366 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// An interface to track an AHB bus
+
+interface ahb_if (input clk_i, input rst_ni);
+  import uvm_pkg::*;
+  `include "uvm_macros.svh"
+  import dv_utils_pkg::if_mode_e, dv_utils_pkg::Host, dv_utils_pkg::Device, dv_utils_pkg::Monitor;
+
+  // The interface mode.
+  //
+  //  - Host:    An agent is driving the interface signals through host_cb acting as a Manager.
+  //  - Device:  An agent is driving the interface signals through device_cb, as a Subordinate.
+  //  - Monitor: No agent is driving interface signals and the interface is purely passive.
+  if_mode_e if_mode = Monitor;
+
+  // The ADDR_WIDTH property. Set this by calling set_addr_width().
+  //
+  // Note: This size is not constrained in the AHB specification (issue C), but the specification
+  //       recommends to set it in the range 10..64. The default value of 32 matches a historical
+  //       convention (used in issues A and B of the specification). The max-footprint approach in
+  //       this interface only supports widths up to 64.
+  int unsigned addr_width = 32;
+
+  // The HBURST_WIDTH property. Set this by calling set_hburst_width().
+  int unsigned hburst_width = 3;
+
+  // The HPROT_WIDTH property. Set this by calling set_hprot_width().
+  int unsigned hprot_width = 7;
+
+  // The DATA_WIDTH property. Set this by calling set_data_width().
+  int unsigned data_width = 256;
+
+  // The Write_Strobes property. Enable or disable this by calling set_has_write_strobes().
+  bit          has_write_strobes = 1;
+
+  // The number of subordinates attached to the bus. Each will have its own HSELx line, driven by a
+  // decoder. Set this by calling set_num_subordinates().
+  //
+  // Note: There must be at least one subordinate (the default value, because this is likely to
+  //       match many block-level testbenches). The max-footprint approach in this interface only
+  //       supports num_subordinates <= 8.
+  int unsigned num_subordinates = 1;
+
+  // The defined manager signals
+  //
+  // This interface uses a max footprint approach. Signals of configurable width (like haddr) might
+  // only use the lower bits.
+  wire [63:0]   haddr;
+  wire [2:0]    hburst;
+  wire          hmastlock;
+  wire [6:0]    hprot;
+  wire [2:0]    hsize;
+  wire [1:0]    htrans;
+  wire [1023:0] hwdata;
+  wire [127:0]  hwstrb;
+  wire          hwrite;
+
+  // The defined decoder signal
+  //
+  // This interface uses a max footprint approach. The hsel signal has configurable width so might
+  // only use the lower bits.
+  //
+  // Note that when if_mode == Host the interface drives hsel through host_cb, grouping the decoder
+  // with the manager as part of the "host side".
+  wire [7:0]    hsel;
+
+  // The defined subordinate signals
+  //
+  // This interface uses a max footprint approach, supporting up to 8 subordinates and a data width
+  // of 1024 bits.
+  wire [7:0][1023:0] hrdata;
+  wire [7:0]         hreadyout;
+  wire [7:0]         hresp;
+
+  // The defined multiplexor signals
+  //
+  // This interface uses a max footprint approach, supporting a data width of 1024 bits. The
+  // hrdata_muxed and hresp_muxed signals are the selected subordinate's hrdata and hresp signals,
+  // respectively.
+  //
+  // When if_mode == Device, these are driven by a multiplexor built in to the interface.
+  wire [1023:0] hrdata_muxed;
+  wire          hready;
+  wire          hresp_muxed;
+
+  // Copies of the signals driven by host_cb (only used if if_mode == Host). The "*_driven" signals
+  // are directly driven by the clocking block. The "*_internal" signals track these, but take masks
+  // into account for signals with configurable length and are also cleared on reset.
+  logic [63:0]   haddr_driven, haddr_internal;
+  logic [2:0]    hburst_driven, hburst_internal;
+  logic          hmastlock_driven, hmastlock_internal;
+  logic [6:0]    hprot_driven, hprot_internal;
+  logic [2:0]    hsize_driven, hsize_internal;
+  logic [1:0]    htrans_driven, htrans_internal;
+  logic [1023:0] hwdata_driven, hwdata_internal;
+  logic [127:0]  hwstrb_driven, hwstrb_internal;
+  logic          hwrite_driven, hwrite_internal;
+  logic [7:0]    hsel_driven, hsel_internal;
+
+  // Copies of the signals driven by device_cb (only used if if_mode == Device). The "*_driven"
+  // signals are directly driven by the clocking block. The "*_internal" signals track these, but
+  // take masks into account for signals with configurable length and are also cleared on reset.
+  logic [7:0][1023:0] hrdata_driven, hrdata_internal;
+  logic [7:0]         hreadyout_driven, hreadyout_internal;
+  logic [7:0]         hresp_driven, hresp_internal;
+
+  // A signal with the same format as hsel, but used for any data phase that's happening on this
+  // cycle. This comes from the previous cycle's hsel, and is updated unless there is a data phase
+  // on the cycle and the muxed hreadyout signal is not asserted.
+  logic [7:0]         data_hsel_d, data_hsel_q;
+
+  // A multiplexor is defined in the interface, for use when if_mode == Device or if_mode ==
+  // Manager. This drives *_internal signals (zeroing everything combinatorially on a reset)
+  //
+  // The multiplexing is done with a combinatorial block, using OR to pick the value from the
+  // selected subordinate (using data_hsel_q).
+  //
+  // The hready signal is special and is defined to be 1 when no subordinate is selected: that
+  // signal is intended for a subordinate to exert back pressure in the middle of the data phase, so
+  // it doesn't make sense for it to be false when no subordinate is acting.
+  logic [1023:0] hrdata_muxed_internal;
+  logic          hready_internal;
+  logic          hresp_muxed_internal;
+
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (!rst_ni) data_hsel_q <= '0;
+    else         data_hsel_q <= data_hsel_d;
+  end
+
+  always_comb begin
+    // Was a subordinate selected for the data phase this cycle applying back-pressure? If so, there
+    // will be an index i such that data_hsel_q[i] is true but hreadyout[i] is false. In this case,
+    // hready_internal will be zero.
+    if (!hready_internal) begin
+      data_hsel_d = data_hsel_q;
+    end else begin
+      // There is no subordinate applying back pressure. If the address phase currently holds a
+      // transfer that has a data phase (TransNonSequential or TransSequential) then the current
+      // hsel signal should apply to the data phase next cycle. If not, there will be no data phase
+      // next cycle. Set hsel to zero in the interface to make the waves easier to read.
+      data_hsel_d = (htrans inside {ahb_agent_pkg::TransNonSequential,
+                                    ahb_agent_pkg::TransSequential}) ?
+                    hsel : '0;
+    end
+  end
+
+  always_comb begin
+    hrdata_muxed_internal = '0;
+    hready_internal = 1'b1;
+    hresp_muxed_internal = 1'b0;
+
+    if (rst_ni) begin
+      for (int unsigned i = 0; i < num_subordinates && i < 8; i++) begin
+        if (data_hsel_q[i]) begin
+          hrdata_muxed_internal  |= hrdata[i];
+          hready_internal        &= hreadyout[i];
+          hresp_muxed_internal   |= hresp[i];
+        end
+      end
+    end
+  end
+
+  // Masks used when converting some *_driven signals to *_internal
+  logic [63:0]        haddr_mask;
+  logic [2:0]         hburst_mask;
+  logic [6:0]         hprot_mask;
+  logic [1023:0]      data_mask;
+  logic [127:0]       strb_mask;
+  logic [7:0]         hsel_mask;
+  logic [7:0][1023:0] sub_data_mask;
+
+  assign haddr_mask   = (64'b1 << addr_width) - 1;
+  assign hburst_mask  = (3'b1 << hburst_width) - 1;
+  assign hprot_mask   = (7'b1 << hprot_width) - 1;
+  assign data_mask    = (1024'b1 << data_width) - 1;
+  assign strb_mask    = has_write_strobes ? ((128'b1 << ((data_width + 7) / 8)) - 1) : '0;
+  assign hsel_mask    = (8'b1 << num_subordinates) - 1;
+
+  always_comb begin
+    for (int unsigned i = 0; i < 8; i++) begin
+      sub_data_mask[i] = (i < num_subordinates) ? data_mask : '0;
+    end
+  end
+
+  clocking mon_cb @(posedge clk_i);
+    input haddr;
+    input hburst;
+    input hmastlock;
+    input hprot;
+    input hsize;
+    input htrans;
+    input hwdata;
+    input hwstrb;
+    input hwrite;
+    input hsel;
+    input hrdata;
+    input hreadyout;
+    input hresp;
+    input hrdata_muxed;
+    input hready;
+    input hresp_muxed;
+  endclocking
+
+  clocking host_cb @(posedge clk_i);
+    output haddr     = haddr_driven;
+    output hburst    = hburst_driven;
+    output hmastlock = hmastlock_driven;
+    output hprot     = hprot_driven;
+    output hsize     = hsize_driven;
+    output htrans    = htrans_driven;
+    output hwdata    = hwdata_driven;
+    output hwstrb    = hwstrb_driven;
+    output hwrite    = hwrite_driven;
+    output hsel      = hsel_driven;
+    input  hrdata;
+    input  hreadyout;
+    input  hresp;
+    input  hrdata_muxed;
+    input  hready;
+    input  hresp_muxed;
+  endclocking
+
+  clocking device_cb @(posedge clk_i);
+    input  haddr;
+    input  hburst;
+    input  hmastlock;
+    input  hprot;
+    input  hsize;
+    input  htrans;
+    input  hwdata;
+    input  hwstrb;
+    input  hwrite;
+    input  hsel;
+    output hrdata    = hrdata_driven;
+    output hreadyout = hreadyout_driven;
+    output hresp     = hresp_driven;
+  endclocking
+
+  always_comb begin
+    if (!rst_ni) begin
+      haddr_internal     = '0;
+      hburst_internal    = '0;
+      hmastlock_internal = '0;
+      hprot_internal     = '0;
+      hsize_internal     = '0;
+      htrans_internal    = '0;
+      hwdata_internal    = '0;
+      hwstrb_internal    = '0;
+      hwrite_internal    = '0;
+      hsel_internal      = '0;
+      hrdata_internal    = '0;
+      hreadyout_internal = '0;
+      hresp_internal     = '0;
+    end else begin
+      haddr_internal     = haddr_driven & haddr_mask;
+      hburst_internal    = hburst_driven & hburst_mask;
+      hmastlock_internal = hmastlock_driven;
+      hprot_internal     = hprot_driven & hprot_mask;
+      hsize_internal     = hsize_driven;
+      htrans_internal    = htrans_driven;
+      hwdata_internal    = hwdata_driven & data_mask;
+      hwstrb_internal    = hwstrb_driven & strb_mask;
+      hwrite_internal    = hwrite_driven;
+      hsel_internal      = hsel_driven & hsel_mask;
+      hrdata_internal    = hrdata_driven & sub_data_mask;
+      hreadyout_internal = hreadyout_driven;
+      hresp_internal     = hresp_driven;
+    end
+  end
+
+  assign haddr         = (if_mode == Host)   ? haddr_internal         : 'z;
+  assign hburst        = (if_mode == Host)   ? hburst_internal        : 'z;
+  assign hmastlock     = (if_mode == Host)   ? hmastlock_internal     : 'z;
+  assign hprot         = (if_mode == Host)   ? hprot_internal         : 'z;
+  assign hsize         = (if_mode == Host)   ? hsize_internal         : 'z;
+  assign htrans        = (if_mode == Host)   ? htrans_internal        : 'z;
+  assign hwdata        = (if_mode == Host)   ? hwdata_internal        : 'z;
+  assign hwstrb        = (if_mode == Host)   ? hwstrb_internal        : 'z;
+  assign hwrite        = (if_mode == Host)   ? hwrite_internal        : 'z;
+  assign hsel          = (if_mode == Host)   ? hsel_internal          : 'z;
+  assign hrdata        = (if_mode == Device) ? hrdata_internal        : 'z;
+  assign hreadyout     = (if_mode == Device) ? hreadyout_internal     : 'z;
+  assign hresp         = (if_mode == Device) ? hresp_internal         : 'z;
+
+  // Note that the hrdata_muxed, hready and hresp_muxed signals come from a "*_internal" signal for
+  // either active mode (Host or Device): in both cases, the interface is supplying the multiplexor,
+  // which drives this signal to both the manager and the subordinate.
+  assign hrdata_muxed  = (if_mode inside {Host, Device}) ? hrdata_muxed_internal : 'z;
+  assign hready        = (if_mode inside {Host, Device}) ? hready_internal       : 'z;
+  assign hresp_muxed   = (if_mode inside {Host, Device}) ? hresp_muxed_internal  : 'z;
+
+  // If if_mode is not Device, the hrdata signals from subordinates are being driven by RTL. That
+  // RTL might not be using the full widths of the interface. Unfortunately, the muxing would
+  // convert the resulting 'z bits to 'x. Add a weak pull-down here.
+  //
+  // Because if_mode is not static, this pull-down is also applied when if-mode == Device. The whole
+  // signal will be driven by the device_cb anyway, so this won't have any effect.
+  assign (weak0, weak1) hrdata = '0;
+
+  // Set the ADDR_WIDTH property. The AHB specification (issue C) does not constrain the value, but
+  // we disallow widths over 64 (in order that a max-footprint approach is possible in this
+  // interface).
+  function void set_addr_width(int unsigned width);
+    if (width > 64) begin
+      `uvm_error($sformatf("%m"),
+                 $sformatf("Cannot set ADDR_WIDTH to %0d: max supported width is 64.",
+                           width))
+      width = 64;
+    end
+    addr_width = width;
+  endfunction
+
+  // Set the HBURST_WIDTH property. The AHB specification (issue C) only allows widths of 0 and 3.
+  function void set_hburst_width(int unsigned width);
+    if (width != 0 && width != 3) begin
+      `uvm_error($sformatf("%m"),
+                 $sformatf("Cannot set HBURST_WIDTH to %0d: allowed values are 0, 3.",
+                           width))
+      width = 0;
+    end
+    hburst_width = width;
+  endfunction
+
+  // Set the HPROT_WIDTH property. The AHB specification (issue C) only allows widths of 0, 4 and 7.
+  function void set_hprot_width(int unsigned width);
+    if (width != 0 && width != 4 && width != 7) begin
+      `uvm_error($sformatf("%m"),
+                 $sformatf("Cannot set HPROT_WIDTH to %0d: allowed values are 0, 4 and 7.",
+                           width))
+      width = 0;
+    end
+    hprot_width = width;
+  endfunction
+
+  // Set the DATA_WIDTH property. The AHB specification (issue C) only allows widths of 8, 16, 32,
+  // 64, 128, 256, 512 and 1024.
+  function void set_data_width(int unsigned width);
+    if (! (width inside {8, 16, 32, 64, 128, 256, 512, 1024})) begin
+      `uvm_error($sformatf("%m"),
+                 $sformatf("Cannot set DATA_WIDTH to %0d: must be power of 2 between 8 and 1024.",
+                           width))
+      width = 32;
+    end
+    data_width = width;
+  endfunction
+
+  // Configure the Write_Strobes property (if false, there is no HWSTRB signal).
+  function void set_has_write_strobes(bit enabled);
+    has_write_strobes = enabled;
+  endfunction
+
+  // Set the number of subordinates (and thus the width of the HSEL signal). This must be in the
+  // range 1..8.
+  function void set_num_subordinates(int unsigned num);
+    if (num == 0 || num > 8) begin
+      `uvm_error($sformatf("%m"),
+                 $sformatf("Cannot set num_subordinates to %0d: number must be in the range 1..8.",
+                           num))
+      num = 8;
+    end
+    num_subordinates = num;
+  endfunction
+endinterface
diff --git a/tools/dv-classes/ahb_agent/ahb_mgr_agent.svh b/tools/dv-classes/ahb_agent/ahb_mgr_agent.svh
new file mode 100644
index 00000000..5e2b8e3b
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_mgr_agent.svh
@@ -0,0 +1,206 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+class ahb_mgr_agent extends uvm_agent;
+  `uvm_component_utils(ahb_mgr_agent)
+
+  typedef uvm_sequencer #(ahb_reg_op_item) layered_reg_sequencer_t;
+
+  // Analysis ports for requests, responses and complete transactions
+  uvm_analysis_port #(ahb_txn_request_item)  m_request_port;
+  uvm_analysis_port #(ahb_txn_response_item) m_response_port;
+  uvm_analysis_port #(ahb_txn_item)          m_transaction_port;
+
+  // The virtual interface. This can either be set by calling set_vif() before the build phase, or
+  // provided through uvm_config_db.
+  local virtual ahb_if m_vif;
+
+  // The monitor for the interface
+  local ahb_monitor m_monitor;
+
+  // The driver that can send read and write transactions
+  local ahb_mgr_driver m_driver;
+
+  // A sequencer that supplies m_driver
+  local ahb_txn_sequencer_t m_sequencer;
+
+  // A reg adapter. This is stateless, so gets created in build_phase whenever the agent is active.
+  local ahb_mgr_reg_adapter m_reg_adapter;
+
+  // A sequencer that can control access to an instance of ahb_mgr_register_layer_vseq (if there is
+  // one)
+  local layered_reg_sequencer_t m_layered_reg_sequencer;
+
+  // A flag that shows there is an instance of ahb_mgr_register_layer_vseq running (started by
+  // run_layered_register_vseq)
+  local bit m_layer_vseq_running;
+
+  // An array of known mappings from address range to subordinate index. Add entries with the
+  // add_subordinate_mapping function.
+  local sub_addr_range_t m_subordinate_ranges[$];
+
+  extern function new (string name, uvm_component parent);
+  extern function void build_phase(uvm_phase phase);
+  extern function void connect_phase(uvm_phase phase);
+
+  // Set m_vif to the provided interface
+  extern function void set_vif(virtual ahb_if vif);
+
+  // Get the sequencer. Can only be called after build_phase, and the agent must be active.
+  extern function ahb_txn_sequencer_t get_sequencer();
+
+  // Get the reg adapter. Can only be called after build_phase, and the agent must be active.
+  extern function ahb_mgr_reg_adapter get_reg_adapter();
+
+  // Add a mapping to m_subordinate_ranges that covers all the items accessible through reg_map. The
+  // single range added includes all the accessible addresses (so this won't work well if there are
+  // gaps)
+  //
+  // This can be called multiple times before starting the layered register vseq (which will use the
+  // information) but cannot be used after that point.
+  extern function void register_subordinate_for_map(uvm_reg_map  reg_map,
+                                                    int unsigned subordinate_idx);
+
+  // Append the agent's mapping from address range to subordinates to the given ranges argument.
+  extern function void get_subordinate_ranges(ref sub_addr_range_t ranges[$]);
+
+  // Run the layered register vseq, which shouldn't already be running.
+  //
+  // This sequence will run forever and its layering sequencer can be retrieved with
+  // get_register_layering_sequencer(). If the sequence is already running for some reason, this
+  // generates a uvm_error and hangs.
+  extern task run_layered_register_vseq();
+
+  // Get a handle to the sequencer that can be used to access a layered register vseq if it is
+  // started.
+  //
+  // Can only be called after build_phase, and the agent must be active.
+  extern function layered_reg_sequencer_t get_register_layering_sequencer();
+endclass
+
+function ahb_mgr_agent::new(string name, uvm_component parent);
+  super.new(name, parent);
+endfunction
+
+function void ahb_mgr_agent::build_phase(uvm_phase phase);
+  super.build_phase(phase);
+
+  m_request_port = new("m_request_port", this);
+  m_response_port = new("m_response_port", this);
+  m_transaction_port = new("m_transaction_port", this);
+
+  if (m_vif == null && !uvm_config_db#(virtual ahb_if)::get(this, "", "vif", m_vif)) begin
+    `uvm_fatal(get_full_name(), "failed to get vif from uvm_config_db")
+  end
+  if (m_vif == null) begin
+    `uvm_fatal(get_full_name(), "No non-null m_vif provided.")
+  end
+
+  m_monitor = ahb_monitor::type_id::create("m_monitor", this);
+  m_monitor.set_vif(m_vif);
+
+  if (get_is_active() == UVM_ACTIVE) begin
+    // Generate a driver, sequencer and reg adapter
+    m_driver = ahb_mgr_driver::type_id::create("m_driver", this);
+    m_sequencer = ahb_txn_sequencer_t::type_id::create("m_sequencer", this);
+    m_reg_adapter = ahb_mgr_reg_adapter::type_id::create("m_reg_adapter");
+    m_layered_reg_sequencer = layered_reg_sequencer_t::type_id::create("m_layered_reg_sequencer",
+                                                                       this);
+
+    // Configure m_reg_adapter's supports_byte_enable flag. The protocol supports this, but only if
+    // the interface has write strobes.
+    m_reg_adapter.supports_byte_enable = m_vif.has_write_strobes;
+  end
+endfunction
+
+function void ahb_mgr_agent::connect_phase(uvm_phase phase);
+  super.connect_phase(phase);
+
+  m_monitor.m_request_port.connect(m_request_port);
+  m_monitor.m_response_port.connect(m_response_port);
+  m_monitor.m_transaction_port.connect(m_transaction_port);
+
+  // If the agent is active, connect drivers to interfaces and sequencers
+  if (get_is_active() == UVM_ACTIVE) begin
+    m_driver.set_vif(m_vif);
+    m_driver.seq_item_port.connect(m_sequencer.seq_item_export);
+  end
+endfunction
+
+function void ahb_mgr_agent::set_vif(virtual ahb_if vif);
+  if (m_vif != null) `uvm_fatal(get_full_name(), "Cannot set vif: m_vif is already non-null.")
+  m_vif = vif;
+endfunction
+
+function ahb_txn_sequencer_t ahb_mgr_agent::get_sequencer();
+  if (m_sequencer == null) `uvm_fatal(get_full_name(), "m_sequencer is null.")
+  return m_sequencer;
+endfunction
+
+function ahb_mgr_reg_adapter ahb_mgr_agent::get_reg_adapter();
+  if (m_reg_adapter == null) `uvm_fatal(get_full_name(), "m_reg_adapter is null.")
+  return m_reg_adapter;
+endfunction
+
+function void ahb_mgr_agent::register_subordinate_for_map(uvm_reg_map   reg_map,
+                                                          int unsigned  subordinate_idx);
+  uvm_reg        regs[$];
+  uvm_reg_addr_t addr_min = '1, addr_max = 0;
+
+  if (m_layer_vseq_running) begin
+    `uvm_error(get_full_name(),
+               {"Adding a subordinate mapping will have no effect: ",
+                "the layered vseq is already running."})
+  end
+
+  // Update addr_min, addr_max so that the range addr_min..addr_max contains every register
+  // accessible through reg_map.
+  reg_map.get_registers(regs);
+  foreach (regs[i]) begin
+    uvm_reg_addr_t addr = regs[i].get_address(reg_map);
+    if (addr < addr_min) addr_min = addr;
+    if (addr_max < addr) addr_max = addr;
+  end
+
+  if (addr_min <= addr_max) begin
+    sub_addr_range_t rng;
+
+    rng.addr_min = addr_min;
+    rng.addr_max = addr_max;
+    rng.subordinate_idx = subordinate_idx;
+    m_subordinate_ranges.push_front(rng);
+  end
+endfunction
+
+function void ahb_mgr_agent::get_subordinate_ranges(ref sub_addr_range_t ranges[$]);
+  foreach (m_subordinate_ranges[i]) ranges.push_back(m_subordinate_ranges[i]);
+endfunction
+
+task ahb_mgr_agent::run_layered_register_vseq();
+  ahb_mgr_register_layer_vseq layer_vseq;
+
+  if (m_layer_vseq_running) begin
+    `uvm_error(get_full_name(), "Layered vseq already running.")
+    wait(0);
+  end
+  m_layer_vseq_running = 1;
+
+  layer_vseq = ahb_mgr_register_layer_vseq::type_id::create("layer_vseq");
+
+  layer_vseq.set_sequencers(m_layered_reg_sequencer, m_sequencer);
+  layer_vseq.set_subordinates(m_subordinate_ranges);
+  layer_vseq.set_has_hprot(m_vif.hprot_width != 0);
+
+  layer_vseq.start(null);
+
+  // Because layer_vseq never completes, we don't expect to get here.
+  `uvm_fatal(get_full_name(), "Instance of ahb_mgr_register_layer_vseq ran to completion.")
+endtask
+
+function ahb_mgr_agent::layered_reg_sequencer_t ahb_mgr_agent::get_register_layering_sequencer();
+  if (m_layered_reg_sequencer == null)
+    `uvm_fatal(get_full_name(), "m_layered_reg_sequencer is null.")
+
+  return m_layered_reg_sequencer;
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_mgr_driver.svh b/tools/dv-classes/ahb_agent/ahb_mgr_driver.svh
new file mode 100644
index 00000000..1bee1172
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_mgr_driver.svh
@@ -0,0 +1,436 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A driver for ahb_if, used when the testbench is acting as an AHB Manager that is requesting
+// transactions.
+//
+// The driver sends a response to every item, sending an ahb_status_item (with m_sending_complete=0)
+// if the transfer was interrupted by a reset and sending an ahb_txn_response_item with the bus
+// response otherwise.
+
+class ahb_mgr_driver extends uvm_driver#(ahb_txn_request_item, uvm_sequence_item);
+  `uvm_component_utils(ahb_mgr_driver)
+
+  local virtual ahb_if m_vif;
+
+  // True if the interface is currently in reset. Maintained by monitor_reset().
+  //
+  // At the very start of the simulation, rst_ni might be 'x or 'z. This isn't considered a "proper"
+  // reset: in_reset can only be asserted by seeing rst_ni === 0 (and then cleared by seeing it
+  // become 1).
+  local bit m_in_reset;
+
+  // If not null, cur_addr_phase is an item whose address phase was driven on the last clock edge.
+  local ahb_txn_request_item m_cur_addr_phase;
+
+  // If not null, cur_data_phase is an item whose data phase was driven on the last clock edge.
+  local ahb_txn_request_item m_cur_data_phase;
+
+  extern function new(string name, uvm_component parent);
+  extern virtual task run_phase(uvm_phase phase);
+
+  // Set m_vif. This must be called before run_phase.
+  extern function void set_vif(virtual ahb_if vif);
+
+  // Run forever, consuming and driving items from seq_item_port
+  extern local task get_and_drive();
+
+  // Run forever, tracking rst_ni and maintaining an in_reset class variable. Calls clear_data when
+  // reset becomes asserted.
+  extern local task monitor_reset();
+
+  // Wait for one clock edge in host_cb, but stop early on a reset
+  extern local task wait_cb_or_reset();
+
+  // Handle interface updates on a clock edge
+  //
+  // If not null, next_item is an item whose address phase might be driven on the next clock edge
+  // (assuming there was not back-pressure exerted on the last cycle).
+  //
+  // The took_next_item output argument is asserted if the next_item argument has been taken as
+  // m_cur_addr_phase.
+  //
+  // This task will consume no simulated time (but needs to be a task because it calls set_hsel,
+  // set_address_phase_signals and set_data_phase_signals which, in turn, must be tasks because they
+  // set clocking block drives.
+  extern local task at_clock_edge(ahb_txn_request_item next_item, output bit took_next_item);
+
+  // Set the HSEL signal to match the set of items in m_cur_addr_phase.
+  //
+  // This task runs in zero time, but uses clocking block drives so cannot be a function.
+  extern local task set_hsel();
+
+  // Set the signals for the address phase for m_cur_addr_phase. If that is null, there is no
+  // address phase to send on this cycle (and the signals should be cleared).
+  //
+  // This task runs in zero time, but uses clocking block drives so cannot be a function.
+  //
+  // The task also checks any address against the ADDR_WIDTH property configured in the interface.
+  extern local task set_address_phase_signals();
+
+  // Set the signals for the data phase for m_cur_data_phase. If item is null, there is no data
+  // phase to send on this cycle (and the signals should be cleared).
+  //
+  // This task runs in zero time, but uses clocking block drives so cannot be a function.
+  //
+  // The task also checks data and strb fields against the DATA_WIDTH property configured in the
+  // interface.
+  extern local task set_data_phase_signals();
+
+  // A task that is called at the start of a reset and also at the end of driving an item.
+  extern local task clear_data();
+
+  // Send a status item response to the given request item
+  //
+  // Because this driver only sends ahb_status_item items when a transaction has been aborted, this
+  // function knows enough to create the item as well.
+  extern local function void send_status_item_rsp(ahb_txn_request_item req_item);
+
+  // Send a status item response (using send_status_item_rsp) for any of m_cur_data_phase,
+  // m_cur_addr_phase and next_item that is not null, then clear both class variables to null.
+  extern local function void send_status_item_rsp_triple(ahb_txn_request_item next_item);
+
+  // Create and send an ahb_txn_response_item based on the signals on the interface if there is an
+  // item currently running its data phase (and thus m_cur_data_phase is not null).
+  //
+  // If there was an item that got a response, this also clears m_cur_data_phase.
+  extern local function void read_and_send_response();
+endclass
+
+function ahb_mgr_driver::new(string name, uvm_component parent);
+  super.new(name, parent);
+endfunction
+
+function void ahb_mgr_driver::set_vif(virtual ahb_if vif);
+  if (m_vif != null) begin
+    `uvm_fatal(get_full_name(), "Cannot call set_vif: there is already an interface.")
+    return;
+  end
+  m_vif = vif;
+endfunction
+
+task ahb_mgr_driver::run_phase(uvm_phase phase);
+  if (m_vif == null) begin
+    `uvm_fatal(get_full_name(), "Cannot drive interface: vif is null.")
+    return;
+  end
+
+  if (m_vif.if_mode != dv_utils_pkg::Host) begin
+    `uvm_warning(get_full_name(),
+                 $sformatf("Driving interface will have no effect: if_mode is %0s",
+                           m_vif.if_mode.name()))
+  end
+
+  // Start by clearing the data (and, importantly, setting m_vif.host_cb.hsel = '0). From now, hsel
+  // will be zero unless $isunknown on all the other fields is false.
+  clear_data();
+
+  fork
+    get_and_drive();
+    monitor_reset();
+  join
+endtask
+
+task ahb_mgr_driver::at_clock_edge(ahb_txn_request_item next_item,
+                                   output bit           took_next_item);
+  bit paused;
+
+  if (m_cur_data_phase != null) begin
+    // If cur_data_phase is not null, that item was being driven on the last clock edge. Was it
+    // accepted by the subordinate?
+    if (!m_vif.host_cb.hready) begin
+      // Because the subordinate was not ready, the item wasn't accepted by the subordinate and no
+      // transaction happened.
+      paused = 1;
+    end else begin
+      // Because the subordinate *was* ready, the item was accepted. Call read_and_send_response,
+      // which will read a response to the non-null m_cur_data_phase item, then clear that variable.
+      read_and_send_response();
+    end
+  end
+
+  // If paused is true, nothing happened. Leave the signals driven as before and return, setting
+  // took_next_item=0 to tell the caller that it wasn't taken.
+  if (paused) begin
+    took_next_item = 0;
+    return;
+  end
+
+  // At this point m_cur_data_phase is null. Move m_cur_addr_phase into m_cur_data_phase.
+  m_cur_data_phase = m_cur_addr_phase;
+  m_cur_addr_phase = null;
+
+  // Can we drive the addr phase of next_item? We can only do so if next_item is not null and either
+  // m_cur_data_phase is null or has it the same m_subordinate_idx as next_item. If so, set
+  // m_cur_addr_phase to be next_item and set took_next_item = 1. If not, set took_next_item=0.
+  if (next_item != null &&
+      (m_cur_data_phase == null ||
+       m_cur_data_phase.m_subordinate_idx == next_item.m_subordinate_idx)) begin
+    m_cur_addr_phase = next_item;
+    took_next_item = 1;
+  end else begin
+    took_next_item = 0;
+  end
+
+  // Set hsel to match any items that are currently being driven (which will have the same
+  // m_subordinate_idx) and drive the address and data signals for the next clock edge
+  set_hsel();
+  set_address_phase_signals();
+  set_data_phase_signals();
+endtask
+
+
+task ahb_mgr_driver::get_and_drive();
+  ahb_txn_request_item next_item;
+
+  forever begin
+    // This flag is set by at_clock_edge if it consumed the item that was passed in its next_item
+    // argument (which will now be in m_cur_addr_phase). If that happens, we should clear next_item
+    // here.
+    bit took_next_item;
+
+    // This infinite loop always runs from one clock edge to the next, stopping an iteration early
+    // on a reset.
+    //
+    // At the start of the loop, we are at a clock edge, where we have just set the
+    // address/data signals for either of m_cur_addr_phase and m_cur_data_phase that is not null.
+    //
+    // Wait until the next clock edge, stopping early if a reset is asserted.
+    wait_cb_or_reset();
+
+    // If we are in reset, call send_status_item_rsp_triple to send an empty response for any item
+    // that is currently non-nil and clear it. Then wait until there is something available in
+    // seq_item_port. Consume it and put it in next_item, then go around the loop again.
+    if (m_in_reset) begin
+      send_status_item_rsp_triple(next_item);
+      seq_item_port.get(next_item);
+      continue;
+    end
+
+    // At this point, we are at a clock edge. If one or both m_cur_addr_phase or m_cur_data_phase
+    // are non-null, they are items whose address or data phase signals were asserted on the last
+    // clock edge.
+    //
+    // If next_item is null, peek at the sequencer to see whether there is an item available to have
+    // its address phase driven from this clock edge.
+    if (next_item == null) begin
+      if (seq_item_port.has_do_available()) begin
+        seq_item_port.get(next_item);
+      end
+    end
+
+    // If next_item is null and m_cur_addr_phase and m_cur_data_phase are also null, we have no
+    // items at the moment. Wait until there is something in seq_item_port and then jump back to the
+    // start of the loop to align to the next clock edge.
+    if (next_item == null && m_cur_addr_phase == null && m_cur_data_phase == null) begin
+      seq_item_port.wait_for_sequences();
+      continue;
+    end
+
+    at_clock_edge(next_item, took_next_item);
+
+    if (took_next_item) begin
+      // If took_next_item is true then next_item will have just been copied to m_cur_addr_phase.
+      // Clear the next_item variable.
+      next_item = null;
+    end
+  end
+endtask
+
+task ahb_mgr_driver::monitor_reset();
+  wait(!$isunknown(m_vif.rst_ni));
+  m_in_reset = !m_vif.rst_ni;
+  forever begin
+    wait (m_vif.rst_ni);
+    m_in_reset = 0;
+    wait (!m_vif.rst_ni);
+    m_in_reset = 1;
+    clear_data();
+  end
+endtask
+
+task ahb_mgr_driver::wait_cb_or_reset();
+  fork : isolation_fork begin
+    fork
+      @(m_vif.host_cb);
+      wait(m_in_reset);
+    join_any
+    disable fork;
+  end join
+endtask
+
+task ahb_mgr_driver::set_hsel();
+  bit [7:0] hsel;
+
+  // If there is an item to send in the address phase, check that m_subordinate_idx is less than the
+  // num_subordinates value from the interface and then set hsel to match.
+  if (m_cur_addr_phase != null) begin
+    if (m_cur_addr_phase.m_subordinate_idx >= m_vif.num_subordinates) begin
+      `uvm_error(get_full_name(),
+                 $sformatf({"Cannot set hsel for m_subordinate_idx = %0d: ",
+                            "there are only %0d subordinates."},
+                           m_cur_addr_phase.m_subordinate_idx, m_vif.num_subordinates))
+    end
+    hsel = (8'd1 << m_cur_addr_phase.m_subordinate_idx);
+  end
+
+  // At this point, hsel will be onehot0. Set the signal in the interface to match.
+  m_vif.host_cb.hsel <= hsel;
+endtask
+
+task ahb_mgr_driver::set_address_phase_signals();
+  if (m_cur_addr_phase == null) begin
+    m_vif.host_cb.haddr     <= 'x;
+    m_vif.host_cb.hburst    <= 'x;
+    m_vif.host_cb.hmastlock <= 'x;
+    m_vif.host_cb.hprot     <= 'x;
+    m_vif.host_cb.hsize     <= 'x;
+    m_vif.host_cb.htrans    <= TransIdle;
+    m_vif.host_cb.hwrite    <= 'x;
+  end else begin
+    if (|(m_cur_addr_phase.m_addr >> m_vif.addr_width)) begin
+      `uvm_error(get_full_name(),
+                 $sformatf("Cannot represent m_addr = 0x%0h. The interface ADDR_WIDTH is %0d.",
+                           m_cur_addr_phase.m_addr, m_vif.addr_width))
+    end
+    if (|(m_cur_addr_phase.m_prot >> m_vif.hprot_width)) begin
+      `uvm_error(get_full_name(),
+                 $sformatf("Cannot represent m_prot = 0x%0h. The interface HPROT_WIDTH is %0d.",
+                           m_cur_addr_phase.m_prot, m_vif.hprot_width))
+    end
+
+    m_vif.host_cb.haddr     <= m_cur_addr_phase.m_addr;
+    m_vif.host_cb.hburst    <= m_cur_addr_phase.m_burst;
+    m_vif.host_cb.hmastlock <= m_cur_addr_phase.m_lock;
+    m_vif.host_cb.hprot     <= m_cur_addr_phase.m_prot;
+    m_vif.host_cb.hsize     <= m_cur_addr_phase.m_size;
+    m_vif.host_cb.htrans    <= m_cur_addr_phase.m_trans;
+    m_vif.host_cb.hwrite    <= m_cur_addr_phase.m_write;
+  end
+endtask
+
+task ahb_mgr_driver::set_data_phase_signals();
+  if (m_cur_data_phase == null) begin
+    m_vif.host_cb.hwstrb <= 'x;
+    m_vif.host_cb.hwdata <= 'x;
+  end else begin
+    int unsigned addr_mod_data_width = m_cur_data_phase.m_addr % (m_vif.data_width / 8);
+    bit [1023:0] shifted_wdata       = m_cur_data_phase.m_wdata << (addr_mod_data_width * 8);
+    bit [127:0]  shifted_wstrb       = m_cur_data_phase.m_wstrb << addr_mod_data_width;
+
+    if (m_cur_data_phase.m_write) begin
+      if (m_vif.data_width % 8) begin
+        `uvm_fatal(get_full_name(),
+                   $sformatf({"Cannot drive hwdata/hwstrb on the interface. ",
+                              "data_width is %0d which is not a whole number of bytes."},
+                             m_vif.data_width))
+      end
+
+      if (|(shifted_wdata >> m_vif.data_width)) begin
+        `uvm_error(get_full_name(),
+                   $sformatf({"Cannot represent m_wdata = 0x%0h with address 0x%0h. ",
+                              "The interface DATA_WIDTH is %0d, so m_wdata would be shifted by ",
+                              "8 * %0d to give 0x%0h in the %0d byte lanes."},
+                             m_cur_data_phase.m_wdata, m_cur_data_phase.m_addr,
+                             m_vif.data_width, addr_mod_data_width, shifted_wdata,
+                             m_vif.data_width / 8))
+      end
+
+      if (|(shifted_wstrb >> (m_vif.data_width / 8))) begin
+        `uvm_error(get_full_name(),
+                   $sformatf({"Cannot represent m_wstrb = 0x%0h with address 0x%0h. ",
+                              "The interface DATA_WIDTH is %0d, so m_wstrb would be shifted by ",
+                              "%0d to give 0x%0h in the %0d strobe bits."},
+                             m_cur_data_phase.m_wstrb, m_cur_data_phase.m_addr,
+                             m_vif.data_width, addr_mod_data_width, shifted_wstrb,
+                             m_vif.data_width / 8))
+      end
+
+      // If the interface has no HWSTRB signal, we want to generate an error if there is a
+      // complicated m_wstrb value. We don't want to require the value be constant though, because
+      // some code on the sequence side is easier to write if it calculates it from m_size and
+      // m_addr. Check that the portion of wstrb corresponding to the bytes from m_size and m_addr
+      // is constant.
+      if (!m_vif.has_write_strobes) begin
+        // m_size determines the number of bytes that are being sent (and should have constant wstrb
+        // bits). The byte lanes used can be inferred from the remainder of m_addr when divided by
+        // DATA_WIDTH/8.
+        bit [127:0]  strb_mask_for_size  = (1 << (1 << m_cur_data_phase.m_size)) - 1;
+        bit [127:0]  relevant_strb_mask  = strb_mask_for_size << (addr_mod_data_width);
+
+        if (shifted_wstrb != '0 && shifted_wstrb != relevant_strb_mask) begin
+          `uvm_error(get_full_name(),
+                     $sformatf({"Cannot represent m_wstrb = 0x%0h for an access with HSIZE = %0d ",
+                                "and HADDR = 0x%0h. Because Write_Strobes is false, there is no ",
+                                "HWSTRB signal. The size and addr imply a write strobe of 0x%0h. ",
+                                "After shifting by the address, the item's m_wstrb is 0x%0h, ",
+                                "which is nonzero but doesn't have all of the bits in the ",
+                                "implied HWSTRB."},
+                               m_cur_data_phase.m_wstrb,
+                               m_cur_data_phase.m_size,
+                               m_cur_data_phase.m_addr,
+                               relevant_strb_mask,
+                               shifted_wstrb))
+        end
+      end
+    end
+
+    m_vif.host_cb.hwstrb <= shifted_wstrb;
+    m_vif.host_cb.hwdata <= shifted_wdata;
+  end
+endtask
+
+task ahb_mgr_driver::clear_data();
+  m_vif.host_cb.hsel      <= '0;
+  m_vif.host_cb.haddr     <= 'x;
+  m_vif.host_cb.hburst    <= 'x;
+  m_vif.host_cb.hmastlock <= 'x;
+  m_vif.host_cb.hprot     <= 'x;
+  m_vif.host_cb.hsize     <= 'x;
+  m_vif.host_cb.htrans    <= TransIdle;
+  m_vif.host_cb.hwdata    <= 'x;
+  m_vif.host_cb.hwstrb    <= 'x;
+  m_vif.host_cb.hwrite    <= 'x;
+endtask
+
+function void ahb_mgr_driver::send_status_item_rsp(ahb_txn_request_item req_item);
+  ahb_status_item status_rsp = ahb_status_item::type_id::create("status_rsp");
+
+  status_rsp.set_id_info(req_item);
+  status_rsp.m_sending_complete = 0;
+
+  seq_item_port.put_response(status_rsp);
+endfunction
+
+function void ahb_mgr_driver::send_status_item_rsp_triple(ahb_txn_request_item next_item);
+  if (m_cur_data_phase != null) begin
+    send_status_item_rsp(m_cur_data_phase);
+    m_cur_data_phase = null;
+  end
+
+  if (m_cur_addr_phase != null) begin
+    send_status_item_rsp(m_cur_addr_phase);
+    m_cur_addr_phase = null;
+  end
+
+  if (next_item != null) begin
+    send_status_item_rsp(next_item);
+  end
+endfunction
+
+function void ahb_mgr_driver::read_and_send_response();
+  if (m_cur_data_phase != null) begin
+    ahb_txn_response_item rsp_item = ahb_txn_response_item::type_id::create("rsp_item");
+    int unsigned          addr_mod_data_width = m_cur_data_phase.m_addr % (m_vif.data_width / 8);
+
+    rsp_item.set_id_info(m_cur_data_phase);
+
+    rsp_item.m_rdata = m_vif.host_cb.hrdata_muxed >> (addr_mod_data_width * 8);
+    rsp_item.m_resp  = m_vif.host_cb.hresp_muxed;
+
+    seq_item_port.put_response(rsp_item);
+  end
+
+  m_cur_data_phase = null;
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_mgr_reg_adapter.svh b/tools/dv-classes/ahb_agent/ahb_mgr_reg_adapter.svh
new file mode 100644
index 00000000..f96a6739
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_mgr_reg_adapter.svh
@@ -0,0 +1,91 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// An extremely simple uvm_reg_adapter that wraps a uvm_reg_op in an ahb_reg_op_item or copies the
+// response fields back from that item.
+
+class ahb_mgr_reg_adapter extends uvm_reg_adapter;
+  `uvm_object_utils(ahb_mgr_reg_adapter)
+
+  extern function new(string name="");
+  extern function uvm_sequence_item reg2bus(const ref uvm_reg_bus_op rw);
+  extern function void bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
+
+  // The bus2reg function, specialised for ahb_reg_op_item items. This is used by the reg_map when
+  // making sense of responses from the layering virtual sequence.
+  extern local function void bus2reg_reg_op(ahb_reg_op_item bus_item, ref uvm_reg_bus_op rw);
+
+  // The bus2reg function, specialised for ahb_txn_item items. This is used by a uvm_reg_predictor
+  // when making sense of bus transactions from the monitor.
+  extern local function void bus2reg_txn(ahb_txn_item bus_item, ref uvm_reg_bus_op rw);
+endclass
+
+function ahb_mgr_reg_adapter::new(string name="");
+  super.new(name);
+
+  // Setting this to true means that the "bus driver" (here, ahb_mgr_register_layer_vseq) sends a
+  // response to the sequencer.
+  provides_responses   = 1;
+endfunction
+
+function uvm_sequence_item ahb_mgr_reg_adapter::reg2bus(const ref uvm_reg_bus_op rw);
+  ahb_reg_op_item bus_item = ahb_reg_op_item::type_id::create("bus_item");
+
+  // Take a copy of the uvm_reg_bus_op (which will be a deep copy because uvm_reg_bus_op is a
+  // struct)
+  bus_item.m_rw = rw;
+
+  return bus_item;
+endfunction
+
+function void ahb_mgr_reg_adapter::bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
+  ahb_reg_op_item reg_op_bus_item;
+  ahb_txn_item    txn_item;
+
+  if ($cast(reg_op_bus_item, bus_item)) begin
+    bus2reg_reg_op(reg_op_bus_item, rw);
+  end else if ($cast(txn_item, bus_item)) begin
+    bus2reg_txn(txn_item, rw);
+  end else begin
+    `uvm_fatal(get_name(), "Cannot convert bus item to an ahb_reg_op_item or ahb_txn_item.")
+  end
+endfunction
+
+function void ahb_mgr_reg_adapter::bus2reg_reg_op(ahb_reg_op_item bus_item, ref uvm_reg_bus_op rw);
+  // Replace all the fields in rw that bus2reg would normally populate (kind, addr, data and status)
+  rw.kind = bus_item.m_rw.kind;
+  rw.addr = bus_item.m_rw.addr;
+  rw.data = bus_item.m_rw.data;
+  rw.status = bus_item.m_rw.status;
+endfunction
+
+function void ahb_mgr_reg_adapter::bus2reg_txn(ahb_txn_item bus_item, ref uvm_reg_bus_op rw);
+  // We only need to understand read vs. write, but it probably makes sense to do this extra sanity
+  // check: the ahb_monitor shouldn't have created an ahb_txn_item if the manager sent HTRANS that
+  // was TransIdle or TransBusy.
+  if (! (bus_item.m_request.m_trans inside {TransNonSequential, TransSequential})) begin
+    `uvm_error("bus2reg_txn",
+               $sformatf({"Unexpected m_trans for bus item: ",
+                          "%0d is not TransNonSequential or TransSequential."},
+                         bus_item.m_request.m_trans))
+  end
+
+  rw.kind   = bus_item.m_request.m_write ? UVM_WRITE : UVM_READ;
+  rw.addr   = bus_item.m_request.m_addr;
+  rw.n_bits = (8 << bus_item.m_request.m_size);
+
+  if (bus_item.m_request.m_write) begin
+    rw.byte_en = bus_item.m_request.m_wstrb;
+    rw.data    = bus_item.m_request.m_wdata;
+  end else begin
+    // AHB doesn't define a read strobe, so set it equal to all bytes available for a transaction of
+    // width 1 << HSIZE bytes.
+    rw.byte_en = (128'd1 << (1 << bus_item.m_request.m_size)) - 1;
+
+    if (bus_item.m_response == null) rw.data = 0;
+    else rw.data = bus_item.m_response.m_rdata;
+  end
+
+  rw.status = (bus_item.m_response == null || bus_item.m_response.m_resp) ? UVM_NOT_OK : UVM_IS_OK;
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_monitor.svh b/tools/dv-classes/ahb_agent/ahb_monitor.svh
new file mode 100644
index 00000000..ff00a543
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_monitor.svh
@@ -0,0 +1,172 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A monitor that watches an AHB interface
+
+class ahb_monitor extends uvm_monitor;
+  `uvm_component_utils(ahb_monitor)
+
+  // The interface being tracked. Set this with set_vif().
+  local virtual ahb_if m_vif;
+
+  // This event gets triggered when the monitor sees a reset. Structuring it like this (instead of
+  // waiting on m_vif.rst_ni in watch_until_reset) simulates dramatically more quickly.
+  local uvm_event saw_reset;
+
+  // The analysis ports for requests, responses and complete transactions.
+  uvm_analysis_port #(ahb_txn_request_item)  m_request_port;
+  uvm_analysis_port #(ahb_txn_response_item) m_response_port;
+  uvm_analysis_port #(ahb_txn_item)          m_transaction_port;
+
+  extern function new(string name, uvm_component parent);
+  extern function void build_phase (uvm_phase phase);
+  extern task run_phase(uvm_phase phase);
+
+  // Set the interface that is being tracked
+  extern function void set_vif(virtual ahb_if vif);
+
+  // Track requests and responses on m_vif
+  extern local task watch_interface();
+
+  // Track requests and responses on m_vif, leaving early if reset is asserted
+  extern local task watch_until_reset();
+endclass
+
+function ahb_monitor::new(string name, uvm_component parent);
+  super.new(name, parent);
+  saw_reset = new("saw_reset");
+endfunction
+
+function void ahb_monitor::build_phase(uvm_phase phase);
+  super.build_phase(phase);
+
+  m_request_port = new("m_request_port", this);
+  m_response_port = new("m_response_port", this);
+  m_transaction_port = new("m_transaction_port", this);
+
+  if (m_vif == null && !uvm_config_db#(virtual ahb_if)::get(this, "", "vif", m_vif)) begin
+    `uvm_fatal(get_full_name(), "Interface neither supplied with set_vif nor with uvm_config_db.")
+  end
+endfunction
+
+task ahb_monitor::run_phase(uvm_phase phase);
+  fork
+    super.run_phase(phase);
+    watch_interface();
+    forever begin
+      wait(m_vif.rst_ni === 1'b1);
+      wait(m_vif.rst_ni !== 1'b1);
+      saw_reset.trigger();
+    end
+  join
+endtask
+
+function void ahb_monitor::set_vif(virtual ahb_if vif);
+  m_vif = vif;
+endfunction
+
+task ahb_monitor::watch_interface();
+  forever begin
+    wait(m_vif.rst_ni === 1'b1);
+    watch_until_reset();
+
+    // Check that there really has been a reset (to ensure the loop iterations take a positive
+    // amount of time)
+    if (m_vif.rst_ni === 1'b1) `uvm_fatal(get_full_name(), "watch_until_reset exited early")
+  end
+endtask
+
+task ahb_monitor::watch_until_reset();
+  // A non-Idle request that has been seen. This is generated when we see a request being sent
+  // (because there is no back pressure from the response side).
+  ahb_txn_request_item req_item;
+
+  forever begin
+    // Wait until the observed region of a time slot where there is a positive clock edge, or drop
+    // out early if there is a reset asserted.
+    fork begin : isolation_fork
+      fork
+        @(m_vif.mon_cb);
+        saw_reset.wait_ptrigger();
+      join_any
+      disable fork;
+    end join
+
+    if (m_vif.rst_ni !== 1'b1) begin
+      // If req_item is not null, there was a transaction in flight that didn't get a response. Send
+      // the partial transaction.
+      if (req_item != null) begin
+        ahb_txn_item txn_item = ahb_txn_item::type_id::create("txn_item");
+        txn_item.m_request = req_item;
+        m_transaction_port.write(txn_item);
+      end
+      return;
+    end
+
+    // Has a request been sent? If so, the subordinate has the opportunity to generate a response.
+    if (req_item != null) begin
+      ahb_txn_response_item rsp_item;
+      ahb_txn_item          txn_item;
+
+      // Infer an appropriate hwstrb value to use for the item if m_vif.has_write_strobes is false.
+      int unsigned addr_mod_data_width  = req_item.m_addr % (m_vif.data_width / 8);
+      int unsigned selected_idx         = req_item.m_subordinate_idx;
+      bit [127:0]  wstrb_from_size0     = (1 << (1 << req_item.m_size)) - 1;
+      bit [127:0]  wstrb_from_size_addr = wstrb_from_size0 << addr_mod_data_width;
+      bit [127:0]  observed_wstrb;
+
+      // If the appropriate hreadyout signal is low, the subordinate is applying back pressure and
+      // there is no transfer on this cycle. Go round the loop again.
+      if (m_vif.mon_cb.hreadyout[selected_idx] !== 1'b1) continue;
+
+      // The wstrb value might not actually be signalled on the bus if m_vif.has_write_strobes is
+      // false. In that case, infer a write strobe from hsize.
+      observed_wstrb = m_vif.has_write_strobes ? m_vif.mon_cb.hwstrb : wstrb_from_size_addr;
+
+      // If the transfer is a write, the data phase will have write data from the manager. Add this
+      // to req_item.
+      req_item.m_wdata = m_vif.mon_cb.hwdata >> (8 * addr_mod_data_width);
+      req_item.m_wstrb = (observed_wstrb >> addr_mod_data_width);
+
+      // Make a response item, then pair it up with the request, sending the response and the pair
+      // on their respective analysis ports.
+      rsp_item = ahb_txn_response_item::type_id::create("rsp_item");
+      rsp_item.m_rdata = m_vif.mon_cb.hrdata[selected_idx] >> (8 * addr_mod_data_width);
+      rsp_item.m_resp  = m_vif.mon_cb.hresp[selected_idx];
+      m_response_port.write(rsp_item);
+
+      txn_item = ahb_txn_item::type_id::create("txn_item");
+      txn_item.m_request = req_item;
+      txn_item.m_response = rsp_item;
+      m_transaction_port.write(txn_item);
+
+      req_item = null;
+    end
+
+    // If we get here then there was either no pending request or there was a request that has had a
+    // response. If the manager is asserting a NONSEQ or SEQ request for some subordinate now,
+    // create an item to represent it.
+    if (|m_vif.mon_cb.hsel &&
+        m_vif.mon_cb.htrans inside {TransNonSequential, TransSequential}) begin
+      if (!$onehot(m_vif.mon_cb.hsel)) begin
+        `uvm_error(get_full_name(),
+                   $sformatf("hsel signal for a request is not one-hot (hsel = 0x%0h)",
+                             m_vif.mon_cb.hsel))
+        continue;
+      end
+
+      req_item = ahb_txn_request_item::type_id::create("req_item");
+
+      req_item.m_subordinate_idx = $clog2(m_vif.mon_cb.hsel);
+      req_item.m_addr = m_vif.mon_cb.haddr;
+      req_item.m_burst = burst_e'(m_vif.mon_cb.hburst);
+      req_item.m_lock = m_vif.mon_cb.hmastlock;
+      req_item.m_prot = m_vif.mon_cb.hprot;
+      req_item.m_size = m_vif.mon_cb.hsize;
+      req_item.m_trans = trans_e'(m_vif.mon_cb.htrans);
+      req_item.m_write = m_vif.mon_cb.hwrite;
+      m_request_port.write(req_item);
+    end
+  end
+endtask
diff --git a/tools/dv-classes/ahb_agent/ahb_reg_op_item.svh b/tools/dv-classes/ahb_agent/ahb_reg_op_item.svh
new file mode 100644
index 00000000..b4f80b7b
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_reg_op_item.svh
@@ -0,0 +1,65 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A simple uvm_sequence_item that holds a uvm_reg_bus_op and can be passed to the sequencer in
+// ahb_mgr_register_layer_vseq.
+
+class ahb_reg_op_item extends uvm_sequence_item;
+  `uvm_object_utils(ahb_reg_op_item)
+
+  // The wrapped uvm_reg_bus_op
+  uvm_reg_bus_op m_rw;
+
+  extern function new(string name = "");
+  extern function void do_print(uvm_printer printer);
+  extern function void do_copy(uvm_object rhs);
+  extern function bit do_compare(uvm_object rhs, uvm_comparer comparer);
+endclass
+
+function ahb_reg_op_item::new(string name="");
+  super.new(name);
+endfunction
+
+function void ahb_reg_op_item::do_print(uvm_printer printer);
+  super.do_print(printer);
+  printer.print_string("m_rw.kind", m_rw.kind.name());
+  printer.print_field("m_rw.addr", m_rw.addr, `UVM_REG_ADDR_WIDTH, UVM_HEX);
+  printer.print_field("m_rw.data", m_rw.data, `UVM_REG_DATA_WIDTH, UVM_HEX);
+  printer.print_field_int("m_rw.n_bits", m_rw.n_bits, 32, UVM_DEC);
+  printer.print_field("m_rw.byte_en", m_rw.byte_en, `UVM_REG_BYTENABLE_WIDTH, UVM_HEX);
+  printer.print_string("m_rw.status", m_rw.status.name());
+endfunction
+
+function void ahb_reg_op_item::do_copy(uvm_object rhs);
+  ahb_reg_op_item rhs_;
+
+  if (rhs == null) `uvm_fatal("do_copy", "Cannot copy from RHS: it is null.")
+  if (!$cast(rhs_, rhs)) `uvm_fatal("do_copy", "Cannot cast RHS: wrong type?")
+
+  super.do_copy(rhs);
+  m_rw = rhs_.m_rw;
+endfunction
+
+function bit ahb_reg_op_item::do_compare(uvm_object rhs, uvm_comparer comparer);
+  ahb_reg_op_item rhs_;
+
+  // These items are only equivalent if rhs is actually an ahb_reg_op_item.
+  if (rhs == null || !$cast(rhs_, rhs)) begin
+    comparer.print_msg("RHS is null or is not an ahb_reg_op_item.");
+    return 0;
+  end
+
+  return (super.do_compare(rhs, comparer) &
+          comparer.compare_field_int("m_rw.kind", m_rw.kind, rhs_.m_rw.kind,
+                                     $bits(m_rw.kind), UVM_HEX) &
+          comparer.compare_field("m_rw.addr", m_rw.addr, rhs_.m_rw.addr,
+                                 `UVM_REG_ADDR_WIDTH, UVM_HEX) &
+          comparer.compare_field("m_rw.data", m_rw.data, rhs_.m_rw.data,
+                                 `UVM_REG_DATA_WIDTH, UVM_HEX) &
+          comparer.compare_field_int("m_rw.n_bits", m_rw.n_bits, rhs_.m_rw.n_bits, 32, UVM_DEC) &
+          comparer.compare_field("m_rw.byte_en", m_rw.byte_en, rhs_.m_rw.byte_en,
+                                 `UVM_REG_BYTENABLE_WIDTH, UVM_HEX) &
+          comparer.compare_field_int("m_rw.status", m_rw.status, rhs_.m_rw.status,
+                                     $bits(m_rw.status), UVM_HEX));
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_status_item.svh b/tools/dv-classes/ahb_agent/ahb_status_item.svh
new file mode 100644
index 00000000..eef64fa1
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_status_item.svh
@@ -0,0 +1,54 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A sequence item is sent back by drivers to show whether an item has actually been sent
+
+class ahb_status_item extends uvm_sequence_item;
+  `uvm_object_utils(ahb_status_item)
+
+  // If this bit is set then the driver that was sending an item (and is responding with this one)
+  // has finished sending the item.
+  //
+  // If the driver was interrupted by a reset, this bit will be clear.
+  bit m_sending_complete;
+
+  extern function new(string name = "");
+  extern function void do_print(uvm_printer printer);
+  extern function void do_copy(uvm_object rhs);
+  extern function bit do_compare(uvm_object rhs, uvm_comparer comparer);
+endclass
+
+function ahb_status_item::new(string name = "");
+  super.new(name);
+endfunction
+
+function void ahb_status_item::do_print(uvm_printer printer);
+  super.do_print(printer);
+  printer.print_field_int("m_sending_complete", m_sending_complete, 1, UVM_BIN);
+endfunction
+
+function void ahb_status_item::do_copy(uvm_object rhs);
+  ahb_status_item rhs_;
+
+  if (rhs == null) `uvm_fatal("do_copy", "Cannot copy from RHS: it is null.")
+  if (!$cast(rhs_, rhs)) `uvm_fatal("do_copy", "Cannot cast RHS: wrong type?")
+
+  super.do_copy(rhs);
+
+  m_sending_complete = rhs_.m_sending_complete;
+endfunction
+
+function bit ahb_status_item::do_compare(uvm_object rhs, uvm_comparer comparer);
+  ahb_status_item rhs_;
+
+  // These items are only equivalent if rhs is actually an ahb_status_item.
+  if (rhs == null || !$cast(rhs_, rhs)) begin
+    comparer.print_msg("RHS is null or is not an ahb_status_item.");
+    return 0;
+  end
+
+  return (super.do_compare(rhs, comparer) &
+          comparer.compare_field_int("m_sending_complete",
+                                     m_sending_complete, rhs_.m_sending_complete, 1, UVM_BIN));
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_txn_item.svh b/tools/dv-classes/ahb_agent/ahb_txn_item.svh
new file mode 100644
index 00000000..56b74fdb
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_txn_item.svh
@@ -0,0 +1,64 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A sequence item that represents an entire transaction (with a request and then a response)
+
+class ahb_txn_item extends uvm_sequence_item;
+  `uvm_object_utils(ahb_txn_item)
+
+  // The request in the transaction.
+  ahb_txn_request_item  m_request;
+
+  // The response in the transaction. This might be null, if the monitor saw a reset before a
+  // response had come back.
+  ahb_txn_response_item m_response;
+
+  extern function new(string name="");
+  extern function void do_print(uvm_printer printer);
+  extern function void do_copy(uvm_object rhs);
+  extern function bit do_compare(uvm_object rhs, uvm_comparer comparer);
+endclass
+
+function ahb_txn_item::new(string name="");
+  super.new(name);
+endfunction
+
+function void ahb_txn_item::do_print(uvm_printer printer);
+  super.do_print(printer);
+  printer.print_object("m_request", m_request);
+  printer.print_object("m_response", m_response);
+endfunction
+
+function void ahb_txn_item::do_copy(uvm_object rhs);
+  ahb_txn_item rhs_;
+
+  if (rhs == null) `uvm_fatal("do_copy", "Cannot copy from RHS: it is null.")
+  if (!$cast(rhs_, rhs)) `uvm_fatal("do_copy", "Cannot cast RHS: wrong type?")
+
+  super.do_copy(rhs);
+
+  if (rhs_.m_request == null) m_request = null;
+  else if (!$cast(m_request, rhs_.m_request.clone())) begin
+    `uvm_fatal("do_copy", "Failed to clone m_request.")
+  end
+  
+  if (rhs_.m_response == null) m_response = null;
+  else if (!$cast(m_response, rhs_.m_response.clone())) begin
+    `uvm_fatal("do_copy", "Failed to clone m_response.")
+  end
+endfunction
+
+function bit ahb_txn_item::do_compare(uvm_object rhs, uvm_comparer comparer);
+  ahb_txn_item rhs_;
+
+  // These items are only equivalent if rhs is actually an ahb_txn_item.
+  if (rhs == null || !$cast(rhs_, rhs)) begin
+    comparer.print_msg("RHS is null or is not an ahb_txn_item.");
+    return 0;
+  end
+
+  return (super.do_compare(rhs, comparer) &
+          comparer.compare_object("m_request", m_request, rhs_.m_request) &
+          comparer.compare_object("m_response", m_response, rhs_.m_response));
+endfunction
diff --git a/tools/dv-classes/ahb_agent/ahb_txn_request_item.svh b/tools/dv-classes/ahb_agent/ahb_txn_request_item.svh
new file mode 100644
index 00000000..3d1ab100
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_txn_request_item.svh
@@ -0,0 +1,194 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A sequence item that represents a message sent by an AHB Manager to request a read or write
+// transaction.
+//
+// This is a single transfer (sent in the address phase of one cycle). A burst will contain multiple
+// transfers, represented by multiple items of this class.
+
+class ahb_txn_request_item extends uvm_sequence_item;
+  `uvm_object_utils(ahb_txn_request_item)
+
+  // The index of the subordinate to select
+  //
+  // This will be sent over the HSEL signal and the maximum value is configurable, based on the
+  // num_subordinates parameter in the interface. The driver will fail with an error if the index is
+  // too high.
+  rand int unsigned m_subordinate_idx;
+
+  // Transaction address
+  //
+  // This is sent over the HADDR signal, whose width is configurable, based on the ADDR_WIDTH
+  // property. The representation in the item uses a max footprint approach (based on the
+  // recommended 10..64 range from the AHB specification, issue C) but the driver will fail with an
+  // error if bits above the configured width are nonzero.
+  rand bit [63:0]   m_addr;
+
+  // Burst attribute
+  rand burst_e      m_burst;
+
+  // Request exclusive access
+  rand bit          m_lock;
+
+  // Protection control
+  //
+  // This is sent over the HPROT signal, whose width is configurable, based on the HPROT_WIDTH
+  // property, which the AHB specification (issue C) requires to be 0, 4 or 7. The driver will fail
+  // with an error if bits above the configured width are nonzero.
+  rand bit [6:0]    m_prot;
+
+  // The size of each data transfer (encoded as log2(byte_size))
+  //
+  // The resulting byte size must be compatible with the width of the HWDATA signal, which is based
+  // on the DATA_WIDTH property. If this value is too large for the interface's DATA_WIDTH, the
+  // transfer might not work properly (but the driver will accept it: HSIZE will still be
+  // representable).
+  rand bit [2:0]    m_size;
+
+  // Transfer type
+  rand trans_e      m_trans;
+
+  // Write data (used when m_write is true)
+  //
+  // Note that (unlike the HWDATA signal), the bottom bit of the access is in the LSB of this field.
+  // The driver and monitor are responsible for shifting to the correct byte lane for DATA_WIDTH.
+  // For example, if 0x12 is being written to address 0x1, m_wdata will be 0x12 rather than 0x1200.
+  //
+  // This is sent over the HWDATA signal, whose width is configurable based on the DATA_WIDTH
+  // property. The representation in the item uses a max footprint approach, supporting up to 1024
+  // bits: the maximum size from the AHB specification (issue C). The driver will fail with an error
+  // if bits above the configured width are nonzero.
+  rand bit [1023:0] m_wdata;
+
+  // Write strobe (used when m_write is true)
+  //
+  // Note that (unlike the HWSTRB signal), the bottom bit of the access is in the LSB of this field.
+  // The driver and monitor are responsible for shifting to the correct byte lane for DATA_WIDTH.
+  // For example, if 0x12 is being written to address 0x1 and only a single strobe bit is asserted,
+  // m_wstrb will be 'b1 rather than 'b10.
+  //
+  // This is sent over the HWSTRB signal, which is only present in the interface if the
+  // Write_Strobes property is true and (if so) whose width is configurable based on the DATA_WIDTH
+  // property. The representation in the item uses a max footprint approach, supporting up to 128
+  // strobe bits: the maximum size from the AHB specification (issue C). The driver will fail with
+  // an error if bits above the configured width are nonzero.
+  rand bit [127:0]  m_wstrb;
+
+  // Transfer direction (true if this is a write)
+  rand bit          m_write;
+
+  extern function new(string name = "");
+  extern function void do_print(uvm_printer printer);
+  extern function void do_copy(uvm_object rhs);
+  extern function bit do_compare(uvm_object rhs, uvm_comparer comparer);
+
+  // Confine m_subordinate_idx to be bounded by the biggest value supported by the driver. The
+  // constraint might be tighter (depending on num_subordinates in the interface), but this
+  // constraint definitely applies.
+  extern constraint max_subordinate_idx_c;
+
+  // The transfer must be naturally aligned
+  extern constraint naturally_aligned_c;
+
+  // If this is a write, m_wdata must be representable with 1 << m_size bytes.
+  extern constraint write_size_c;
+
+  // If this is a write, m_wstrb must be representable with 1 << m_size bits.
+  extern constraint strb_size_c;
+endclass
+
+function ahb_txn_request_item::new(string name = "");
+  super.new(name);
+endfunction
+
+function void ahb_txn_request_item::do_print(uvm_printer printer);
+  super.do_print(printer);
+  printer.print_field_int("m_subordinate_idx", m_subordinate_idx, 32, UVM_DEC);
+  printer.print_field("m_addr", m_addr, 64, UVM_HEX);
+  printer.print_string("m_burst", m_burst.name());
+  printer.print_field_int("m_lock", m_lock, 1, UVM_BIN);
+  printer.print_field_int("m_prot", m_prot, 7, UVM_DEC);
+  printer.print_field_int("m_size", m_size, 3, UVM_DEC);
+  printer.print_string("m_trans", m_trans.name());
+  if (m_write) begin
+    printer.print_field("m_wdata", m_wdata, 1024, UVM_HEX);
+    printer.print_field("m_wstrb", m_wstrb, 128, UVM_HEX);
+  end
+  printer.print_field_int("m_write", m_write, 1, UVM_BIN);
+endfunction
+
+function void ahb_txn_request_item::do_copy(uvm_object rhs);
+  ahb_txn_request_item rhs_;
+  if (rhs == null) `uvm_fatal("do_copy", "Cannot copy from RHS: it is null.")
+  if (!$cast(rhs_, rhs)) `uvm_fatal("do_copy", "Cannot cast RHS: wrong type?")
+
+  super.do_copy(rhs);
+  this.m_subordinate_idx = rhs_.m_subordinate_idx;
+  this.m_addr            = rhs_.m_addr;
+  this.m_burst           = rhs_.m_burst;
+  this.m_lock            = rhs_.m_lock;
+  this.m_prot            = rhs_.m_prot;
+  this.m_size            = rhs_.m_size;
+  this.m_trans           = rhs_.m_trans;
+  this.m_wdata           = rhs_.m_wdata;
+  this.m_wstrb           = rhs_.m_wstrb;
+  this.m_write           = rhs_.m_write;
+endfunction
+
+function bit ahb_txn_request_item::do_compare(uvm_object rhs, uvm_comparer comparer);
+  ahb_txn_request_item rhs_;
+  bit all_match;
+
+  // These items are only equivalent if rhs is actually an ahb_txn_request_item.
+  if (rhs == null || !$cast(rhs_, rhs)) begin
+    comparer.print_msg("RHS is null or is not an ahb_txn_request_item.");
+    return 0;
+  end
+
+  // Note: The rather imperative code structure for the rest of this function ensures we only
+  // compare fields that matter (so don't compare wdata for reads) and that we do the comparisons in
+  // the order in the specification. This means that mismatches will be listed in the same order as
+  // that document.
+
+  all_match = super.do_compare(rhs, comparer);
+  all_match &= comparer.compare_field_int("m_subordinate_idx",
+                                          m_subordinate_idx, rhs_.m_subordinate_idx,
+                                          32, UVM_DEC);
+  all_match &= comparer.compare_field("m_addr", m_addr, rhs_.m_addr, 64, UVM_HEX);
+  all_match &= comparer.compare_field_int("m_burst", m_burst, rhs_.m_burst, 3, UVM_ENUM);
+  all_match &= comparer.compare_field_int("m_lock", m_lock, rhs_.m_lock, 1, UVM_BIN);
+  all_match &= comparer.compare_field_int("m_prot", m_prot, rhs_.m_prot, 7, UVM_DEC);
+  all_match &= comparer.compare_field_int("m_size", m_size, rhs_.m_size, 3, UVM_DEC);
+  all_match &= comparer.compare_field_int("m_trans", m_trans, rhs_.m_trans, 2, UVM_ENUM);
+
+  if (m_write || rhs_.m_write) begin
+    all_match &= comparer.compare_field("m_wdata", m_wdata, rhs_.m_wdata, 1024, UVM_HEX);
+    all_match &= comparer.compare_field("m_wstrb", m_wstrb, rhs_.m_wstrb, 128, UVM_HEX);
+  end
+
+  all_match &= comparer.compare_field_int("m_write", m_write, rhs_.m_write, 1, UVM_BIN);
+
+  return all_match;
+endfunction
+
+constraint ahb_txn_request_item::max_subordinate_idx_c {
+  m_subordinate_idx < 8;
+}
+
+constraint ahb_txn_request_item::naturally_aligned_c {
+  (m_addr & ((1 << m_size) - 1)) == 0;
+}
+
+constraint ahb_txn_request_item::write_size_c {
+  if (m_write) {
+    (m_wdata >> (8 << m_size)) == '0;
+  }
+}
+
+constraint ahb_txn_request_item::strb_size_c {
+  if (m_write) {
+    (m_wstrb >> (1 << m_size)) == '0;
+  }
+}
diff --git a/tools/dv-classes/ahb_agent/ahb_txn_response_item.svh b/tools/dv-classes/ahb_agent/ahb_txn_response_item.svh
new file mode 100644
index 00000000..22bce814
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/ahb_txn_response_item.svh
@@ -0,0 +1,66 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// A sequence item that represents a message sent by an AHB Subordinate to respond to a read or
+// write transaction.
+
+class ahb_txn_response_item extends uvm_sequence_item;
+  `uvm_object_utils(ahb_txn_response_item)
+
+  // Read data (used when responding to a read)
+  //
+  // Note that (unlike the HRDATA signal), the bottom bit of the access is in the LSB of this field.
+  // The driver and monitor are responsible for shifting to the correct byte lane for DATA_WIDTH.
+  // For example, if 0x12 is being read from address 0x1, m_rdata will be 0x12 rather than 0x1200.
+  //
+  // This is sent over the HRDATA signal, whose width is configurable based on the DATA_WIDTH
+  // property. The representation in the item uses a max footprint approach, supporting up to 1024
+  // bits: the maximum size from the AHB specification (issue C). The driver will fail with an error
+  // if bits above the configured width are nonzero.
+  rand bit [1023:0] m_rdata;
+
+  // Transfer response
+  //
+  // This bit is high if the transfer status is ERROR.
+  rand bit          m_resp;
+
+  extern function new(string name = "");
+  extern function void do_print(uvm_printer printer);
+  extern function void do_copy(uvm_object rhs);
+  extern function bit do_compare(uvm_object rhs, uvm_comparer comparer);
+endclass
+
+function ahb_txn_response_item::new(string name = "");
+  super.new(name);
+endfunction
+
+function void ahb_txn_response_item::do_print(uvm_printer printer);
+  super.do_print(printer);
+  printer.print_field("m_rdata", m_rdata, 1024, UVM_HEX);
+  printer.print_field_int("m_resp", m_resp, 1, UVM_BIN);
+endfunction
+
+function void ahb_txn_response_item::do_copy(uvm_object rhs);
+  ahb_txn_response_item rhs_;
+  if (rhs == null) `uvm_fatal("do_copy", "Cannot copy from RHS: it is null.")
+  if (!$cast(rhs_, rhs)) `uvm_fatal("do_copy", "Cannot cast RHS: wrong type?")
+
+  super.do_copy(rhs);
+  this.m_rdata = rhs_.m_rdata;
+  this.m_resp  = rhs_.m_resp;
+endfunction
+
+function bit ahb_txn_response_item::do_compare(uvm_object rhs, uvm_comparer comparer);
+  ahb_txn_response_item rhs_;
+
+  // These items are only equivalent if rhs is actually an ahb_txn_response_item.
+  if (rhs == null || !$cast(rhs_, rhs)) begin
+    comparer.print_msg("RHS is null or is not an ahb_txn_response_item.");
+    return 0;
+  end
+
+  return (super.do_compare(rhs, comparer) &
+          comparer.compare_field("m_rdata", m_rdata, rhs_.m_rdata, 1024, UVM_HEX) &
+          comparer.compare_field_int("m_resp", m_resp, rhs_.m_resp, 1, UVM_BIN));
+endfunction
diff --git a/tools/dv-classes/ahb_agent/seq_lib/ahb_mgr_register_layer_vseq.svh b/tools/dv-classes/ahb_agent/seq_lib/ahb_mgr_register_layer_vseq.svh
new file mode 100644
index 00000000..e13f43aa
--- /dev/null
+++ b/tools/dv-classes/ahb_agent/seq_lib/ahb_mgr_register_layer_vseq.svh
@@ -0,0 +1,229 @@
+// Copyright lowRISC contributors
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// This is a register layering virtual sequence. It consumes ahb_reg_op_item objects from a
+// sequencer and uses each to trigger a sequence on the AHB channel.
+//
+// It is designed to be used with ahb_mgr_reg_adapter with provides_responses=1, so calls put() on
+// m_layered_sequencer to provide responses to the operations.
+
+class ahb_mgr_register_layer_vseq extends uvm_sequence;
+  `uvm_object_utils(ahb_mgr_register_layer_vseq)
+
+  // A sequencer used as a source of register transactions that can be run, and the sequencer for
+  // the AHB channel.
+  //
+  // These can be provided by calling set_sequencers, which must be done before
+  // starting this sequence.
+  local uvm_sequencer #(ahb_reg_op_item) m_layered_sequencer;
+  local ahb_txn_sequencer_t              m_ahb_sequencer;
+
+  // An array of known mappings from address range to subordinate index. Set this with
+  // set_sub_mappings.
+  local sub_addr_range_t m_subordinate_mappings[$];
+
+  // If this is true, the AHB bus has a nonzero HPROT_WIDTH (either 4 or 7). If it is false, the AHB
+  // bus has no HPROT signal and sequences should be constrained to generate items with m_prot = 0.
+  //
+  // Configure this by calling set_has_hprot().
+  local bit          m_has_hprot = 1;
+
+  extern function new(string name="");
+  extern task body();
+
+  extern function void set_sequencers(ahb_reg_op_sequencer_t layered_sequencer,
+                                      ahb_txn_sequencer_t    ahb_sequencer);
+
+  // Set the subordinate mapping array
+  //
+  // Call this to configure the sequence before starting it.
+  extern function void set_subordinates(const ref sub_addr_range_t mappings[$]);
+
+  // Return the subordinate most recently associated with a range containing addr.
+  //
+  // If no subordinate is associated with the range, this writes 1 to the no_sub output argument.
+  extern local function int unsigned get_subordinate_for_addr(bit [63:0] addr, output bit no_sub);
+
+  // Configure whether the AHB bus has an HPROT signal. If has_hprot is false, sequences are
+  // constrained to generate items with m_prot = 0.
+  extern function void set_has_hprot(bit has_hprot);
+
+  // Send the request item through a layered sequence, passing any information back by modifying the
+  // item argument (by modifying its m_rw field).
+  extern local task send_op_item(ahb_reg_op_item item);
+endclass
+
+function ahb_mgr_register_layer_vseq::new(string name="");
+  super.new(name);
+endfunction
+
+task ahb_mgr_register_layer_vseq::body();
+  if (m_layered_sequencer == null || m_ahb_sequencer == null) begin
+    `uvm_fatal(get_full_name(), "Cannot run sequence because at least one sequencer is null.")
+  end
+
+  fork : isolation_fork begin
+    forever begin
+      ahb_reg_op_item item;
+      m_layered_sequencer.get(item);
+
+      // Run the item in the background. The send_op_item task completes when the generated virtual
+      // sequence runs to completion, modifying the item in its item argument to represent the
+      // response.
+      //
+      // At that point, we call m_layered_sequencer.put(item). The item will have originally come
+      // from an ahb_mgr_reg_adapter and the response will now be passed back to that adapter's
+      // bus2reg, which will be able to update a uvm_reg_bus_op in a uvm_reg_map, completing the
+      // operation handshake.
+      fork begin
+        send_op_item(item);
+        m_layered_sequencer.put(item);
+      end join_none
+    end
+  end join
+endtask
+
+function void
+  ahb_mgr_register_layer_vseq::set_sequencers(ahb_reg_op_sequencer_t layered_sequencer,
+                                              ahb_txn_sequencer_t    ahb_sequencer);
+  if (layered_sequencer == null) `uvm_fatal(get_full_name(), "No layered sequencer")
+  if (ahb_sequencer == null)     `uvm_fatal(get_full_name(), "No ahb sequencer")
+
+  m_layered_sequencer = layered_sequencer;
+  m_ahb_sequencer     = ahb_sequencer;
+endfunction
+
+function void ahb_mgr_register_layer_vseq::set_subordinates(const ref sub_addr_range_t mappings[$]);
+  m_subordinate_mappings.delete();
+  foreach (mappings[i]) begin
+    m_subordinate_mappings.push_back(mappings[i]);
+  end
+endfunction
+
+function int unsigned ahb_mgr_register_layer_vseq::get_subordinate_for_addr(bit [63:0] addr,
+                                                                            output bit no_sub);
+  foreach (m_subordinate_mappings[i]) begin
+    if (m_subordinate_mappings[i].addr_min <= addr &&
+        addr <= m_subordinate_mappings[i].addr_max) begin
+      return m_subordinate_mappings[i].subordinate_idx;
+    end
+  end
+
+  // No match. Set no_sub, allowing the caller to report an error and abort.
+  no_sub = 1;
+
+  return 0;
+endfunction
+
+function void ahb_mgr_register_layer_vseq::set_has_hprot(bit has_hprot);
+  m_has_hprot = has_hprot;
+endfunction
+
+task ahb_mgr_register_layer_vseq::send_op_item(ahb_reg_op_item item);
+  // This task handles the bulk of the work that would normally be done by a uvm_reg_adapter's
+  // reg2bus and bus2reg functions.
+  bit no_sub;
+
+  int unsigned subordinate_idx = get_subordinate_for_addr(item.m_rw.addr, no_sub);
+  if (no_sub) begin
+    `uvm_error(get_full_name(),
+               $sformatf("No subordinate is associated with address 0x%0h", item.m_rw.addr))
+    item.m_rw.status = UVM_NOT_OK;
+    return;
+  end
+
+  // item.m_rw.n_bits gives the number of bits that are being accessed. Since we don't support burst
+  // accesses, round this up to the next value for HSIZE by dividing down to bytes (and taking the
+  // ceiling), then taking clog2.
+  int unsigned hsize = $clog2((item.m_rw.n_bits + 7) / 8);
+
+  // This is the maximum strb value possible, given hsize. If byte_en is not maximal, the strb value
+  // to actually use might not have all of the bits set.
+  bit [127:0] strb_from_size = (128'd1 << (1 << hsize)) - 1;
+
+  // The strb value to send on a write transaction, or the byte mask to use with rdata in a read
+  // response. This takes size and byte_en into account.
+  bit [127:0] byte_mask = strb_from_size & item.m_rw.byte_en;
+
+  if (hsize > 7) begin
+    `uvm_error(get_full_name(),
+               $sformatf({"Cannot generate a sequence to represent an access with n_bits = %d: ",
+                          "for a single transfer, this would need an HSIZE of %0d."},
+                         item.m_rw.n_bits, hsize))
+    item.m_rw.status = UVM_NOT_OK;
+    return;
