index 00000000..79d17cdc
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_long_transfer_long_b_resp_short_r_resp_sequence.svh
@@ -0,0 +1,81 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
