+// SPDX-License-Identifier: Apache-2.0
+
+package common_ifs_pkg;
+  // dep packages
+  import uvm_pkg::*;
+
+  // Enum representing reset scheme
+  typedef enum bit [1:0] {
+    RstAssertSyncDeassertSync,
+    RstAssertAsyncDeassertSync,
+    RstAssertAsyncDeassertASync
+  } rst_scheme_e;
