diff --git a/tools/dv-classes/common_ifs/pins_if.sv b/tools/dv-classes/common_ifs/pins_if.sv
new file mode 100644
index 00000000..bf90c272
--- /dev/null
+++ b/tools/dv-classes/common_ifs/pins_if.sv
@@ -0,0 +1,116 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// Interface: pins_if
+// Description: Pin interface for driving and sampling individual pins such as interrupts, alerts
+// and gpios.
+`ifndef SYNTHESIS
+
+interface pins_if #(
+  parameter int Width = 1,
+  parameter bit [8*4-1:0] PullStrength = "Pull"
+) (
+  inout [Width-1:0] pins
+);
+
+  `include "prim_assert.sv"
+
+  `ASSERT_INIT(PullStrengthParamValid, PullStrength inside {"Weak", "Pull"})
+
+  logic [Width-1:0] pins_o;       // value to be driven out
+  bit   [Width-1:0] pins_oe = '0; // output enable
+  bit   [Width-1:0] pins_pd = '0; // pull down enable
+  bit   [Width-1:0] pins_pu = '0; // pull up enable
+
+  // function to set pin output enable for specific pin (useful for single pin interface)
+  function automatic void drive_en_pin(int idx = 0, bit val);
+    pins_oe[idx] = val;
+  endfunction
+
+  // function to set pin output enable for all pins
+  function automatic void drive_en(bit [Width-1:0] val);
+    pins_oe = val;
+  endfunction
+
+  // function to drive a specific pin with a value (useful for single pin interface)
+  function automatic void drive_pin(int idx = 0, logic val);
+    pins_oe[idx] = 1'b1;
+    pins_o[idx] = val;
+  endfunction // drive_pin
+
+  // function to drive all pins
+  function automatic void drive(logic [Width-1:0] val);
+    pins_oe = {Width{1'b1}};
+    pins_o = val;
+  endfunction // drive
+
+  // function to drive all pull down values
+  function automatic void set_pulldown_en(bit [Width-1:0] val);
+    pins_pd = val;
+  endfunction // set_pulldown_en
+
+  // function to drive all pull up values
+  function automatic void set_pullup_en(bit [Width-1:0] val);
+    pins_pu = val;
+  endfunction // set_pullup_en
+
+  // function to drive the pull down value on a specific pin
+  function automatic void set_pulldown_en_pin(int idx = 0, bit val);
+    pins_pd[idx] = val;
+  endfunction // set_pulldown_en_pin
+
+  // function to drive the pull up value on a specific pin
+  function automatic void set_pullup_en_pin(int idx = 0, bit val);
+    pins_pu[idx] = val;
+  endfunction // set_pullup_en_pin
+
+  // function to sample a specific pin (useful for single pin interface)
+  function automatic logic sample_pin(int idx = 0);
+    return pins[idx];
+  endfunction
+
+  // function to sample all pins
+  function automatic logic [Width-1:0] sample();
+    return pins;
+  endfunction
+
+  // Fully disconnect this interface, including the pulls.
+  function automatic void disconnect();
+    pins_oe = {Width{1'b0}};
+    pins_pu = {Width{1'b0}};
+    pins_pd = {Width{1'b0}};
+  endfunction
+
+  // make connections
+  for (genvar i = 0; i < Width; i++) begin : gen_each_pin
+`ifdef VERILATOR
+    assign pins[i] = pins_oe[i] ? pins_o[i] :
+                     pins_pu[i] ? 1'b1 :
+                     pins_pd[i] ? 1'b0 : 1'bz;
+`else
+    // Drive the pin based on whether pullup / pulldown is enabled.
+    //
+    // If output is not enabled, then the pin is pulled up or down with the `PullStrength` strength
+    // Pullup has priority over pulldown.
+    if (PullStrength == "Pull") begin : gen_pull_strength_pull
+      assign (pull0, pull1) pins[i] = ~pins_oe[i] ? (pins_pu[i] ? 1'b1 :
+                                                     pins_pd[i] ? 1'b0 : 1'bz) : 1'bz;
+    end : gen_pull_strength_pull
+    else if (PullStrength == "Weak") begin : gen_pull_strength_weak
+      assign (weak0, weak1) pins[i] = ~pins_oe[i] ? (pins_pu[i] ? 1'b1 :
+                                                     pins_pd[i] ? 1'b0 : 1'bz) : 1'bz;
+    end : gen_pull_strength_weak
+
+    // If output enable is 1, strong driver assigns pin to 'value to be driven out';
+    // the external strong driver can still affect pin, if exists.
+    // Else if output enable is 0, weak pullup or pulldown is applied to pin.
+    // By doing this, we make sure that weak pullup or pulldown does not override
+    // any 'x' value on pin, that may result due to conflicting values
+    // between 'value to be driven out' and the external driver's value.
+    assign pins[i] = pins_oe[i] ? pins_o[i] : 1'bz;
+`endif
+  end : gen_each_pin
+
+endinterface
+`endif
diff --git a/tools/dv-classes/common_ifs/rst_shadowed_if.sv b/tools/dv-classes/common_ifs/rst_shadowed_if.sv
new file mode 100644
index 00000000..3a7e02ef
--- /dev/null
+++ b/tools/dv-classes/common_ifs/rst_shadowed_if.sv
@@ -0,0 +1,39 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+//
+// Interface: rst_shadowed_if
+// An interface to drive rst_shadowed_n pin
+// By default, the `rst_shadowed_n` pin is directly connected to `rst_n` pin from the IP.
+// This interface provide methods to drive `rst_shadowed_n` pin when `drive_shadow_rst_pin()` task is
+// called, and can use `reconnect_shadowed_rst_n_to_rst_n()` to reconnect to `rst_n` pin.
+interface rst_shadowed_if (
+  input  rst_n,
+  output rst_shadowed_n
+);
+
+`ifndef VERILATOR
+  // include macros and import pkgs
+  `include "dv_macros.svh"
+  `include "uvm_macros.svh"
+  import uvm_pkg::*;
+`endif
+
+  bit   drive_shadowed_rst_en;
+  logic shadowed_rst_n;
+
+  // If set `drive_shadowed_rst_en` bit to 0, the `rst_shadowed_n` output will be the same as IP
+  // level reset pin.
+  function automatic void reconnect_shadowed_rst_n_to_rst_n();
+    drive_shadowed_rst_en = 0;
+  endfunction
+
+  task automatic drive_shadow_rst_pin(logic val);
+    shadowed_rst_n = val;
+    drive_shadowed_rst_en = 1;
+  endtask
+
+  assign rst_shadowed_n = drive_shadowed_rst_en ? shadowed_rst_n : rst_n;
+
+endinterface
diff --git a/tools/dv-classes/csr_utils/csr_base_seq.sv b/tools/dv-classes/csr_utils/csr_base_seq.sv
new file mode 100644
index 00000000..bac7af0c
--- /dev/null
+++ b/tools/dv-classes/csr_utils/csr_base_seq.sv
@@ -0,0 +1,306 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// The base class for CSR sequences, deriving from uvm_reg_sequence
+//
+// To use this sequence, create the object and then populate models, external_checker, and
+// num_test_csrs. Run the sequence by calling the start() task.
+//
+// Any subclass of this sequence performs tests across a set of registers in the design. The
+// complete list of available registers is computed just before the sequence body (in the pre_start
+// task), but a test may wish to check a smaller subset of these registers.
+//
+// To make that possible, there are two plusarg-based mechanisms:
+//
+//  +num_test_csrs=
+//
+//     If num_test_csrs is a positive number, the list of CSRs in all_csrs is divided into
+//     contiguous chunks of that length and then the sequence operates on some randomly chosen chunk
+//     from that list.
+//
+//     If max_num_test_csrs has been set to a positive number after creating the sequence, it is
+//     used as another upper bound on the number of CSRs in a chunk for the sequence.
+//
+//  +num_csr_chunks=, +test_csr_chunk=
+//
+//     If num_test_csrs is not provided, the list of CSRs in all_csrs can instead be divided into a
+//     requested number of contiguous chunks by setting num_csr_chunks. The index of the chunk to
+//     test is then provided with test_csr_chunk.
+//
+//     It is an error to use these flags if max_num_test_csrs is set to a positive number (because
+//     there's not a nice description of the length of chunks in that situation).
+
+class csr_base_seq extends uvm_reg_sequence #(uvm_sequence #(uvm_reg_item));
+  `uvm_object_utils(csr_base_seq)
+
+  // A queue of register models (UVM register blocks), whose registers will be added to the lists of
+  // CSRs (all_csrs and test_csrs) in pre_start.
+  dv_base_reg_block models[$];
+
+  // A flag that is true if there is some external checker (scoreboard).
+  //
+  // If it is false then each register write is followed by a call to that register's predict
+  // function in order to update the mirrored value. Similarly, reads are checked against the
+  // register's mirrored value (using the by passing a true "compare" argument to the csr_rd_check
+  // task).
+  //
+  // If the flag is true, the sequence doesn't do predict and compare, instead leaving that to the
+  // scoreboard.
+  //
+  // In either case, the prediction and comparison happen as part of the register write/read, which
+  // means that this sequence can do completely non-blocking writes and reads.
+  bit external_checker;
+
+  // An upper bound on the number of CSRs that are tested by this sequence. It can be set by the
+  // creator before starting the sequence. If not overridden, this will be zero (meaning there is no
+  // upper bound).
+  int unsigned max_num_test_csrs;
+
+  // A queue holding every register across the blocks in models.
+  protected uvm_reg all_csrs[$];
+
+  // A queue of the CSR registers that have been selected for this test. These are contained in
+  // all_csrs, but may be a proper subset if set_csr_test_range has picked only some of them (as
+  // instructed by the max_num_test_csrs or the num_test_csrs or num_csr_chunks plusargs). They will
+  // also be shuffled into a random order.
+  //
+  // The queue gets populated by set_csr_test_range, which is called by the pre_start task. It is
+  // then cleared by post_start, to ensure that it will be re-populated if the sequence is run
+  // again.
+  protected uvm_reg test_csrs[$];
+
+  extern function new (string name="");
+
+  // The pre_start task overrides that of uvm_sequence_base.
+  //
+  // It is run just before the body task and is in charge of selecting a subset of all_csrs on which
+  // the sequence will operate. This subset is written to test_csrs.
+  extern task pre_start();
+
+  // The post_start task overrides that of uvm_sequence_base.
+  //
+  // It is run just after the body task. In the body task, the sequence will have requested a stream
+  // of CSR accesses, but the implementation doesn't necessarily wait for the accesses to complete.
+  // To make sure they have actually done so, the post_start task waits for a period with no
+  // outstanding CSR accesses (which would mean that each access is done).
+  //
+  // The task also clears test_csrs, which means that the same sequence can be run another time and
+  // the randomisation in set_csr_test_range might pick a different set of test CSRs.
+  extern task post_start();
+
+  // Pick a subset of all_csrs and write that to test_csrs. The function's behaviour is described in
+  // the comment about plusargs before the class.
+  extern local function void set_csr_test_range();
+
+  // Return true if this is a CSR or field that has been excluded from the test described in
+  // csr_test_type by some exclusion (that ultimately came from the hjson register description).
+  extern function bit is_excl(uvm_object obj,
+                              csr_excl_type_e csr_excl_type,
+                              csr_test_type_e csr_test_type);
+
+  // Return true if this CSR should be excluded by the current sequence. The base class always
+  // returns false, but this allows more specialised sequences to work over more evenly sized
+  // chunks.
+  extern virtual protected function bit csr_excluded(uvm_reg csr);
+endclass
+
+function csr_base_seq::new (string name="");
+  super.new(name);
+endfunction
+
+task csr_base_seq::pre_start();
+  super.pre_start();
+
+  // Create test_csrs list only if it is empty. Note that this won't actually do anything if the
+  // entries in the models array don't have any registers.
+  if (test_csrs.size() == 0) begin
+    set_csr_test_range();
+  end
+endtask
+
+task csr_base_seq::post_start();
+  super.post_start();
+  wait_no_outstanding_access();
+  test_csrs.delete();
+endtask
+
+function void csr_base_seq::set_csr_test_range();
+  bit has_ntc, has_ncc, has_tcc;
+
+  int unsigned num_csrs;
+  int          num_test_csrs, num_csr_chunks, test_csr_chunk;
+
+  int unsigned start_idx, end_idx;
+
+  // Extract all csrs from the model. If this sequence has specialised the csr_excluded function,
+  // some CSRs might be skipped. This should help to keep chunks with similar testing times.
+  all_csrs.delete();
+  foreach (models[i]) begin
+    uvm_reg model_csrs[$];
+    models[i].get_registers(model_csrs);
+    foreach (model_csrs[j]) begin
+      if (!csr_excluded(model_csrs[j])) begin
+        all_csrs.push_back(model_csrs[j]);
+      end else begin
+        `uvm_info(`gtn,
+                  $sformatf("Skipping register %0s due to exclusion",
+                            model_csrs[j].get_full_name()),
+                  UVM_MEDIUM)
+      end
+    end
+  end
+
+  num_csrs = all_csrs.size();
+  if (!num_csrs) return;
+
+  // Has the num_test_csrs plusarg been supplied to give the maximum size of a chunk?
+  if ($value$plusargs("num_test_csrs=%0d", num_test_csrs)) begin
+    // Check that the user hasn't requested chunks of less than one: that wouldn't make much sense.
+    // Generate a UVM error and ignore the plusarg.
+    if (num_test_csrs < 1) begin
+      `uvm_error(`gtn, $sformatf("+num_test_csrs=%0d, which is not positive.", num_test_csrs))
+    end else begin
+      has_ntc = 1;
+
+      // If num_test_csrs is greater than the total number of CSRs, clip it to what is available.
+      if (num_test_csrs > num_csrs) begin
+        num_test_csrs = num_csrs;
+      end
+    end
+  end
+
+  // Has the num_csr_chunks plusarg been supplied?
+  if ($value$plusargs("num_csr_chunks=%0d", num_csr_chunks)) begin
+    // Check that we want a positive number of CSR chunks (since "splitting the list into -3 chunks"
+    // wouldn't make much sense!). If not, generate a UVM error and ignore the plusarg.
+    if (num_csr_chunks < 1) begin
+      `uvm_error(`gtn, $sformatf("+num_csr_chunks=%0d, which is not positive.", num_csr_chunks))
+    end else begin
+      has_ncc = 1;
+    end
+  end
+
+  // Has the test_csr_chunk plusarg been supplied?
+  if ($value$plusargs("test_csr_chunk=%0d", test_csr_chunk)) begin
+    if (!has_ncc) begin
+      // This argument only makes sense if we *have* specified a number of CSR chunks.
+      `uvm_error(`gtn, "Cannot supply test_csr_chunk without num_csr_chunks")
+    end else if (test_csr_chunk < 0 || test_csr_chunk >= num_csr_chunks) begin
+      // Similarly, it only makes sense if it's a valid index into the list of chunks.
+      `uvm_error(`gtn,
+                 $sformatf("+test_csr_chunk=%0d is invalid when num_csr_chunks=%0d",
+                           test_csr_chunk, num_csr_chunks));
+    end
+    has_tcc = 1;
+  end
+
+  // Check that num_test_csrs and num_csr_chunks haven't both been supplied (because then there
+  // isn't any good chunk size)
+  if (has_ntc && has_ncc) begin
+    `uvm_error(`gtn, "Cannot set both +num_csr_chunks and +num_test_csrs. Using the latter.")
+    has_ncc = 0;
+  end
+
+  // At this point, at most one of has_ntc and has_ncc is true.
+  if (has_ncc) begin
+    int unsigned chunk_idx;
+
+    // If num_csr_chunks has been supplied we can use it to derive a chunk size in the same way as
+    // the has_ntc case.
+    int unsigned chunk_size = (num_csrs + num_csr_chunks - 1) / num_csr_chunks;
+
+    // At this point, we might find that the requested number of chunks is incompatible with
+    // max_num_test_csrs. If so, generate an error and then clip chunk_size (to ensure the test
+    // doesn't run for a silly time)
+    if (max_num_test_csrs > 0 && chunk_size > max_num_test_csrs) begin
+      `uvm_error(`gtn,
+                 $sformatf("chunk_size %0d is too large for max_num_test_csrs %0d",
+                           chunk_size, max_num_test_csrs))
+      chunk_size = max_num_test_csrs;
+    end
+
+    // We might already have a chunk index in test_csr_chunk. If not, we pick one at random in the
+    // allowed range.
+    chunk_idx = has_tcc ? test_csr_chunk : $urandom_range(num_csr_chunks - 1);
+
+    // Again, convert these two into a pair of CSR indices (where end_idx is strictly past the end)
+    start_idx = chunk_idx * chunk_size;
+    end_idx = start_idx + chunk_size - 1;
+  end else if (has_ntc || max_num_test_csrs > 0) begin
+    int unsigned num_chunks, chunk_size, chunk_idx;
+
+    // Take the smaller supplied value of num_test_csrs and max_num_test_csrs to give an upper bound
+    // on the size of a chunk.
+    int unsigned max_chunk_size;
+    if (max_num_test_csrs > 0) begin
+      if (has_ntc) begin
+        max_chunk_size = (max_num_test_csrs < num_test_csrs) ? max_num_test_csrs : num_test_csrs;
+      end else begin
+        max_chunk_size = max_num_test_csrs;
+      end
+    end else begin
+      max_chunk_size = num_test_csrs;
+    end
+
+    // Now divide the total number of CSRs by that bound. Rounding up gives enough chunks to be able
+    // to cover the whole list.
+    num_chunks = (num_csrs + max_chunk_size - 1) / max_chunk_size;
+
+    // Given the number of chunks, we can now divide the number of CSRs by that to get the size of a
+    // chunk. Note that this will be at most max_chunk_size but may be much smaller.
+    //
+    // For example, if max_chunk_size = 50 and num_csrs = 51 then we will get 2 = ceil(51/50) chunks
+    // but then assign ceil(51/2) = 26 tests to each chunk, which gets "maximum parallelism" by
+    // avoiding dramatic differences between the size of chunks.
+    chunk_size = (num_csrs + num_chunks - 1) / num_chunks;
+
+    // Pick a chunk index (less than num_chunks) at random
+    chunk_idx = $urandom_range(num_chunks - 1);
+
+    // Finally, convert that into a pair of CSR indices (where end_idx is strictly past the end)
+    start_idx = chunk_idx * chunk_size;
+    end_idx = start_idx + chunk_size - 1;
+  end else begin
+    // If neither value was provided, we work on the entire list of CSRs at once.
+    start_idx = 0;
+    end_idx = num_csrs - 1;
+  end
+
+  // At this point, start_idx and end_idx should have been chosen, with start_idx < end_idx. Convert
+  // the end index to an inclusive limit, by clipping to the number of CSRs.
+  end_idx = (end_idx >= num_csrs) ? num_csrs - 1 : end_idx;
+
+  // At this point, we should have 0 <= start_idx <= end_idx < num_csrs. If that isn't true, there
+  // was a bug in the code above.
+  `DV_CHECK_FATAL(start_idx <= end_idx && end_idx < num_csrs)
+
+  // Replace any existing list of CSRs with the chosen chunk in a random order.
+  test_csrs.delete();
+  for (int i = start_idx; i <= end_idx; i++) begin
+    test_csrs.push_back(all_csrs[i]);
+    `uvm_info(`gtn, $sformatf("Testing CSR %0s, reset: 0x%0x.", all_csrs[i].get_full_name(),
+                              all_csrs[i].get_mirrored_value()), UVM_HIGH)
+  end
+  `uvm_info(`gtn,
+            $sformatf("Testing %0d csrs [%0d - %0d] from supplied models.",
+                      test_csrs.size(), start_idx, end_idx),
+            UVM_MEDIUM)
+
+  test_csrs.shuffle();
+endfunction
+
+function bit csr_base_seq::is_excl(uvm_object obj,
+                                   csr_excl_type_e csr_excl_type,
+                                   csr_test_type_e csr_test_type);
+  csr_excl_item csr_excl = get_excl_item(obj);
+  if (csr_excl == null) begin
+    return 0;
+  end else begin
+    return csr_excl.is_excl(obj, csr_excl_type, csr_test_type);
+  end
+endfunction
+
+function bit csr_base_seq::csr_excluded(uvm_reg csr);
+  return 1'b0;
+endfunction
diff --git a/tools/dv-classes/csr_utils/csr_hw_reset_seq.sv b/tools/dv-classes/csr_utils/csr_hw_reset_seq.sv
new file mode 100644
index 00000000..f91003b5
--- /dev/null
+++ b/tools/dv-classes/csr_utils/csr_hw_reset_seq.sv
@@ -0,0 +1,65 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// This sequence reads all CSRs and checks their values against the reset value provided in the RAL
+// specification. Note that this does not sufficiently qualify as the CSR HW reset test. The 'full'
+// CSR HW reset test is constructed externally by running csr_write_seq first, issuing reset and
+// only then running this sequence.
+
+class csr_hw_reset_seq extends csr_base_seq;
+  `uvm_object_utils(csr_hw_reset_seq)
+
+  extern function new (string name="");
+
+  // Read all CSRs, expecting their values to match their reset values in the register block.
+  extern task body();
+
+  // Read the given CSR if it is not excluded and check its value matches the expected reset value.
+  // If the register has an HDL path, use two reads, starting with a backdoor one.
+  extern local task test_one_csr(uvm_reg csr);
+
+  // Return true if the CSR should be skipped by this sequence
+  extern protected function bit csr_excluded(uvm_reg csr);
+endclass
+
+function csr_hw_reset_seq::new (string name="");
+  super.new(name);
+endfunction
+
+task csr_hw_reset_seq::body();
+  foreach (test_csrs[i]) begin
+    test_one_csr(test_csrs[i]);
+  end
+endtask
+
+task csr_hw_reset_seq::test_one_csr(uvm_reg csr);
+  uvm_reg_data_t compare_mask = get_mask_excl_fields(csr, CsrExclInitCheck, CsrHwResetTest);
+
+  `uvm_info(`gtn,
+            $sformatf("Verifying reset value of register %0s", csr.get_full_name()),
+            UVM_MEDIUM)
+
+  // Read CSR twice, one from backdoor (if path available), the other from frontdoor.
+  if (csr.has_hdl_path()) begin
+    // Reading from backdoor can ensure that we deposit value into the storage rather than just a
+    // net. If we mistakenly deposit to a net, reset can't clear it and this check will fail.
+    csr_rd_check(.ptr           (csr),
+                 .backdoor      (1),
+                 .compare       (!external_checker),
+                 .compare_vs_ral(1'b1),
+                 .compare_mask  (compare_mask));
+  end
+
+  // Read and check value via frontdoor.
+  csr_rd_check(.ptr           (csr),
+               .backdoor      (0),
+               .blocking      (0),
+               .compare       (!external_checker),
+               .compare_vs_ral(1'b1),
+               .compare_mask  (compare_mask));
+endtask
+
+function bit csr_hw_reset_seq::csr_excluded(uvm_reg csr);
+  return is_excl(csr, CsrExclInitCheck, CsrHwResetTest);
+endfunction
diff --git a/tools/dv-classes/csr_utils/csr_seq_lib.sv b/tools/dv-classes/csr_utils/csr_seq_lib.sv
new file mode 100644
index 00000000..63d10c90
--- /dev/null
+++ b/tools/dv-classes/csr_utils/csr_seq_lib.sv
@@ -0,0 +1,402 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+// CSR suite of sequences that do writes and reads to CSRs
+// includes hw_reset, rw, bit_bash and aliasing tests for CSRs, and mem_walk for uvm_mems
+// The sequences perform csr writes and reads and follow the standard csr test suite. If external
+// checker is enabled, then the external entity is required to update the mirrored value on
+// writes. If not enabled, the sequences themselves call predict function to update the mirrored
+// value. Consequently, the read values are checked against the mirrored value and not the
+// previously written value. This approach is better since it takes care of special
+// register and field access policies. Also, we use csr_rd_check task instead of csr_mirror to take
+// field exclusions into account.
+//
+// Exclusions are to be provided using the csr_excl_item item (see class for more details).
+
+//--------------------------------------------------------------------------------------------------
+// Class: csr_write_seq
+// Brief Description: This sequence writes a random value to all CSRs. It does not perform any
+// checks. It is run as the first step of the CSR HW reset test.
+//--------------------------------------------------------------------------------------------------
+class csr_write_seq extends csr_base_seq;
+  static bit test_backdoor_path_done; // only run once
+  bit en_rand_backdoor_write;
+  `uvm_object_utils(csr_write_seq)
+
+  `uvm_object_new
+
+  virtual task body();
+    uvm_reg_data_t wdata;
+
+    // check all hdl paths are valid
+    if (!test_backdoor_path_done) begin
+      foreach (models[i]) begin
+        bkdr_reg_path_e path_kind;
+        uvm_reg_mem_hdl_paths_seq hdl_check_seq;
+
+        hdl_check_seq = uvm_reg_mem_hdl_paths_seq::type_id::create("hdl_check_seq");
+        do begin
+          // Test the HDL paths for correctness if they exist.
+          if (models[i].has_hdl_path(path_kind.name)) begin
+            hdl_check_seq.abstractions.push_back(path_kind.name);
+          end
+          path_kind = path_kind.next;
+        end while (path_kind != path_kind.first);
+        hdl_check_seq.model = models[i];
+        hdl_check_seq.start(null);
+      end
+      test_backdoor_path_done = 1;
+    end
+
+    foreach (test_csrs[i]) begin
+      dv_base_reg dv_csr;
+      bit         backdoor;
+      // check if parent block or register is excluded from write
+      if (is_excl(test_csrs[i], CsrExclWrite, CsrHwResetTest)) begin
+        `uvm_info(`gtn, $sformatf("Skipping register %0s due to CsrExclWrite exclusion",
+                                  test_csrs[i].get_full_name()), UVM_MEDIUM)
+        continue;
+      end
+
+      `uvm_info(`gtn, $sformatf("Writing random data to register %0s",
+                                test_csrs[i].get_full_name()), UVM_MEDIUM)
+
+      `DV_CHECK_STD_RANDOMIZE_FATAL(wdata)
+      wdata = get_csr_wdata_with_write_excl(test_csrs[i], wdata, CsrHwResetTest);
+
+      `downcast(dv_csr, test_csrs[i])
+      if (en_rand_backdoor_write && test_csrs[i].has_hdl_path() && !dv_csr.get_is_ext_reg()) begin
+        `DV_CHECK_STD_RANDOMIZE_WITH_FATAL(backdoor, backdoor dist {0 :/ 7, 1 :/ 3};)
+      end
+
+      if (backdoor) begin
+        string str_kinds[$];
+
+        test_csrs[i].get_hdl_path_kinds(str_kinds);
+        str_kinds.shuffle();
+
+        foreach (str_kinds[j]) begin
+          bkdr_reg_path_e enum_kind;
+          // Convert string name to an enum
+          `DV_CHECK_FATAL(uvm_enum_wrapper#(bkdr_reg_path_e)::from_name(str_kinds[j], enum_kind))
+
+          csr_poke(.ptr(test_csrs[i]), .value(wdata), .kind(enum_kind));
+
+          `DV_CHECK_STD_RANDOMIZE_FATAL(wdata)
+          wdata = get_csr_wdata_with_write_excl(test_csrs[i], wdata, CsrHwResetTest);
+        end
+      end else begin
+        csr_wr(.ptr(test_csrs[i]), .value(wdata), .blocking(0));
+      end
+    end
+  endtask
+
+endclass
+
+
+//--------------------------------------------------------------------------------------------------
+// Class: csr_rw_seq
+// Brief Description: This seq writes a random value to a CSR and reads it back. The read value
+// is checked for correctness while adhering to its access policies. A random choice is made between
+// reading back the CSR as a whole or reading fields individually, so that partial accesses are made
+// into the DUT as well.
+//--------------------------------------------------------------------------------------------------
+class csr_rw_seq extends csr_base_seq;
+  `uvm_object_utils(csr_rw_seq)
+
+  `uvm_object_new
+
+  virtual task body();
+    foreach (test_csrs[i]) begin
+      uvm_reg_data_t wdata;
+      uvm_reg_field  test_fields[$];
+      dv_base_reg    test_dv_csr;
+      bit            supports_byte_enable;
+      bit            do_field_rd_check;
+
+      // The test_csrs list may be jumbled from different RAL models. Hence, we find at runtime, if
+      // the interface supports byte_accesses.
+      begin
+        uvm_reg_map map = test_csrs[i].get_default_map();
+        uvm_reg_adapter adapter = map.get_adapter();
+        if (adapter != null) begin
+          supports_byte_enable = adapter.supports_byte_enable;
+        end
+      end
+
+      // check if parent block or register is excluded from write
+      if (is_excl(test_csrs[i], CsrExclWrite, CsrRwTest)) begin
+        `uvm_info(`gtn, $sformatf("Skipping register %0s due to CsrExclWrite exclusion",
+                                  test_csrs[i].get_full_name()), UVM_MEDIUM)
+        continue;
+      end
+
+      `uvm_info(`gtn, $sformatf("Verifying register read/write for %0s",
+                                test_csrs[i].get_full_name()), UVM_MEDIUM)
+
+      `DV_CHECK_STD_RANDOMIZE_FATAL(wdata)
+      wdata = get_csr_wdata_with_write_excl(test_csrs[i], wdata, CsrRwTest);
+
+      // if external checker is not enabled and writes are made non-blocking, then we need to
+      // pre-predict so that the mirrored value will be updated. if we dont, then csr_rd_check task
+      // might pick up stale mirrored value
+      // the pre-predict also needs to happen after the register is being written, to make sure the
+      // register is getting the updated access information.
+      csr_wr(.ptr(test_csrs[i]), .value(wdata), .blocking(0), .predict(!external_checker));
+
+      // Shadow register requires two writes with the same value to write registers into DUT.
+      // In `csr_wr` task, the `predict` task is triggered after two shadow writes are done.
+      // To avoid non-blocking access where shadow register read might be triggered between two
+      // consecutive shadow register write, we will wait until all outstanding accesses finish,
+      // then issue a shadow register read.
+      `downcast(test_dv_csr, test_csrs[i])
+      if (test_dv_csr.get_is_shadowed) wait_no_outstanding_access();
+
+      `DV_CHECK_STD_RANDOMIZE_WITH_FATAL(do_field_rd_check,
+          !supports_byte_enable -> !do_field_rd_check;)
+      do_check_csr_or_field_rd(.csr(test_csrs[i]),
+                              .blocking(0),
+                              .compare(!external_checker),
+                              .compare_vs_ral(1),
+                              .do_csr_field_rd_check(do_field_rd_check),
+                              .csr_excl_type(CsrExclWriteCheck),
+                              .csr_test_type(CsrRwTest));
+
+      wait_if_max_outstanding_accesses_reached();
+    end
+  endtask
+
+endclass
+
+//--------------------------------------------------------------------------------------------------
+// Class: csr_bit_bash_seq
+// Brief Description: This sequence walks a 1 through each CSR by writing one bit at a time and
+// reading the CSR back. The read value is checked for correctness while adhering to its access
+// policies. This verifies that there is no aliasing within the fields / bits of a CSR.
+//--------------------------------------------------------------------------------------------------
+class csr_bit_bash_seq extends csr_base_seq;
+  `uvm_object_utils(csr_bit_bash_seq)
+
+  `uvm_object_new
+
+  virtual task body();
+    int unsigned total_count = test_csrs.size();
+    int unsigned done_count = 0;
+
+    `uvm_info(`gtn,
+              $sformatf("Running bit bash sequence for %0d registers", total_count),
+              UVM_MEDIUM)
+    foreach (test_csrs[i]) begin
+      done_count++;
+      `uvm_info(`gtn,
+                $sformatf("Verifying register bit bash for %0s (register %0d/%0d)",
+                          test_csrs[i].get_full_name(), done_count, total_count),
+                UVM_MEDIUM)
+
+      // check if parent block or register is excluded from write
+      if (is_excl(test_csrs[i], CsrExclWrite, CsrBitBashTest) ||
+          is_excl(test_csrs[i], CsrExclWriteCheck, CsrBitBashTest)) begin
+        `uvm_info(`gtn, $sformatf("Skipping register %0s due to CsrExclWrite/WriteCheck exclusion",
+                                  test_csrs[i].get_full_name()), UVM_MEDIUM)
+        continue;
+      end
+
+      bash_register(test_csrs[i]);
+    end
+
+  endtask
+
+  // Run bit bash test on the given register.
+  //
+  // The basic idea is that we test each bit of the register with the bash_kth_bit task, checking
+  // that we can set and clear the register as expected. This task takes field exclusions and
+  // read/write masks into account when calculating how to run the bash_kth_bit task across the
+  // register.
+  virtual task bash_register(uvm_reg csr);
+    uvm_reg_field   fields[$];
+    string          mode[`UVM_REG_DATA_WIDTH];
+    uvm_reg_data_t  dc_mask;  // dont write or read
+    uvm_reg_data_t  no_cmp_mask; // read but dont compare
+    int             n_bits;
+    string          field_access;
+    int             next_lsb;
+
+    n_bits = csr.get_n_bytes() * 8;
+
+    // Let's see what kind of bits we have...
+    csr.get_fields(fields);
+
+    next_lsb    = 0;
+    dc_mask     = 0;
+    no_cmp_mask = 0;
+
+    foreach (fields[j]) begin
+      int lsb, w, dc, no_cmp;
+
+      field_access = fields[j].get_access(csr.get_default_map());
+      no_cmp = (fields[j].get_compare() == UVM_NO_CHECK);
+      lsb    = fields[j].get_lsb_pos();
+      w      = fields[j].get_n_bits();
+
+      // Exclude write-only fields from compare because you are not supposed to read them
+      case (field_access)
+        "WO", "WOC", "WOS", "WO1", "NOACCESS", "": no_cmp = 1;
+        default:                                   no_cmp = 0;
+      endcase
+
+      // skip fields that are wr-excluded
+      if (is_excl(fields[j], CsrExclWrite, CsrBitBashTest)) begin
+        `uvm_info(`gtn, $sformatf("Skipping field %0s due to CsrExclWrite exclusion",
+                                  fields[j].get_full_name()), UVM_MEDIUM)
+        dc = 1;
+      end
+
+      // ignore fields that are init or rd-excluded
+      no_cmp = is_excl(fields[j], CsrExclInitCheck, CsrBitBashTest) ||
+               is_excl(fields[j], CsrExclWriteCheck, CsrBitBashTest) ;
+
+      // Any unused bits below the LSB of this field?
+      while (next_lsb < lsb) mode[next_lsb++] = "RO";
+
+      repeat (w) begin
+        mode[next_lsb] = field_access;
+        dc_mask[next_lsb] = dc;
+        no_cmp_mask[next_lsb] = no_cmp;
+        next_lsb++;
+      end
+    end
+
+    // Any unused bits above the top field, but that we will still look at with bash_kth_bit?
+    while (next_lsb < n_bits) begin
+      mode[next_lsb++] = "RO";
+    end
+
+    // Bash the kth bit
+    for (int k = 0; k < n_bits; k++) begin
+      // Cannot test unpredictable bit behavior
+      if (dc_mask[k]) continue;
+      bash_kth_bit(csr, k, mode[k], no_cmp_mask);
+    end
+  endtask
+
+  // A bit bashing sequence for bit k of register rg.
+  //
+  // This works by writing the bit as one value and reading it back, then writing the other value
+  // and reading that back, checking that each write sets the value as expected.
+  //
+  // The mask argument gives bits that won't be compared when reading the value back. Note that this
+  // task is still worth running even if the k'th bit of mask is set: it might be that writes to
+  // that bit of the register mess up other bits/fields in the register, and this task will spot if
+  // that happens.
+  task bash_kth_bit(uvm_reg        rg,
+                    int            k,
+                    string         mode,
+                    uvm_reg_data_t mask);
+
+    uvm_reg_data_t val;
+    string          err_msg;
+
+    `uvm_info(`gtn, $sformatf("bashing %0s bit #%0d", mode, k), UVM_HIGH)
+    repeat (2) begin
+      val = rg.get();
+      val[k]  = ~val[k];
+      err_msg = $sformatf("Wrote %0s[%0d]: %0b", rg.get_full_name(), k, val[k]);
+      csr_wr(.ptr(rg), .value(val), .blocking(1), .predict(!external_checker));
+
+      // uvm_reg waits until transaction is completed, before start another read/write in same reg
+      csr_rd_check(.ptr           (rg),
+                   .blocking      (0),
+                   .compare       (!external_checker),
+                   .compare_vs_ral(1'b1),
+                   .compare_mask  (~mask),
+                   .err_msg       (err_msg));
+    end
+  endtask: bash_kth_bit
+
+endclass
+
+//--------------------------------------------------------------------------------------------------
+// Class: csr_aliasing_seq
+// Brief Description: For each CSR, this sequence writes a random value to it and reads ALL CSRs
+// back. The read value of the CSR that was written is checked for correctness while adhering to its
+// access policies. The read value of all other CSRs are compared against their previous values.
+// This verifies that there is no aliasing across the address bits within the valid CSR space.
+//--------------------------------------------------------------------------------------------------
+class csr_aliasing_seq extends csr_base_seq;
+  `uvm_object_utils(csr_aliasing_seq)
+
+  `uvm_object_new
+
+  virtual task body();
+    foreach(test_csrs[i]) begin
+      uvm_reg_data_t wdata;
+
+      // check if parent block or register is excluded
+      if (is_excl(test_csrs[i], CsrExclWrite, CsrAliasingTest)) begin
+        `uvm_info(`gtn, $sformatf("Skipping register %0s due to CsrExclWrite exclusion",
+                                  test_csrs[i].get_full_name()), UVM_MEDIUM)
+        continue;
+      end
+
+      `uvm_info(`gtn,
+                $sformatf("Verifying register aliasing for %0s (register %0d / %0d)",
+                          test_csrs[i].get_full_name(), i + 1, test_csrs.size()),
+                UVM_MEDIUM)
+
+      `DV_CHECK_STD_RANDOMIZE_FATAL(wdata)
+      wdata = get_csr_wdata_with_write_excl(test_csrs[i], wdata, CsrAliasingTest);
+      csr_wr(.ptr(test_csrs[i]), .value(wdata), .blocking(0), .predict(!external_checker));
+
+      all_csrs.shuffle();
+
+      // If all_csrs queue size is larger than 100, randomly pick 100 CSRs to avoid chip level test
+      // runtime too long.
+      if (all_csrs.size() > 100) all_csrs = all_csrs[0 : 99];
+
+      foreach (all_csrs[j]) begin
+        uvm_reg_data_t compare_mask;
+
+        // check if parent block or register is excluded
+        if (is_excl(all_csrs[j], CsrExclInitCheck, CsrAliasingTest) ||
+            is_excl(all_csrs[j], CsrExclWriteCheck, CsrAliasingTest)) begin
+          `uvm_info(`gtn, $sformatf("Skipping register %0s due to CsrExclInit/WriteCheck exclusion",
+                                    all_csrs[j].get_full_name()), UVM_HIGH)
+          continue;
+        end
+
+        compare_mask = get_mask_excl_fields(all_csrs[j], CsrExclWriteCheck, CsrAliasingTest);
+        csr_rd_check(.ptr           (all_csrs[j]),
+                     .blocking      (0),
+                     .compare       (!external_checker),
+                     .compare_vs_ral(1'b1),
+                     .compare_mask  (compare_mask));
+      end
+      wait_no_outstanding_access();
+    end
+  endtask
+
+endclass
+
+//--------------------------------------------------------------------------------------------------
+// Class: csr_mem_walk_seq
+// Brief Description: This seq walks through each address of the memory by running the default
+// UVM mem walk sequence.
+//--------------------------------------------------------------------------------------------------
+class csr_mem_walk_seq extends csr_base_seq;
+  uvm_mem_walk_seq mem_walk_seq;
+
+  `uvm_object_utils(csr_mem_walk_seq)
+
+  `uvm_object_new
+
+  virtual task body();
+    mem_walk_seq = uvm_mem_walk_seq::type_id::create("mem_walk_seq");
+    foreach (models[i]) begin
+      `uvm_info(`gfn, $sformatf("Testing model %0s", models[i].get_full_name()), UVM_LOW)
+      mem_walk_seq.model = models[i];
+      mem_walk_seq.start(null);
+    end
+  endtask : body
+
+endclass
diff --git a/tools/dv-classes/csr_utils/csr_utils_pkg.sv b/tools/dv-classes/csr_utils/csr_utils_pkg.sv
new file mode 100644
index 00000000..18509340
--- /dev/null
+++ b/tools/dv-classes/csr_utils/csr_utils_pkg.sv
@@ -0,0 +1,862 @@
+// Copyright lowRISC contributors (OpenTitan project).
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+
+package csr_utils_pkg;
+  // dep packages
+  import uvm_pkg::*;
+  import dv_utils_pkg::*;
+  import dv_base_reg_pkg::*;
+  export dv_base_reg_pkg::csr_field_t, dv_base_reg_pkg::decode_csr_or_field;
+
+  // macro includes
+  `include "uvm_macros.svh"
+  `include "dv_macros.svh"
+
+  // local types and variables
+  uint              outstanding_accesses        = 0;
+  uint              default_timeout_ns          = 2_000_000; // 2ms
+  uint              default_spinwait_timeout_ns = 10_000_000; // 10ms
+  bit               default_csr_blocking        = 1;
+  uvm_check_e       default_csr_check           = UVM_CHECK;
+  bit               under_reset                 = 0;
+  int               max_outstanding_accesses    = 100;
+  uvm_reg_frontdoor default_user_frontdoor      = null;
+
+  function automatic void increment_outstanding_access();
+    outstanding_accesses++;
+    `uvm_info($sformatf("%m"), $sformatf("%0d", outstanding_accesses), UVM_HIGH)
+  endfunction
+
+  function automatic void decrement_outstanding_access();
+    outstanding_accesses--;
+    `uvm_info($sformatf("%m"), $sformatf("%0d", outstanding_accesses), UVM_HIGH)
+  endfunction
+
+  task automatic wait_no_outstanding_access();
+    wait(outstanding_accesses == 0);
+  endtask
+
+  function automatic void clear_outstanding_access();
+    outstanding_accesses = 0;
+  endfunction
+
+  function automatic bit has_outstanding_access();
+    return outstanding_accesses > 0;
+  endfunction
+
+  // timeout may happen if we issue too many non-blocking accesses at once
+  // limit the nonblocking items to be up to max outstanding
+  task automatic wait_if_max_outstanding_accesses_reached(int max = max_outstanding_accesses);
+    wait(outstanding_accesses <= max);
+  endtask
+
+  function automatic void reset_asserted();
+    under_reset = 1;
+  endfunction
+
+  function automatic void reset_deasserted();
+    under_reset = 0;
+  endfunction
+
+  // get mem object from address
+  function automatic uvm_mem get_mem_by_addr(uvm_reg_block ral, uvm_reg_addr_t addr);
+    uvm_mem mem;
+    addr[1:0] = 0;
+    mem = ral.default_map.get_mem_by_offset(addr);
+    `DV_CHECK_NE_FATAL(mem, null,
+                       $sformatf("Can't find any mem with addr 0x%0h", addr), $sformatf("%m"))
+    return mem;
+  endfunction
+
+  // get mem access like RW, RO
+  function automatic string get_mem_access_by_addr(uvm_reg_block ral, uvm_reg_addr_t addr);
+    uvm_mem mem = get_mem_by_addr(ral, addr);
+    return mem.get_access();
+  endfunction
+
+  // This function return mirrored value of reg/field of given RAL
+  function automatic uvm_reg_data_t get_reg_fld_mirror_value(uvm_reg_block ral,
+                                                             string        reg_name,
+                                                             string        field_name  = "");
+    uvm_reg         csr;
+    uvm_reg_field   fld;
+    uvm_reg_data_t  result;
+    csr = ral.get_reg_by_name(reg_name);
+    `DV_CHECK_NE_FATAL(csr, null, "", $sformatf("%m"))
+    // return field mirror value if field_name is passed, else return reg mirror value
+    if (field_name != "") begin
+      fld = csr.get_field_by_name(field_name);
+      `DV_CHECK_NE_FATAL(fld, null, "", $sformatf("%m"))
+      result = fld.get_mirrored_value();
+    end
+    else begin
+      result = csr.get_mirrored_value();
+    end
+    return result;
+  endfunction : get_reg_fld_mirror_value
+
+  // get updated reg value by using new specific field value
+  function automatic uvm_reg_data_t get_csr_val_with_updated_field(uvm_reg_field   field,
+                                                                   uvm_reg_data_t  csr_value,
+                                                                   uvm_reg_data_t  field_value);
+    uvm_reg_data_t  mask = (1 << field.get_n_bits()) - 1;
+    uint            shift = field.get_lsb_pos();
+    csr_value = csr_value & ~(mask << shift) | ((mask & field_value) << shift);
+    return csr_value;
+  endfunction
+
+  // wait until current csr op is complete
+  task automatic csr_wait(input uvm_reg csr);
+    `uvm_info($sformatf("%m"), $sformatf("%0s: wait_busy: %0b",
+                                         csr.get_full_name(), csr.m_is_busy), UVM_HIGH)
+    wait(csr.m_is_busy == 1'b0);
+    `uvm_info($sformatf("%m"), $sformatf("%0s: done wait_busy: %0b",
+                                         csr.get_full_name(), csr.m_is_busy), UVM_HIGH)
+  endtask
+
+  // Use `csr_wr` to construct `csr_update` to avoid replicated codes to handle nonblocking,
+  // shadow writes etc
+  task automatic csr_update(input  uvm_reg            csr,
+                            input  uvm_check_e        check = default_csr_check,
+                            input  uvm_path_e         path = UVM_DEFAULT_PATH,
+                            input  bit                blocking = default_csr_blocking,
+                            input  uint               timeout_ns = default_timeout_ns,
+                            input  uvm_reg_map        map = null,
+                            input  uvm_reg_frontdoor  user_ftdr = default_user_frontdoor,
+                            input  bit                en_shadow_wr = 1);
+    uvm_reg_field fields[$];
+    uvm_reg_data_t value;
+
+    // below is partial replication of the uvm_reg_field::update() logic in UVM1.2 source code
+    if (!csr.needs_update()) return;
+    csr.get_fields(fields);
+    // Concatenate the write-to-update values from each field
+    // Fields are stored in LSB or MSB order
+    value = 0;
+    foreach (fields[i]) begin
+      value |= fields[i].XupdateX() << fields[i].get_lsb_pos();
+    end
+
+    csr_wr(.ptr(csr), .value(value), .check(check), .path(path), .blocking(blocking), .backdoor(0),
+           .timeout_ns(timeout_ns), .predict(0), .map(map), .user_ftdr(user_ftdr),
+           .en_shadow_wr(en_shadow_wr));
+  endtask
+
+  task automatic csr_wr(input uvm_object          ptr,
+                        input uvm_reg_data_t      value,
+                        input uvm_check_e         check = default_csr_check,
+                        input uvm_path_e          path = UVM_DEFAULT_PATH,
+                        input bit                 blocking = default_csr_blocking,
+                        input bit                 backdoor = 0,
+                        input uint                timeout_ns = default_timeout_ns,
+                        input bit                 predict = 0,
+                        input uvm_reg_map         map = null,
+                        input uvm_reg_frontdoor   user_ftdr = default_user_frontdoor,
+                        input bit                 en_shadow_wr = 1);
+    if (backdoor) begin
+      csr_poke(ptr, value, check, predict);
+    end else begin
+      csr_field_t csr_or_fld = decode_csr_or_field(ptr);
+
+      // if it's a field write, still do full CSR write and use mirrored value for the other fields
+      if (csr_or_fld.field != null) begin
+        // get full CSR value
+        value = get_csr_val_with_updated_field(csr_or_fld.field, `gmv(csr_or_fld.csr), value);
+      end
+
+      if (blocking) begin
+        csr_wr_sub(csr_or_fld.csr, value, check, path, timeout_ns, predict, map, user_ftdr,
+                   en_shadow_wr);
+      end else begin
+        fork
+          begin
+            csr_wr_sub(csr_or_fld.csr, value, check, path, timeout_ns, predict, map, user_ftdr,
+                       en_shadow_wr);
+          end
+        join_none
+        // Add #0 to ensure that this thread starts executing before any subsequent call
+        #0;
+      end
+    end
+  endtask
+
+  // subroutine of csr_wr, don't use it directly
+  task automatic csr_wr_sub(input uvm_reg             csr,
+                            input uvm_reg_data_t      value,
+                            input uvm_check_e         check = default_csr_check,
+                            input uvm_path_e          path = UVM_DEFAULT_PATH,
+                            input uint                timeout_ns = default_timeout_ns,
+                            input bit                 predict = 0,
+                            input uvm_reg_map         map = null,
+                            input uvm_reg_frontdoor   user_ftdr = default_user_frontdoor,
+                            input bit                 en_shadow_wr = 1);
+    fork
+      begin : isolation_fork
+        fork
+          begin
+            dv_base_reg dv_reg;
+            `downcast(dv_reg, csr, "", fatal, $sformatf("%m"))
+
+            increment_outstanding_access();
+            csr_pre_write_sub(csr, en_shadow_wr);
+
+            csr_wr_and_predict_sub(.csr(csr), .value(value), .check(check), .path(path),
+                                   .predict(predict), .map(map), .user_ftdr(user_ftdr));
+            if (en_shadow_wr && dv_reg.get_is_shadowed()) begin
+              csr_wr_and_predict_sub(.csr(csr), .value(value), .check(check), .path(path),
+                                     .predict(predict), .map(map), .user_ftdr(user_ftdr));
+            end
+
+            csr_post_write_sub(csr, en_shadow_wr);
+            decrement_outstanding_access();
+          end
+          begin
+            `DV_WAIT_TIMEOUT(timeout_ns, $sformatf("%m"),
+                             $sformatf("Timeout waiting to csr_wr %0s (addr=0x%0h)",
+                                       csr.get_full_name(), csr.get_address()))
+          end
+        join_any
+        disable fork;
+      end : isolation_fork
+    join
+  endtask
+
+  // internal task, don't use it directly
+  task automatic csr_wr_and_predict_sub(uvm_reg             csr,
+                                        uvm_reg_data_t      value,
+                                        uvm_check_e         check,
+                                        uvm_path_e          path,
+                                        bit                 predict,
+                                        uvm_reg_map         map,
+                                        uvm_reg_frontdoor   user_ftdr);
+    uvm_status_e status;
+
+    if (user_ftdr != null) csr.set_frontdoor(user_ftdr);
+    csr.write(.status(status), .value(value), .path(path), .map(map), .prior(100));
+    // TODO: need to remove the frontdoor to switch back to the default,
+    // but this doesn't work: if (user_ftdr != null) ptr.set_frontdoor(null);
+
+    if (under_reset) return;
+    if (check == UVM_CHECK) begin
+      `DV_CHECK_EQ(status, UVM_IS_OK,
+                   $sformatf("trying to write csr %0s", csr.get_full_name()),
+                   error, $sformatf("%m"))
+    end
+    // Only update the predicted value if status is ok (otherwise the write isn't completed
+    // successfully and the design shouldn't have accepted the written value)
+    if (status == UVM_IS_OK && predict) begin
+      void'(csr.predict(.value(value), .kind(UVM_PREDICT_WRITE)));
+    end
+  endtask
+
+  task automatic csr_pre_write_sub(uvm_reg csr, bit en_shadow_wr);
+    dv_base_reg dv_reg;
+    `downcast(dv_reg, csr, "", fatal, $sformatf("%m"))
+    if (dv_reg.get_is_shadowed() && en_shadow_wr) begin
+      dv_reg.atomic_en_shadow_wr.get(1);
+    end
+  endtask
+
+  task automatic csr_post_write_sub(uvm_reg csr, bit en_shadow_wr);
+    dv_base_reg dv_reg;
+    `downcast(dv_reg, csr, "", fatal, $sformatf("%m"))
+    if (dv_reg.get_is_shadowed() && en_shadow_wr) begin
+      dv_reg.atomic_en_shadow_wr.put(1);
+    end
+  endtask
+
+  // backdoor write csr
+  task automatic csr_poke(input uvm_object      ptr,
+                          input uvm_reg_data_t  value,
+                          input uvm_check_e     check = default_csr_check,
+                          input bit             predict = 0,
+                          input bkdr_reg_path_e kind = BkdrRegPathRtl);
+    csr_field_t   csr_or_fld = decode_csr_or_field(ptr);
+    uvm_status_e  status;
+    uvm_reg_data_t old_mirrored_val;
+
+    if (csr_or_fld.field != null) begin
+      old_mirrored_val = csr_or_fld.field.get_mirrored_value();
+      csr_or_fld.field.poke(.status(status), .value(value), .kind(kind.name));
+    end else begin
+      old_mirrored_val = csr_or_fld.csr.get_mirrored_value();
+      csr_or_fld.csr.poke(.status(status), .value(value), .kind(kind.name));
+    end
+    if (check == UVM_CHECK && status != UVM_IS_OK) begin
+      string str;
+      uvm_hdl_path_concat paths[$];
+      csr_or_fld.csr.get_full_hdl_path(paths, kind.name);
+      foreach (paths[0].slices[i]) str = $sformatf("%0s\n%0s", str, paths[0].slices[i].path);
+      `uvm_fatal($sformatf("%m"), $sformatf("poke failed for %0s, check below paths %0s",
+                                            ptr.get_full_name(), str))
+    end
+    // poke always updates predict value, if predict == 0, revert back to old mirrored value
+    if (!predict || kind == BkdrRegPathRtlShadow) begin
+      if (csr_or_fld.field != null) begin
+        void'(csr_or_fld.field.predict(.value(old_mirrored_val), .kind(UVM_PREDICT_DIRECT),
+                                       .path(UVM_BACKDOOR)));
+      end else begin
+        void'(csr_or_fld.csr.predict(.value(old_mirrored_val), .kind(UVM_PREDICT_DIRECT),
+                                     .path(UVM_BACKDOOR)));
+      end
+    end
+  endtask
+
+  task automatic csr_rd(input  uvm_object         ptr, // accept reg or field
+                        output uvm_reg_data_t     value,
+                        input  uvm_check_e        check = default_csr_check,
+                        input  uvm_path_e         path = UVM_DEFAULT_PATH,
+                        input  bit                blocking = default_csr_blocking,
+                        input  bit                backdoor = 0,
+                        input  uint               timeout_ns = default_timeout_ns,
+                        input  uvm_reg_map        map = null,
+                        input  uvm_reg_frontdoor  user_ftdr = default_user_frontdoor);
+    uvm_status_e status;
+    if (blocking) begin
+      csr_rd_sub(.ptr(ptr), .value(value), .status(status), .check(check), .path(path),
+                 .backdoor(backdoor), .timeout_ns(timeout_ns), .map(map), .user_ftdr(user_ftdr));
+    end else begin
+      `DV_CHECK_EQ(backdoor, 0, "Don't enable backdoor with blocking = 0", error, $sformatf("%m"))
+      fork
+        csr_rd_sub(.ptr(ptr), .value(value), .status(status), .check(check), .path(path),
+                   .backdoor(backdoor), .timeout_ns(timeout_ns), .map(map), .user_ftdr(user_ftdr));
+      join_none
+      // Add #0 to ensure that this thread starts executing before any subsequent call
+      #0;
+    end
+  endtask
+
+  // subroutine of csr_rd, don't use it directly
+  task automatic csr_rd_sub(input  uvm_object         ptr, // accept reg or field
+                            output uvm_reg_data_t     value,
+                            output uvm_status_e       status,
+                            input  bit                backdoor = 0,
+                            input  uvm_check_e        check = default_csr_check,
+                            input  uvm_path_e         path = UVM_DEFAULT_PATH,
+                            input  uint               timeout_ns = default_timeout_ns,
+                            input  uvm_reg_map        map = null,
+                            input  uvm_reg_frontdoor  user_ftdr = default_user_frontdoor);
+    if (backdoor) begin
+      value = csr_peek(ptr, check);
+      status = UVM_IS_OK;
+      return;
+    end
+    fork
+      begin : isolation_fork
+        csr_field_t   csr_or_fld;
+        fork
+          begin
+            increment_outstanding_access();
+            csr_or_fld = decode_csr_or_field(ptr);
+            if (user_ftdr != null) csr_or_fld.csr.set_frontdoor(user_ftdr);
+            if (csr_or_fld.field != null) begin
+              csr_or_fld.field.read(.status(status), .value(value), .path(path), .map(map),
+                                    .prior(100));
+            end else begin
+              csr_or_fld.csr.read(.status(status), .value(value), .path(path), .map(map),
+                                  .prior(100));
+            end
+            // TODO: need to remove the frontdoor to switch back to the default,
+            // but this doesn't work: if (user_ftdr != null) ptr.set_frontdoor(null);
+            if (check == UVM_CHECK && !under_reset) begin
+              `DV_CHECK_EQ(status, UVM_IS_OK,
+                           $sformatf("trying to read csr/field %0s", ptr.get_full_name()),
+                           error, $sformatf("%m"))
+            end
+            decrement_outstanding_access();
+          end
+          begin
+            `DV_WAIT_TIMEOUT(timeout_ns, $sformatf("%m"),
+                             $sformatf("Timeout waiting to csr_rd %0s (addr=0x%0h)",
+                                       ptr.get_full_name(), csr_or_fld.csr.get_address()))
+          end
+        join_any
+        disable fork;
+      end : isolation_fork
+    join
+  endtask
+
+  // backdoor read csr
+  // uvm_reg::peek() returns a 2-state value, directly get data from hdl path
+  function automatic uvm_reg_data_t csr_peek(uvm_object      ptr,
+                                             uvm_check_e     check = default_csr_check,
+                                             bkdr_reg_path_e kind = BkdrRegPathRtl);
+    csr_field_t    csr_or_fld = decode_csr_or_field(ptr);
+    uvm_reg        csr = csr_or_fld.csr;
+    uvm_reg_data_t value = 0;
+
+    uvm_hdl_path_concat paths[$];
+    csr.get_full_hdl_path(paths, kind.name);
+
+    `DV_CHECK_FATAL(paths.size() > 0,
+                    $sformatf("No backdoor defined for %0s path's %0s",
+                              csr.get_full_name(), kind.name),
+                    $sformatf("%m"))
+
+    foreach (paths[0].slices[i]) begin
+      uvm_reg_data_t field_val;
+      `DV_CHECK_FATAL(uvm_hdl_read(paths[0].slices[i].path, field_val),
+                      $sformatf("Failed to read %s, slice %d, at path %s",
+                                csr.get_full_name(), i, paths[0].slices[i].path),
+                      $sformatf("%m"))
+      if (check == UVM_CHECK) `DV_CHECK_EQ($isunknown(field_val), 0, "", error, $sformatf("%m"))
+
+      value |= field_val << paths[0].slices[i].offset;
+    end
+
+    // We now have the contents of the field or register in value. If ptr was a sub-field of some
+    // register, it will be laid out in the same way as the field is laid out in the register.
+    // That's no problem: we can just extract the relevant field from the laid-out value here.
+    if (csr_or_fld.field != null) value = get_field_val(csr_or_fld.field, value);
+
+    return value;
+  endfunction
+
+  task automatic csr_rd_check(input  uvm_object         ptr,
+                              input  uvm_check_e        check = default_csr_check,
+                              input  uvm_path_e         path = UVM_DEFAULT_PATH,
+                              input  bit                blocking = default_csr_blocking,
+                              input  bit                backdoor = 0,
+                              input  uint               timeout_ns = default_timeout_ns,
+                              input  bit                compare = 1'b1,
+                              input  bit                compare_vs_ral = 1'b0,
+                              input  uvm_reg_data_t     compare_mask = '1,
+                              input  uvm_reg_data_t     compare_value = 0,
+                              input  string             err_msg = "",
+                              input  uvm_reg_map        map = null,
+                              input  uvm_reg_frontdoor  user_ftdr = default_user_frontdoor);
+    fork
+      begin : isolation_fork
+        fork
+          begin
+            csr_field_t     csr_or_fld;
+            uvm_status_e    status;
+            uvm_reg_data_t  obs;
+            uvm_reg_data_t  exp;
+            uvm_reg_data_t  reset_val;
+
+            csr_or_fld = decode_csr_or_field(ptr);
+
+            csr_rd_sub(.ptr(ptr), .value(obs), .status(status), .check(check), .path(path),
+                       .backdoor(backdoor), .timeout_ns(timeout_ns), .map(map),
+                       .user_ftdr(user_ftdr));
+
+            // get mirrored value after read to make sure the read reg access is updated
+            if (csr_or_fld.field != null) begin
+              exp = csr_or_fld.field.get_mirrored_value();
+              reset_val = csr_or_fld.field.get_reset();
+            end else begin
+              exp = csr_or_fld.csr.get_mirrored_value();
+              reset_val = csr_or_fld.csr.get_reset();
+            end
+            if (compare && status == UVM_IS_OK && !under_reset) begin
+              obs = obs & compare_mask;
+              exp = (compare_vs_ral ? exp : compare_value) & compare_mask;
+              `DV_CHECK_EQ(obs, exp, $sformatf("Regname: %0s reset value: 0x%0h %0s",
+                                               ptr.get_full_name(), reset_val, err_msg),
+                           error, $sformatf("%m"))
+            end
+          end
+        join_none
+        if (blocking) wait fork;
+        // Add #0 to ensure that this thread starts executing before any subsequent call
+        else #0;
+      end : isolation_fork
+    join
+  endtask
+
+  // task to read all csrs and check against ral expected value. Mainly used after reset
+  task automatic read_and_check_all_csrs(input uvm_reg_block ral);
+    uvm_reg ral_csrs[$];
+    ral.get_registers(ral_csrs);
+    ral_csrs.shuffle();
+
+    foreach (ral_csrs[i]) csr_rd_check(.ptr(ral_csrs[i]), .compare_vs_ral(1));
+  endtask
+
+  // Checks the csr value against predicted value by reading the whole CSR or individual CSR
+  // fields.
+  // This task will skip read check if the CSR field is excluded.
+  task automatic do_check_csr_or_field_rd(input uvm_reg         csr,
+                                          input bit             do_csr_field_rd_check = $urandom(),
+                                          input bit             blocking = 0,
+                                          input bit             compare = 1,
+                                          input bit             compare_vs_ral = 1,
+                                          input csr_excl_type_e csr_excl_type = CsrNoExcl,
+                                          input csr_test_type_e csr_test_type = CsrRwTest,
+                                          input csr_excl_item   csr_excl_item = get_excl_item(csr));
+    uvm_reg_data_t compare_mask;
+
+    // Check if parent block or register is excluded from read-check
+    if (csr_excl_item != null && csr_excl_item.is_excl(csr, csr_excl_type, csr_test_type)) begin
+      `uvm_info($sformatf("%m"),
+                $sformatf("Skipping register %0s due to CsrExclWriteCheck exclusion",
+                          csr.get_full_name()), UVM_MEDIUM)
+      return;
+    end
+
+    compare_mask = get_mask_excl_fields(csr, csr_excl_type, csr_test_type, csr_excl_item);
+
+    if (!do_csr_field_rd_check) begin
+      csr_rd_check(.ptr           (csr),
+                   .blocking      (blocking),
+                   .compare       (compare),
+                   .compare_vs_ral(compare_vs_ral),
+                   .compare_mask  (compare_mask));
+    end else begin
+      uvm_reg_field test_fields[$];
+      csr.get_fields(test_fields);
+      test_fields.shuffle();
+      foreach (test_fields[i]) begin
+        bit field_compare = 1;
+        if (csr_excl_item != null) begin
+          field_compare = !csr_excl_item.is_excl(test_fields[i], csr_excl_type, csr_test_type);
+        end
+        csr_rd_check(.ptr           (test_fields[i]),
+                     .blocking      (blocking),
+                     .compare       (field_compare && compare),
+                     .compare_vs_ral(compare_vs_ral));
+      end
+    end
+   endtask
+
+  // Poll a csr or csr field continuously until its value is as expected.
+  //
+  // The CSR or field is polled by performing reads at the given ptr and its current value is
+  // compared with exp_data using the comparison in compare_op. The task exits when the comparison
+  // becomes true.
+  //
+  // To avoid this task waiting forever, there is an upper bound given with timeout_ns. If the task
+  // does not finish for another reason in that time, the test will fail.
+  //
+  // CSR reads are performed using frontdoor access. If the backdoor argument is true, then they
+  // will be performed with a backdoor access instead.
+  //
+  // Successive CSR reads are back-to-back unless spinwait_delay_ns is positive. If backdoor is
+  // true, the delay between successive reads is made to be at least 1ns.
+  task automatic csr_spinwait(input uvm_object          ptr,
+                              input uvm_reg_data_t      exp_data,
+                              input uvm_check_e         check = default_csr_check,
+                              input uvm_path_e          path = UVM_DEFAULT_PATH,
+                              input uvm_reg_map         map = null,
+                              input  uvm_reg_frontdoor  user_ftdr = default_user_frontdoor,
+                              input uint                spinwait_delay_ns = 0,
+                              input uint                timeout_ns = default_spinwait_timeout_ns,
+                              input compare_op_e        compare_op = CompareOpEq,
+                              input bit                 backdoor = 0,
+                              input uvm_verbosity       verbosity = UVM_HIGH);
+    static int count;
+    automatic int lcount;
+
+    // Increment count so that each call to csr_spinwait has a different index (to help debugging)
+    count++;
+
+    // Take an (automatic) copy of lcount. This will act as a snapshot of the value that the count
+    // had when this task started, giving the index of *this* call.
+    lcount = count;
+
+    `uvm_info($sformatf("%m"), $sformatf(
+                "- (call_count=%0d, backdoor=%0d, exp_data=%0d, ptr=%s)",
+                lcount, backdoor, exp_data, ptr.get_name()), verbosity)
+    fork
+      begin : isolation_fork
+        csr_field_t     csr_or_fld;
+        uvm_reg_data_t  read_data;
+
+        csr_or_fld = decode_csr_or_field(ptr);
+        if (backdoor && spinwait_delay_ns == 0) spinwait_delay_ns = 1;
+        fork
+          // Repeatedly do reads of the value at path and stop when the value satisfies the supplied
+          // comparison. If it is positive, wait spinwait_delay_ns nanoseconds between reads. If we
+          // enter reset, stop immediately (once the current csr_rd call has finished).
+          forever begin
+            `uvm_info($sformatf("%m"), $sformatf("In csr_spinwait - call_count = %0d", lcount),
+                      verbosity)
+
+            // Wait spinwait_delay_ns nanoseconds between each read (and before the first one), but
+            // stop waiting immediately if we see a reset. Note that we can't wait for a reset in
+            // parallel with the csr_rd below, because we use disable fork when a process finishes
+            // and csr_rd has internal state that it must clean up without being killed.
+            if (spinwait_delay_ns) begin
+              fork begin : iso_fork
+                fork
+                  #(spinwait_delay_ns * 1ns);
+                  wait (under_reset);
+                join_any
+                disable fork;
+              end : iso_fork join
+            end
+
+            // If we are in reset, stop the wait immediately.
+            if (under_reset) break;
+
+            csr_rd(.ptr(ptr), .value(read_data), .check(check), .path(path),
+                   .blocking(1), .map(map), .user_ftdr(user_ftdr), .backdoor(backdoor));
+            `uvm_info($sformatf("%m"),
+                      $sformatf("ptr %0s == 0x%0h", ptr.get_full_name(), read_data), verbosity)
+            case (compare_op)
+              CompareOpEq:     if (read_data ==  exp_data) break;
+              CompareOpCaseEq: if (read_data === exp_data) break;
+              CompareOpNe:     if (read_data !=  exp_data) break;
+              CompareOpCaseNe: if (read_data !== exp_data) break;
+              CompareOpGt:     if (read_data >   exp_data) break;
+              CompareOpGe:     if (read_data >=  exp_data) break;
+              CompareOpLt:     if (read_data <   exp_data) break;
+              CompareOpLe:     if (read_data <=  exp_data) break;
+              default: begin
+                `uvm_fatal(ptr.get_full_name(), $sformatf("invalid operator:%0s", compare_op))
+              end
+            endcase
+          end
+          // Wait for timeout_ns nanoseconds and then fail with an error (because this process
+          // should have been killed before then)
+          `DV_WAIT_TIMEOUT(timeout_ns, $sformatf("%m"),
+                           $sformatf({"timeout %0s (addr=0x%0h, Comparison=%s, ",
+                                      "exp_data=0x%0h, call_count=%0d)"},
+                                     ptr.get_full_name(), csr_or_fld.csr.get_address(),
+                                     compare_op.name, exp_data, lcount))
+        join_any
+        disable fork;
+      end : isolation_fork
+    join
+  endtask
