diff --git a/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_dma_xfer_item.svh b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_dma_xfer_item.svh
new file mode 100644
index 00000000..7140dddb
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_dma_xfer_item.svh
@@ -0,0 +1,122 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//----------------------------------------------------------------------
+// DESCRIPTION: Constrained-random DMA transfer descriptor.
+//
+// One AXI DMA transfer constrained legal for the SRAM window. Relative offsets
+// are randomized for backdoor access; src_addr()/dst_addr() derive the absolute
+// DMA addresses.
+//----------------------------------------------------------------------
+
+class soc_ifc_dma_xfer_item extends uvm_object;
+
+  `uvm_object_utils( soc_ifc_dma_xfer_item )
+
+  // ---- Non-random geometry knobs ----
+  bit [63:0]       base_addr;
+  longint unsigned window_bytes;
+  protected bit    configured;
+  // Max transfer size in words, supplied via configure(). Default exceeds the
+  // 512B (128-word) DMA FIFO to exercise wrap, stays under mailbox capacity, and
+  // caps sim runtime.
+  int unsigned     max_words;
+
+  // ---- Randomized transfer fields (SRAM-relative byte offsets) ----
+  rand dma_route_e  route;
+  rand int unsigned num_words;
+  rand longint unsigned src_offset;
+  rand longint unsigned dst_offset;
+
+  // Payload words moved by the transfer. Auto-filled by post_randomize; set
+  // directly for a directed transfer.
+  bit [31:0] payload[];
+
+  function new(string name = "soc_ifc_dma_xfer_item");
+    super.new(name);
+    configured = 1'b0;
+  endfunction
+
+  virtual function void configure(input bit [63:0]       base_addr,
+                                  input longint unsigned window_bytes,
+                                  input int unsigned     max_words = 160);
+    // Sanity check: max_words (words) must fit the SRAM window. Compare against
+    // window_bytes/4 so the multiply-by-4 cannot overflow.
+    if (max_words == 0 || max_words > (window_bytes / 4))
+      `uvm_fatal(get_type_name(),
+        $sformatf("Illegal geometry: max_words=%0d must be >0 and <= window_bytes/4=%0d (window_bytes=%0d)",
+                  max_words, (window_bytes / 4), window_bytes))
+    this.base_addr    = base_addr;
+    this.window_bytes = window_bytes;
+    this.max_words    = max_words;
+    configured = 1'b1;
+  endfunction
+
+  // Reject a max_words the window cannot hold (compare via window_bytes/4 so the
+  // check cannot overflow).
+  function void pre_randomize();
+    if (!configured)
+      `uvm_fatal(get_type_name(), "DMA SRAM geometry must be configured before randomize()")
+    if (max_words == 0 || max_words > (window_bytes / 4))
+      `uvm_fatal(get_type_name(),
+        $sformatf("Illegal geometry knobs: max_words=%0d must be >0 and <= window_bytes/4=%0d (window_bytes=%0d)",
+                  max_words, (window_bytes / 4), window_bytes))
+  endfunction
+
+  function void post_randomize();
+    payload = new[num_words];
+    foreach (payload[i]) payload[i] = $urandom();
+  endfunction
+
+  function int unsigned byte_count();
+    return num_words * 4;
+  endfunction
+
+  function bit [63:0] src_addr();
+    return base_addr + src_offset;
+  endfunction
+
+  function bit [63:0] dst_addr();
+    return base_addr + dst_offset;
+  endfunction
+
+  // Transfer size: at least one word, bounded by the runtime knob.
+  constraint c_num_words { num_words inside {[1:max_words]}; }
+
+  // 4-byte alignment (DMA requires byte_count/addresses aligned to DW bytes).
+  constraint c_align {
+    src_offset[1:0] == 2'b0;
+    dst_offset[1:0] == 2'b0;
+  }
+
+  constraint c_window_fit {
+    num_words <= (window_bytes / 4);
+    src_offset <= (window_bytes - (num_words * 4));
+    dst_offset <= (window_bytes - (num_words * 4));
+  }
+
+  // AXI2AXI copies src->dst within the SRAM, so its ranges must be disjoint.
+  constraint c_no_overlap {
+    (route == XFER_AXI2AXI) ->
+      ((src_offset + (num_words * 4) <= dst_offset) ||
+       (dst_offset + (num_words * 4) <= src_offset));
+  }
+
+  virtual function string convert2string();
+    return $sformatf("route=%s num_words=%0d byte_count=%0d src_addr=0x%0h src_offset=0x%0h dst_addr=0x%0h dst_offset=0x%0h",
+                     route.name(), num_words, byte_count(),
+                     src_addr(), src_offset, dst_addr(), dst_offset);
+  endfunction
+
+endclass
diff --git a/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_reg_soc_access_sequence.svh b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_reg_soc_access_sequence.svh
new file mode 100644
index 00000000..c56216e6
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_reg_soc_access_sequence.svh
@@ -0,0 +1,81 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//----------------------------------------------------------------------
+// DESCRIPTION: Reusable SoC-AXI access sequence against the AXI DMA registers.
+//
+// Continuously drives SoC-AXI reads/writes to every DMA register with random
+// AxUSERs. The DMA block is Caliptra-uC-only, so every access must be rejected;
+// that is checked passively by the predictor + scoreboard (predicted SLVERR) and
+// the bound assertion soc_ifc_arb.ERR_ARB_SOC_DMA_GNT.
+//
+// Standalone and composable: a test can fork it as background traffic and end it
+// via stop(), or bound it with num_accesses.
+//----------------------------------------------------------------------
+
+class soc_ifc_env_dma_reg_soc_access_sequence extends soc_ifc_env_dma_sequence_base;
+
+  `uvm_object_utils( soc_ifc_env_dma_reg_soc_access_sequence )
+
+  // 0 = run until stop() is called; otherwise stop after this many accesses.
+  int unsigned num_accesses = 0;
+
+  protected bit stop_access;
+
+  function new(string name = "" );
+    super.new(name);
+  endfunction
+
+  // Request the access loop to finish (used when forked as background traffic).
+  virtual function void stop();
+    stop_access = 1'b1;
+  endfunction
+
+  virtual task body();
+    uvm_reg           soc_regs[$];
+    caliptra_axi_user axi_user_obj;
+    uvm_status_e      sts;
+    uvm_reg_data_t    rdata;
+    uvm_reg_data_t    wdata;
+    int               sel;
+    int unsigned      count;
+
+    if (reg_model == null)
+      reg_model = configuration.soc_ifc_rm;
+
+    reg_model.axi_dma_reg_rm.axi_dma_reg_AXI_map.get_registers(soc_regs);
+    axi_user_obj = new("axi_user_obj");
+    stop_access  = 1'b0;
+    count        = 0;
+
+    // Any AxUSER is rejected for the DMA block, so a raw random user suffices.
+    while (!stop_access && (num_accesses == 0 || count < num_accesses)) begin
+      sel = $urandom_range(soc_regs.size()-1, 0);
+      if (!axi_user_obj.randomize())
+        `uvm_fatal("DMA_SOC_SEQ", "Failed to randomize AxUSER")
+      if ($urandom_range(1,0)) begin
+        soc_regs[sel].read(sts, rdata, UVM_FRONTDOOR, reg_model.soc_ifc_AXI_map, this, .extension(axi_user_obj));
+      end
+      else begin
+        if (!std::randomize(wdata))
+          `uvm_fatal("DMA_SOC_SEQ", "Failed to randomize write data")
+        soc_regs[sel].write(sts, wdata, UVM_FRONTDOOR, reg_model.soc_ifc_AXI_map, this, .extension(axi_user_obj));
+      end
+      count++;
+    end
+
+    `uvm_info("DMA_SOC_SEQ", $sformatf("Completed %0d SoC-AXI DMA register accesses (all expected rejected)", count), UVM_LOW)
+  endtask
+
+endclass
diff --git a/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_sequence_base.svh b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_sequence_base.svh
new file mode 100644
index 00000000..0c8a128e
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_sequence_base.svh
@@ -0,0 +1,321 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//----------------------------------------------------------------------
+// DESCRIPTION: Reusable base for soc_ifc AXI DMA environment sequences.
+//
+// Provides the DMA transaction API (arm/status/fifo/mbox helpers,
+// dma_transfer_and_verify, dma_transfer_rand) for derived DMA sequences. SRAM
+// access goes through configuration.dma_axi_sram_backdoor, so no SRAM geometry
+// or hierarchy path is hard-coded here.
+//----------------------------------------------------------------------
+
+class soc_ifc_env_dma_sequence_base extends soc_ifc_env_sequence_base #(.CONFIG_T(soc_ifc_env_configuration_t));
+
+  `uvm_object_utils( soc_ifc_env_dma_sequence_base )
+
+  // SRAM access is delegated to configuration.dma_axi_sram_backdoor, so this
+  // sequence holds no SRAM geometry or hierarchy path.
+
+  // DMA internal FIFO max depth (in words), read once from cap.fifo_max_depth.
+  protected int unsigned fifo_max_depth;
+
+  // Running count of transfers issued, used for log/error context.
+  protected int unsigned transfer_id;
+
+  function new(string name = "" );
+    super.new(name);
+  endfunction
+
+  virtual task pre_body();
+    super.pre_body();
+    reg_model = configuration.soc_ifc_rm;
+    if (configuration.dma_axi_sram_backdoor == null)
+      `uvm_fatal("DMA_SEQ_BASE",
+        "configuration.dma_axi_sram_backdoor is null; test_top must configure it before DMA sequences run")
+  endtask
+
+  //==========================================
+  // DMA register API (uC / AHB side).
+  //==========================================
+  // Read cap.fifo_max_depth (words) into fifo_max_depth.
+  virtual task dma_read_cap();
+    uvm_status_e   sts;
+    uvm_reg_data_t cap_val;
+    reg_model.axi_dma_reg_rm.cap.read(sts, cap_val, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    fifo_max_depth = int'((cap_val >> reg_model.axi_dma_reg_rm.cap.fifo_max_depth.get_lsb_pos()) &
+                          ((1 << reg_model.axi_dma_reg_rm.cap.fifo_max_depth.get_n_bits()) - 1));
+    if (fifo_max_depth == 0) begin
+      fifo_max_depth = 1; // guard against unexpected 0 to avoid a stuck push loop
+      `uvm_warning("DMA_SEQ_BASE", "cap.fifo_max_depth read as 0; defaulting to 1")
+    end
+  endtask
+
+  // Program the DMA config registers and set ctrl.go over AHB.
+  virtual task dma_arm(input bit [63:0] src_addr,
+                       input bit [63:0] dst_addr,
+                       input int unsigned byte_count,
+                       input int unsigned block_size,
+                       input bit [1:0]  rd_route,
+                       input bit [2:0]  wr_route);
+    uvm_status_e   sts;
+    uvm_reg_data_t ctrl_val;
+    reg_model.axi_dma_reg_rm.src_addr_l.write(sts, src_addr[31:0],  UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    reg_model.axi_dma_reg_rm.src_addr_h.write(sts, src_addr[63:32], UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    reg_model.axi_dma_reg_rm.dst_addr_l.write(sts, dst_addr[31:0],  UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    reg_model.axi_dma_reg_rm.dst_addr_h.write(sts, dst_addr[63:32], UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    reg_model.axi_dma_reg_rm.byte_count.write(sts, byte_count,      UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    reg_model.axi_dma_reg_rm.block_size.write(sts, block_size,      UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    // Compose ctrl (go=1 + routes, all other fields 0) from RAL field positions and
+    // issue one explicit write. Explicit compose (vs set()/update()) is deterministic
+    // and avoids re-writing any stale desired state in other ctrl fields.
+    ctrl_val = (uvm_reg_data_t'(1)        << reg_model.axi_dma_reg_rm.ctrl.go.get_lsb_pos())       |
+               (uvm_reg_data_t'(rd_route) << reg_model.axi_dma_reg_rm.ctrl.rd_route.get_lsb_pos()) |
+               (uvm_reg_data_t'(wr_route) << reg_model.axi_dma_reg_rm.ctrl.wr_route.get_lsb_pos());
+    reg_model.axi_dma_reg_rm.ctrl.write(sts, ctrl_val, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+  endtask
+
+  // Recover the DMA from a DMA_ERROR state: ctrl.flush resets the FSM to IDLE and
+  // clears the FIFO (see axi_dma_ctrl). Harmless when idle (flush self-clears).
+  virtual task dma_flush();
+    uvm_status_e   sts;
+    uvm_reg_data_t ctrl_val;
+    ctrl_val = (uvm_reg_data_t'(1) << reg_model.axi_dma_reg_rm.ctrl.flush.get_lsb_pos());
+    reg_model.axi_dma_reg_rm.ctrl.write(sts, ctrl_val, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+  endtask
+
+  // Read status0 over AHB, returning busy/error/fifo_depth. Parse the value read
+  // back from the DUT (d); field positions/widths come from the RAL model.
+  virtual task dma_read_status(output bit busy, output bit err, output int unsigned fifo_depth);
+    uvm_status_e   sts;
+    uvm_reg_data_t d;
+    reg_model.axi_dma_reg_rm.status0.read(sts, d, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    busy       = d[reg_model.axi_dma_reg_rm.status0.busy.get_lsb_pos()];
+    err        = d[reg_model.axi_dma_reg_rm.status0.error.get_lsb_pos()];
+    fifo_depth = int'((d >> reg_model.axi_dma_reg_rm.status0.fifo_depth.get_lsb_pos()) &
+                      ((1 << reg_model.axi_dma_reg_rm.status0.fifo_depth.get_n_bits()) - 1));
+  endtask
+
+  // Poll status0 until the DMA is idle (busy==0) or reports an error.
+  virtual task dma_wait_idle(output bit err);
+    bit busy;
+    int unsigned fd;
+    do begin
+      dma_read_status(busy, err, fd);
+    end while (busy && !err);
+    // Detection only; callers are the contextual error reporter.
+  endtask
+
+  // Push one payload word into the DMA FIFO over AHB (wr_route=AHB_FIFO).
+  // err is set (and the wait loop broken) if the DMA reports status0.error.
+  virtual task dma_fifo_push(input bit [31:0] data, output bit err);
+    uvm_status_e sts;
+    bit busy;
+    int unsigned fd;
+    err = 1'b0;
+    // Wait until the FIFO has room (depth != max), aborting on a DMA error.
+    do begin
+      dma_read_status(busy, err, fd);
+      if (err) return;
+    end while (fd == fifo_max_depth);
+    reg_model.axi_dma_reg_rm.write_data.write(sts, data, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+  endtask
+
+  // Pop one payload word from the DMA FIFO over AHB (rd_route=AHB_FIFO).
+  // err is set (and the wait loop broken) if the DMA reports status0.error.
+  virtual task dma_fifo_pop(output bit [31:0] data, output bit err);
+    uvm_status_e   sts;
+    uvm_reg_data_t d;
+    bit busy;
+    int unsigned fd;
+    err  = 1'b0;
+    data = '0;
+    // Wait until the FIFO has data (depth != 0), aborting on a DMA error.
+    do begin
+      dma_read_status(busy, err, fd);
+      if (err) return;
+    end while (fd == 0);
+    reg_model.axi_dma_reg_rm.read_data.read(sts, d, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    data = d[31:0];
+  endtask
+
+  // Acquire the mailbox lock for the microcontroller over AHB. Reading mbox_lock
+  // returns 0 and grants the lock when it was free; the DMA MBOX route requires
+  // the uC to hold the lock (uc_has_lock in mbox.sv). ok=1 if acquired.
+  virtual task dma_mbox_lock_acquire(output bit ok);
+    uvm_status_e   sts;
+    uvm_reg_data_t d;
+    reg_model.mbox_csr_rm.mbox_lock.read(sts, d, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+    ok = (d[0] == 1'b0);
+  endtask
+
+  virtual task dma_mbox_unlock();
+    uvm_status_e sts;
+    reg_model.mbox_csr_rm.mbox_unlock.write(sts, 1, UVM_FRONTDOOR, reg_model.soc_ifc_AHB_map, this);
+  endtask
+
+  //==========================================
+  // Run and verify one DMA transfer described by item.
+  //==========================================
+  virtual task dma_transfer_and_verify(input  soc_ifc_dma_xfer_item item,
+                                       output bit                   err);
+    int unsigned num_words;
+    int unsigned byte_count;
+    localparam int unsigned block_size = 0;
+    localparam bit [63:0] mbox_addr = 64'h0;
+    bit [63:0]   src_addr;
+    bit [63:0]   dst_addr;
+    bit [31:0]   rd_data;
+    bit          lock_ok;
+
+    err       = 1'b0;
+    num_words = item.payload.size();
+    src_addr  = item.src_addr();
+    dst_addr  = item.dst_addr();
+    if (num_words == 0) begin
+      `uvm_fatal("DMA_XFER_SEQ", "dma_transfer_and_verify called with empty payload")
+    end
+    byte_count = num_words * 4;
+    transfer_id++;
+
+    // Start each transfer from a clean DMA state so a prior transfer's error
+    // (status0.error / DMA_ERROR, which is sticky until flushed) cannot cascade
+    // into this one and mask/inflate the real failure count.
+    dma_flush();
+
+    case (item.route)
+      XFER_AXI2AXI: begin
+        // Source SRAM -> DMA -> destination SRAM (both over AXI).
+        for (int w = 0; w < num_words; w++)
+          configuration.dma_axi_sram_backdoor.write32_offset(item.src_offset + (w*4), item.payload[w]);
+        dma_arm(src_addr, dst_addr, byte_count, block_size,
+                axi_dma_reg__ctrl__rd_route__rd_route_e__AXI_WR,
+                axi_dma_reg__ctrl__wr_route__wr_route_e__AXI_RD);
+        dma_wait_idle(err);
+        if (err) begin
+          `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s", transfer_id, item.route.name()))
+          return;
+        end
+        for (int w = 0; w < num_words; w++) begin
+          configuration.dma_axi_sram_backdoor.read32_offset(item.dst_offset + (w*4), rd_data);
+          if (rd_data !== item.payload[w])
+            `uvm_error("DMA_XFER_SEQ", $sformatf("AXI2AXI xfer %0d word %0d mismatch: exp=0x%08x got=0x%08x", transfer_id, w, item.payload[w], rd_data))
+        end
+      end
+      XFER_RD_FIFO: begin
+        // Source SRAM -> DMA FIFO; uC pops each word over AHB and compares.
+        for (int w = 0; w < num_words; w++)
+          configuration.dma_axi_sram_backdoor.write32_offset(item.src_offset + (w*4), item.payload[w]);
+        dma_arm(src_addr, 64'h0, byte_count, block_size,
+                axi_dma_reg__ctrl__rd_route__rd_route_e__AHB_FIFO,
+                axi_dma_reg__ctrl__wr_route__wr_route_e__DISABLE);
+        for (int w = 0; w < num_words; w++) begin
+          dma_fifo_pop(rd_data, err);
+          if (err) begin
+            `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s", transfer_id, item.route.name()))
+            return;
+          end
+          if (rd_data !== item.payload[w])
+            `uvm_error("DMA_XFER_SEQ", $sformatf("RD_FIFO xfer %0d word %0d mismatch: exp=0x%08x got=0x%08x", transfer_id, w, item.payload[w], rd_data))
+        end
+        dma_wait_idle(err);
+        if (err) begin
+          `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s", transfer_id, item.route.name()))
+          return;
+        end
+      end
+      XFER_WR_FIFO: begin
+        // uC pushes each word over AHB into the DMA FIFO -> destination SRAM.
+        dma_arm(64'h0, dst_addr, byte_count, block_size,
+                axi_dma_reg__ctrl__rd_route__rd_route_e__DISABLE,
+                axi_dma_reg__ctrl__wr_route__wr_route_e__AHB_FIFO);
+        for (int w = 0; w < num_words; w++) begin
+          dma_fifo_push(item.payload[w], err);
+          if (err) begin
+            `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s", transfer_id, item.route.name()))
+            return;
+          end
+        end
+        dma_wait_idle(err);
+        if (err) begin
+          `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s", transfer_id, item.route.name()))
+          return;
+        end
+        for (int w = 0; w < num_words; w++) begin
+          configuration.dma_axi_sram_backdoor.read32_offset(item.dst_offset + (w*4), rd_data);
+          if (rd_data !== item.payload[w])
+            `uvm_error("DMA_XFER_SEQ", $sformatf("WR_FIFO xfer %0d word %0d mismatch: exp=0x%08x got=0x%08x", transfer_id, w, item.payload[w], rd_data))
+        end
+      end
+      XFER_MBOX: begin
+        // Mailbox round-trip under one uC lock: src SRAM -> mailbox (rd MBOX),
+        // then mailbox -> dst SRAM (wr MBOX).
+        dma_mbox_lock_acquire(lock_ok);
+        if (!lock_ok) begin
+          `uvm_error("DMA_XFER_SEQ", $sformatf("Failed to acquire mailbox lock for xfer %0d", transfer_id))
+          return;
+        end
+        for (int w = 0; w < num_words; w++)
+          configuration.dma_axi_sram_backdoor.write32_offset(item.src_offset + (w*4), item.payload[w]);
+        dma_arm(src_addr, mbox_addr, byte_count, block_size,
+                axi_dma_reg__ctrl__rd_route__rd_route_e__MBOX,
+                axi_dma_reg__ctrl__wr_route__wr_route_e__DISABLE);
+        dma_wait_idle(err);
+        if (err) begin
+          dma_mbox_unlock();
+          `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s (SRAM->mbox)", transfer_id, item.route.name()))
+          return;
+        end
+        dma_arm(mbox_addr, dst_addr, byte_count, block_size,
+                axi_dma_reg__ctrl__rd_route__rd_route_e__DISABLE,
+                axi_dma_reg__ctrl__wr_route__wr_route_e__MBOX);
+        dma_wait_idle(err);
+        dma_mbox_unlock();
+        if (err) begin
+          `uvm_error("DMA_XFER_SEQ", $sformatf("DMA reported error (status0.error) during xfer %0d route=%s (mbox->SRAM)", transfer_id, item.route.name()))
+          return;
+        end
+        for (int w = 0; w < num_words; w++) begin
+          configuration.dma_axi_sram_backdoor.read32_offset(item.dst_offset + (w*4), rd_data);
+          if (rd_data !== item.payload[w])
+            `uvm_error("DMA_XFER_SEQ", $sformatf("MBOX xfer %0d word %0d mismatch: exp=0x%08x got=0x%08x", transfer_id, w, item.payload[w], rd_data))
+        end
+      end
+      default: begin
+        `uvm_fatal("DMA_XFER_SEQ", $sformatf("dma_transfer_and_verify called with non-concrete route %s", item.route.name()))
+      end
+    endcase
+
+    `uvm_info("DMA_XFER_SEQ", $sformatf("Completed DMA transfer %0d route=%s byte_count=%0d", transfer_id, item.route.name(), byte_count), UVM_LOW)
+  endtask
+
+  //==========================================
+  // Randomize a soc_ifc_dma_xfer_item, then run+verify.
+  //==========================================
+  virtual task dma_transfer_rand(int unsigned dma_max_words, output bit err);
+    soc_ifc_dma_xfer_item item;
+
+    item = soc_ifc_dma_xfer_item::type_id::create("item");
+    item.configure(configuration.dma_axi_sram_backdoor.get_base_addr(),
+                   configuration.dma_axi_sram_backdoor.get_size_bytes(),
+                   dma_max_words);
+    if (!item.randomize())
+      `uvm_fatal("DMA_XFER_SEQ", "Failed to randomize soc_ifc_dma_xfer_item")
+
+    `uvm_info("DMA_XFER_SEQ", $sformatf("Randomized transfer: %s", item.convert2string()), UVM_HIGH)
+
+    dma_transfer_and_verify(item, err);
+  endtask
+
+endclass
diff --git a/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_wr_fifo_directed_sequence.svh b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_wr_fifo_directed_sequence.svh
new file mode 100644
index 00000000..cd55352c
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_wr_fifo_directed_sequence.svh
@@ -0,0 +1,105 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//----------------------------------------------------------------------
+// DESCRIPTION: Directed, non-random WR_FIFO / write_data DMA sequence.
+//
+// Focuses on the AXI DMA write-data FIFO (wr_route=AHB_FIFO) and the write_data
+// register, deterministically (no randomization) so it runs quickly. It forks
+// two concurrent activities:
+//   1. Functional: the microcontroller pushes a fixed payload through write_data
+//      over AHB and the DMA writes it to the destination SRAM; verified by the
+//      bounded AXI SRAM backdoor.
+//   2. Security (in parallel, while the DMA transfer is active): the SoC-AXI side
+//      CONTINUOUSLY writes EVERY DMA register (including write_data) with fixed
+//      data and a fixed AxUSER, repeating until the transfer completes. The DMA
+//      block is Caliptra-uC-only, so all of these must be rejected (SLVERR) and
+//      must not disturb the transfer. Verified passively by the predictor +
+//      scoreboard and the bound assertion soc_ifc_arb.ERR_ARB_SOC_DMA_GNT. The
+//      stimulus values/targets are fixed (no randomization); only the number of
+//      passes adapts to the transfer duration.
+//----------------------------------------------------------------------
+
+class soc_ifc_env_dma_wr_fifo_directed_sequence extends soc_ifc_env_dma_sequence_base;
+
+  `uvm_object_utils( soc_ifc_env_dma_wr_fifo_directed_sequence )
+
+  // Deterministic transfer / stimulus parameters (no randomization).
+  localparam int unsigned NUM_WORDS = 256;                // longer transfer -> more overlap
+  localparam bit [31:0]   SOC_WDATA = 32'hDEAD_BEEF;      // fixed SoC-AXI write payload
+
+  function new(string name = "" );
+    super.new(name);
+  endfunction
+
+  virtual task body();
+    caliptra_axi_user axi_user_obj;
+    uvm_reg           soc_regs[$];
+    bit               err;
+    bit               xfer_done;
+    soc_ifc_dma_xfer_item item;
+
+    if (reg_model == null)
+      reg_model = configuration.soc_ifc_rm;
+
+    dma_read_cap(); // FIFO max depth, needed by the AHB_FIFO write route
+
+    // Directed item: fixed route/size/offsets and a fixed-pattern payload.
+    item = soc_ifc_dma_xfer_item::type_id::create("item");
+    item.configure(configuration.dma_axi_sram_backdoor.get_base_addr(),
+                   configuration.dma_axi_sram_backdoor.get_size_bytes());
+    item.route      = XFER_WR_FIFO;
+    item.num_words  = NUM_WORDS;
+    item.src_offset = 0;
+    item.dst_offset = 0;
+    item.payload    = new[NUM_WORDS];
+    foreach (item.payload[w]) item.payload[w] = 32'hA5A5_0000 | w;
+
+    axi_user_obj = new("axi_user_obj");
+    axi_user_obj.set_addr_user('1); // any SoC user is rejected for the DMA block
+    // Fixed order/count: every register in the DMA AXI map (includes write_data).
+    reg_model.axi_dma_reg_rm.axi_dma_reg_AXI_map.get_registers(soc_regs);
+
+    // Run the uC WR_FIFO transfer while the SoC-AXI side continuously writes every
+    // DMA register in parallel until the transfer completes. All SoC writes are
+    // rejected and must not disturb the transfer.
+    xfer_done = 1'b0;
+    fork
+      begin : UC_WR_FIFO_XFER
+        dma_transfer_and_verify(item, err);
+        if (err)
+          `uvm_error("DMA_WRFIFO_DIR", "uC WR_FIFO transfer through write_data reported a DMA error")
+        xfer_done = 1'b1; // signal the SoC-AXI writer to stop
+      end
+      begin : SOC_AXI_WRITES
+        uvm_status_e sts;
+        int unsigned num_soc_writes = 0;
+        // Fixed data / order / AxUSER (no randomization); repeat the full register
+        // pass until the transfer is done so the SoC-AXI accesses span the whole
+        // active transfer.
+        while (!xfer_done) begin
+          foreach (soc_regs[i]) begin
+            if (xfer_done) break;
+            soc_regs[i].write(sts, SOC_WDATA, UVM_FRONTDOOR, reg_model.soc_ifc_AXI_map, this, .extension(axi_user_obj));
+            num_soc_writes++;
+          end
+        end
+        `uvm_info("DMA_WRFIFO_DIR", $sformatf("Issued %0d fixed SoC-AXI writes to DMA registers during the transfer (all expected rejected: SLVERR)", num_soc_writes), UVM_LOW)
+      end
+    join
+
+    `uvm_info("DMA_WRFIFO_DIR", "Completed directed WR_FIFO / write_data test", UVM_LOW)
+  endtask
+
+endclass
diff --git a/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_xfer_stress_sequence.svh b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_xfer_stress_sequence.svh
new file mode 100644
index 00000000..4f7db190
--- /dev/null
+++ b/src/soc_ifc/uvmf_soc_ifc/uvmf_template_output/verification_ip/environment_packages/soc_ifc_env_pkg/sequences/dma/soc_ifc_env_dma_xfer_stress_sequence.svh
@@ -0,0 +1,62 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//----------------------------------------------------------------------
+// DESCRIPTION: DMA transfer stress scenario.
+//
+// Runs 50 constrained-random DMA transfers (configured
+// by the microcontroller over AHB) while concurrently running the reusable
+// soc_ifc_env_dma_reg_soc_access_sequence against the DMA registers from SoC-AXI.
+// Proves both that every transfer moves its data correctly and that every
+// SoC-AXI DMA access is rejected while the DMA is in flight.
+//
+// Thin by design: the DMA transaction API lives in soc_ifc_env_dma_sequence_base
+// and the SoC-AXI access sequence is its own reusable sequence.
+//----------------------------------------------------------------------
+
+class soc_ifc_env_dma_xfer_stress_sequence extends soc_ifc_env_dma_sequence_base;
+
+  `uvm_object_utils( soc_ifc_env_dma_xfer_stress_sequence )
+
+  function new(string name = "" );
+    super.new(name);
+  endfunction
+
+  virtual task body();
+    soc_ifc_env_dma_reg_soc_access_sequence soc_seq;
+    bit err;
+    int unsigned num_transfers = 50; 
+
+    if (reg_model == null)
+      reg_model = configuration.soc_ifc_rm;
+
+    dma_read_cap(); // FIFO max depth, needed by the AHB_FIFO routes
+
+    `uvm_info("DMA_XFER_SEQ", $sformatf("Starting %0d DMA transfers with concurrent SoC-AXI register accesses (fifo_max_depth=%0d)", num_transfers, fifo_max_depth), UVM_LOW)
+
+    soc_seq = soc_ifc_env_dma_reg_soc_access_sequence::type_id::create("soc_seq");
+
+    fork
+      soc_seq.start(get_sequencer(), this);
+      begin
+        for (int i = 0; i < num_transfers; i++)
+          dma_transfer_rand(2048, err);
+        soc_seq.stop();
+      end
+    join
+
+    `uvm_info("DMA_XFER_SEQ", "Completed all DMA transfers; SoC-AXI DMA accesses were rejected throughout.", UVM_LOW)
+  endtask
+
+endclass
