+    logic ``__name``_glitch_inject;                   \
+    assign ``__name``_glitch_inject = '0;             \
+    __type ``__name``_d;                              \
+    assign ``__name``_d = __type'($bits(__type)'(__d) ^ {``__name``_glitch_inject, {($bits(__type)-1){1'b0}}}); \
