diff --git a/src/keyvault/coverage/keyvault_cov_if.sv b/src/keyvault/coverage/keyvault_cov_if.sv
index a284993f..b9b1f2ca 100644
--- a/src/keyvault/coverage/keyvault_cov_if.sv
+++ b/src/keyvault/coverage/keyvault_cov_if.sv
@@ -63,6 +63,32 @@ interface keyvault_cov_if
     assign ahb_write = kv.kv_ahb_slv1.dv & kv.kv_ahb_slv1.write;
     assign ahb_read  = kv.kv_ahb_slv1.dv & ~kv.kv_ahb_slv1.write;

+    // Multi-write error: >1 crypto write client active simultaneously
+    logic kv_multi_write_err;
+    assign kv_multi_write_err = kv.kv_multi_write_err;
+
+    logic prev_multi_write_err;
+    always_ff @(posedge clk or negedge rst_b) begin
+        if (!rst_b)
+            prev_multi_write_err <= '0;
+        else
+            prev_multi_write_err <= kv_multi_write_err;
+    end
+
+    logic multi_write_event;
+    assign multi_write_event = kv_multi_write_err & ~prev_multi_write_err;
+
+    covergroup cg_multi_write @(posedge clk iff multi_write_event);
+        option.per_instance = 1;
+        option.name = "cg_multi_write";
+
+        cp_multi_write: coverpoint kv_multi_write_err {
+            bins detected = {1'b1};
+        }
+    endgroup
+
+    cg_multi_write cg_multi_write_inst = new();
+
     covergroup keyvault_top_cov_grp @(posedge clk);
         option.per_instance = 1;
         debug: coverpoint cptra_in_debug_scan_mode; //debugUnlock_or_scan_mode_switch;
diff --git a/src/keyvault/coverage/kv_boot_flow_cov.sv b/src/keyvault/coverage/kv_boot_flow_cov.sv
index 859e6ec7..a752bcec 100644
--- a/src/keyvault/coverage/kv_boot_flow_cov.sv
+++ b/src/keyvault/coverage/kv_boot_flow_cov.sv
@@ -13,7 +13,14 @@
 // limitations under the License.
 //
 // Covergroups for KV Boot Flow Transition Enforcement
-// Covers: enforcement actions, monitor checks, error escalation, write counters
+// Covers: enforcement results, monitor checks, flush sources, write counter
+//         thresholds, and multi-write arbitration errors
+//
+// Architecture notes (from kv.sv):
+//   - KV Monitor checks dest_valid and write counters ONLY on enter_fmc/enter_rt
+//   - KV Enforcement sets lock_wr/lock_use and clears non-preserved slots on transitions
+//   - Multi-write detection (kv_write_cnt > 1) is bus arbitration, not boot-flow
+//   - Write counters track ROM-phase crypto writes to DICE slots 6/7/8; checked at enter_fmc

 `ifndef VERILATOR

@@ -42,9 +49,6 @@ module kv_boot_flow_cov
     input logic [2:0] write_count_fmc_ecdsa,
     input logic [2:0] write_count_fmc_mldsa,

-    // Multi-write error
-    input logic kv_multi_write_err,
-
     // Crypto write strobes (for counter sampling)
     input logic crypto_wr_fmc_cdi,
     input logic crypto_wr_fmc_ecdsa,
@@ -52,77 +56,110 @@ module kv_boot_flow_cov
 );

     // =========================================================================
-    // Intermediate signals — sample slot state at transition edges
+    // Shared types
+    // =========================================================================
+    typedef enum logic [1:0] {TRANS_FMC = 0, TRANS_RT = 1} transition_t;
+
+    transition_t sampled_transition;
+    assign sampled_transition = enter_fmc ? TRANS_FMC : TRANS_RT;
+
+    // =========================================================================
+    // Delayed transition edges -- enforcement results (lock_wr, lock_use,
+    // dest_valid clear) are registered, so sample one cycle after the edge
+    // to observe the post-enforcement state.
     // =========================================================================
-    logic [KV_NUM_KEYS-1:0] lock_wr_at_sample;
-    logic [KV_NUM_KEYS-1:0] lock_use_at_sample;
+    logic enter_fmc_d, enter_rt_d;
+    always_ff @(posedge clk or negedge rst_b) begin
+        if (!rst_b) begin
