       write_block(block1);

+      write_single_word(`HMAC_REG_HMAC512_CTRL, mode | CTRL_NEXT_VALUE | CTRL_LAST_VALUE);
+      #CLK_PERIOD;
+      hsel_i_tb       = 0;
