-//
-//======================================================================
-//
-// sha512_ctrl_32bit_tb.sv
-// --------
-// SHA512 testbench for the SHA512 AHb_lite interface controller.
-//
-//
-//======================================================================
-
-`include "caliptra_reg_defines.svh"
-`include "caliptra_reg_field_defines.svh"
-
-module sha512_ctrl_32bit_tb 
-  import kv_defines_pkg::*;
-  import pv_defines_pkg::*;
-  ();
-
-//----------------------------------------------------------------
-  // Internal constant and parameter definitions.
-  //----------------------------------------------------------------
-  parameter DEBUG = 0;
-
-  parameter CLK_HALF_PERIOD = 1;
-  parameter CLK_PERIOD      = 2 * CLK_HALF_PERIOD;
-
-  parameter MODE_SHA_512_224     = 2'h0;
-  parameter MODE_SHA_512_256     = 2'h1;
-  parameter MODE_SHA_384         = 2'h2;
-  parameter MODE_SHA_512         = 2'h3;
-
-  parameter INIT_CMD             = (1 << `SHA512_REG_SHA512_CTRL_INIT_LOW) & (`SHA512_REG_SHA512_CTRL_INIT_MASK);
-  parameter NEXT_CMD             = (1 << `SHA512_REG_SHA512_CTRL_NEXT_LOW) & (`SHA512_REG_SHA512_CTRL_NEXT_MASK);
-  parameter RESTORE_CMD          = (1 << `SHA512_REG_SHA512_CTRL_RESTORE_LOW) & (`SHA512_REG_SHA512_CTRL_RESTORE_MASK);
-  parameter ZEROIZE_CMD          = (1 << `SHA512_REG_SHA512_CTRL_ZEROIZE_LOW) & (`SHA512_REG_SHA512_CTRL_ZEROIZE_MASK);
-
-  parameter AHB_HTRANS_IDLE      = 0;
-  parameter AHB_HTRANS_BUSY      = 1;
-  parameter AHB_HTRANS_NONSEQ    = 2;
-  parameter AHB_HTRANS_SEQ       = 3;
-
-  parameter AHB_ADDR_WIDTH       = 32;
-  parameter AHB_DATA_WIDTH       = 32;
-
-  //----------------------------------------------------------------
-  // Register and Wire declarations.
-  //----------------------------------------------------------------
-  reg [31 : 0]  cycle_ctr;
-  reg [31 : 0]  error_ctr;
-  reg [31 : 0]  tc_ctr;
-
-  reg           clk_tb;
-  reg           reset_n_tb;
-  reg           cptra_pwrgood_tb;
-
-  reg [AHB_ADDR_WIDTH-1:0]  haddr_i_tb;
-  reg [AHB_DATA_WIDTH-1:0]  hwdata_i_tb;
-  reg           hsel_i_tb;
-  reg           hwrite_i_tb; 
-  reg           hready_i_tb;
-  reg [1:0]     htrans_i_tb;
-  reg [2:0]     hsize_i_tb;
-
-  wire          hresp_o_tb;
-  wire          hreadyout_o_tb;
-  wire [AHB_DATA_WIDTH-1:0] hrdata_o_tb;
-
-  pv_read_t pv_read_tb;
-  pv_write_t pv_write_tb;
-  pv_rd_resp_t pv_rd_resp_tb;
-  pv_wr_resp_t pv_wr_resp_tb;
-  logic [KV_NUM_DWORDS-1:0][31:0] pcr_signing_hash_tb;
-
-  wire error_intr_tb;
-  wire notif_intr_tb;
-
-  reg [31 : 0]  read_data;
-  reg [511 : 0] digest_data;
-
-  //bind coverage file
-  sha512_ctrl_cov_bind i_sha512_ctrl_cov_bind();
-
-  //----------------------------------------------------------------
-  // Device Under Test.
-  //----------------------------------------------------------------
-  sha512_ctrl #(
-             .AHB_DATA_WIDTH(32),
-             .AHB_ADDR_WIDTH(32)
-            )
-            dut (
-             .clk(clk_tb),
-             .reset_n(reset_n_tb),
-             .cptra_pwrgood(cptra_pwrgood_tb),
-
-             .haddr_i(haddr_i_tb),
-             .hwdata_i(hwdata_i_tb),
-             .hsel_i(hsel_i_tb),
-             .hwrite_i(hwrite_i_tb),
-             .hready_i(hready_i_tb),
-             .htrans_i(htrans_i_tb),
-             .hsize_i(hsize_i_tb),
-
-             .hresp_o(hresp_o_tb),
-             .hreadyout_o(hreadyout_o_tb),
-             .hrdata_o(hrdata_o_tb),
-
-             .pcr_signing_hash(pcr_signing_hash_tb),
-             .pv_read(pv_read_tb),
-             .pv_rd_resp(pv_rd_resp_tb),
-             .pv_write(pv_write_tb),
-             .pv_wr_resp(pv_wr_resp_tb),
-
-             .error_intr(error_intr_tb),
-             .notif_intr(notif_intr_tb),
-             .debugUnlock_or_scan_mode_switch('0)
-            );
-
-  //----------------------------------------------------------------
-  // clk_gen
-  //
-  // Clock generator process.
-  //----------------------------------------------------------------
-  always
-    begin : clk_gen
-      #CLK_HALF_PERIOD clk_tb = !clk_tb;
-    end // clk_gen
-
-  //----------------------------------------------------------------
-  // sys_monitor
-  //
-  // Generates a cycle counter and displays information about
-  // the dut as needed.
-  //----------------------------------------------------------------
-  always
-    begin : sys_monitor
-      #(CLK_PERIOD);
-      cycle_ctr = cycle_ctr + 1;
-    end
-
-  //----------------------------------------------------------------
-  // reset_dut()
-  //
-  // Toggles reset to force the DUT into a well defined state.
-  //----------------------------------------------------------------
-  task reset_dut;
-    begin
-      $display("*** Toggle reset.");
-      reset_n_tb = 0;
-      cptra_pwrgood_tb = 0;
-
-      #(4 * CLK_HALF_PERIOD);
-
-      reset_n_tb = 1;
-      cptra_pwrgood_tb = 1;
-    end
-  endtask // reset_dut
-
-
-  //----------------------------------------------------------------
-  // init_sim()
-  //
-  // Initialize all counters and testbed functionality as well
-  // as setting the DUT inputs to defined values.
-  //----------------------------------------------------------------
-  task init_sim;
-    begin
-      cycle_ctr = 32'h00000000;
-      error_ctr = 32'h00000000;
-      tc_ctr    = 32'h00000000;
-
-      clk_tb        = 0;
-      reset_n_tb    = 0;
-      cptra_pwrgood_tb = 0;
-
-      haddr_i_tb      = 0;
-      hwdata_i_tb     = 0;
-      hsel_i_tb       = 0;
-      hwrite_i_tb     = 0;
-      hready_i_tb     = 0;
-      htrans_i_tb     = AHB_HTRANS_IDLE;
-      hsize_i_tb      = 3'b011;
-
-      pv_wr_resp_tb   = '0;
-      pv_rd_resp_tb   = '0;
-    end
-  endtask // init_dut
-
-  //----------------------------------------------------------------
-  // display_test_result()
-  //
-  // Display the accumulated test results.
-  //----------------------------------------------------------------
-  task display_test_result;
-    begin
-      if (error_ctr == 0)
-        begin
-          $display("*** All %02d test cases completed successfully.", tc_ctr);
-          $display("* TESTCASE PASSED");
-        end
-      else
-        begin
-          $display("*** %02d test cases completed.", tc_ctr);
-          $display("*** %02d errors detected during testing.", error_ctr);
-          $display("* TESTCASE FAILED");
-        end
-    end
-  endtask // display_test_result
-
-  //----------------------------------------------------------------
-  // wait_ready()
-  //
-  // Wait for the ready flag in the dut to be set.
-  // (Actually we wait for either ready or valid to be set.)
-  //
-  // Note: It is the callers responsibility to call the function
-  // when the dut is actively processing and will in fact at some
-  // point set the flag.
-  //----------------------------------------------------------------
-  task wait_ready;
-    begin
-      read_data = 0;
-      #(CLK_PERIOD);
-
-      while (read_data == 0)
-        begin
-          read_single_word(`SHA512_REG_SHA512_STATUS);
-        end
-    end
-  endtask // wait_ready
-
-  //----------------------------------------------------------------
-  // read_word()
-  //
-  // Read a data word from the given address in the DUT.
-  // the word read will be available in the global variable
-  // read_data.
-  //----------------------------------------------------------------
-  task read_single_word(input [31 : 0]  address);
-    begin
-      hsel_i_tb       = 1;
-      haddr_i_tb      = address;
-      hwrite_i_tb     = 0;
-      hready_i_tb     = 1;
-      htrans_i_tb     = AHB_HTRANS_NONSEQ;
-      hsize_i_tb      = 3'b010;
-      #(CLK_PERIOD);
-      
-      hwdata_i_tb     = 0;
-      haddr_i_tb     = 'Z;
-      htrans_i_tb     = AHB_HTRANS_IDLE;
-
-      read_data = hrdata_o_tb;
-
-    end
-  endtask // read_word
-
-
-  //----------------------------------------------------------------
-  // write_single_word()
-  //
-  // Write the given word to the DUT using the DUT interface.
-  //----------------------------------------------------------------
-  task write_single_word(input [31 : 0]  address,
-                  input [31 : 0] word);
-    begin
-      hsel_i_tb       = 1;
-      haddr_i_tb      = address;
-      hwrite_i_tb     = 1;
-      hready_i_tb     = 1;
-      htrans_i_tb     = AHB_HTRANS_NONSEQ;
-      hsize_i_tb      = 3'b010;
-      #(CLK_PERIOD);
-
-      haddr_i_tb      = 'Z;
-      hwdata_i_tb     = word;
-      hwrite_i_tb     = 0;
-      htrans_i_tb     = AHB_HTRANS_IDLE;
-    end
-  endtask // write_single_word
-
-
-  //----------------------------------------------------------------
-  // write_block()
-  //
-  // Write the given block to the dut.
-  //----------------------------------------------------------------
