+                            force `CPTRA_TOP_PATH.key_vault1.kv_reg_hwif_in.KEY_CTRL[slot_id].last_dword.next = 'd7;
+                            force `CPTRA_TOP_PATH.key_vault1.kv_reg_hwif_in.KEY_ENTRY[slot_id][dword_i].data.we = 1'b1;
+                            force `CPTRA_TOP_PATH.key_vault1.kv_reg_hwif_in.KEY_ENTRY[slot_id][dword_i].data.next = mlkem_msg_tb[dword_i][31 : 0];
+                        end
+                    end
                     else if((WriteData[7:0] == 8'h9f) && mailbox_write) begin
                         inject_aes_seed <= 1'b1;
                         release_kv_inject_flags <= '0;

design_diff:
diff --git a/src/aes/rtl/aes_clp_wrapper.sv b/src/aes/rtl/aes_clp_wrapper.sv
index 96f7951f..b832fcfa 100644
--- a/src/aes/rtl/aes_clp_wrapper.sv
+++ b/src/aes/rtl/aes_clp_wrapper.sv
@@ -424,6 +424,7 @@ end
 //Read Key
 kv_read_client #(
   .DATA_WIDTH(keymgr_pkg::KeyWidth),
+  .AES(1),
   .PAD(0)
 )
 aes_key_kv_read
@@ -564,7 +565,9 @@ localparam int unsigned NumSeedChunks =
 logic [caliptra_prim_trivium_pkg::TriviumStateWidth-1:0] trivium_seed;
 logic [NumSeedChunks-1:0] trivium_seed_qe;
 logic [NumSeedChunks-1:0] trivium_seed_chunk_vld_q, trivium_seed_chunk_vld_d;
-logic trivium_seed_en;
+logic trivium_seed_en, trivium_seed_en_nq;
+// ECO: one-shot latch — block re-seeding after the first seed operation until reset
+logic trivium_seeded;

 // Concatenate the register values to produce the full state seed.
 assign trivium_seed = {hwif_out.ENTROPY_IF_SEED[8].ENTROPY_IF_SEED.value,
@@ -591,8 +594,9 @@ assign trivium_seed_qe = {hwif_out.ENTROPY_IF_SEED[8].ENTROPY_IF_SEED.swmod,
 // Track write operations:
 // - Perform the reseed once every register has been written at least once.
 // - Clear the tracking upon doing the reseed operation.
-assign trivium_seed_chunk_vld_d = trivium_seed_en ? '0 : trivium_seed_chunk_vld_q | trivium_seed_qe;
-assign trivium_seed_en = &trivium_seed_chunk_vld_q;
+assign trivium_seed_chunk_vld_d = trivium_seed_en_nq ? '0 : trivium_seed_chunk_vld_q | trivium_seed_qe;
+assign trivium_seed_en_nq = &trivium_seed_chunk_vld_q;
+assign trivium_seed_en = trivium_seed_en_nq & ~trivium_seeded;

 always_ff @(posedge clk or negedge reset_n) begin
   if (~reset_n) begin
@@ -602,6 +606,16 @@ always_ff @(posedge clk or negedge reset_n) begin
   end
 end

+always_ff @(posedge clk or negedge reset_n) begin
+  if (~reset_n) begin
+    trivium_seeded <= 1'b0;
+  end else if (trivium_seed_en) begin  
+    trivium_seeded <= 1'b1;
+  end else begin
+    trivium_seeded <= trivium_seeded;
+  end
+end
+
 caliptra_prim_trivium #(
   .OutputWidth(edn_pkg::ENDPOINT_BUS_WIDTH),
   .SeedType   (caliptra_prim_trivium_pkg::SeedTypeStateFull)
@@ -626,6 +640,11 @@ u_caliptra_prim_trivium
     .err_o()
 );

+// What: After the first Trivium reseed, seed_en must stay low until reset
+// Why: Prevent firmware from re-seeding the PRNG after initial entropy injection
+// Timing: Combinational — trivium_seeded_q is set 1 cycle after first seed_en
+`CALIPTRA_ASSERT(ERR_AES_TRIVIUM_SEEDED_TWICE, trivium_seeded |-> !trivium_seed_en, clk, !reset_n)
+
 `CALIPTRA_ASSERT_STABLE(ERR_AES_KEY_RD_CTRL_NOT_STABLE, kv_key_read_ctrl_reg, clk, (!reset_n || status_idle_o) )
 `CALIPTRA_ASSERT_STABLE(ERR_AES_WR_CTRL_NOT_STABLE, kv_write_ctrl_reg, clk, (!reset_n || status_idle_o) )
 `CALIPTRA_ASSERT_STABLE(ERR_AES_KEY_NOT_STABLE, kv_key_reg, clk, (!reset_n || status_idle_o) )
diff --git a/src/keyvault/rtl/kv_read_client.sv b/src/keyvault/rtl/kv_read_client.sv
index 84ad0ad7..55128c51 100644
--- a/src/keyvault/rtl/kv_read_client.sv
+++ b/src/keyvault/rtl/kv_read_client.sv
@@ -20,6 +20,7 @@ module kv_read_client
     #(
     parameter DATA_WIDTH = 512
    ,parameter HMAC = 0
+   ,parameter AES = 0
    ,parameter PAD = 0

    ,localparam DATA_OFFSET_W = $clog2(DATA_WIDTH/32)
@@ -116,13 +117,21 @@ always_ff @(posedge clk or negedge rst_b) begin
         // On subsequent beats of kv read, preserve any error that was previously
         // flagged or decode new error conditions
         error_code <= validated_read_en && ~read_allow ? KV_READ_FAIL :
-                      read_allow && |write_offset && (error_code != KV_SUCCESS) ? error_code :
-                      read_allow && kv_resp.error ? KV_READ_FAIL : 
-                      read_allow && ~kv_resp.error ? KV_SUCCESS : error_code;
+                      write_en && |write_offset && (error_code != KV_SUCCESS) ? error_code :
+                      write_en && kv_resp.error ? KV_READ_FAIL : 
+                      write_en && ~kv_resp.error ? KV_SUCCESS : error_code;
     end
 end

-always_comb kv_ready = kv_fsm_ready & (error_code == KV_SUCCESS) & ~validated_read_en;
+//for AES kv ready can't be held for errors since AES does not have zeroize support
+//AES already handles the key material in case of errors
+generate
+    if (AES) begin : aes_kv_ready_gen
+        always_comb kv_ready = kv_fsm_ready & ~validated_read_en;
+    end else begin :non_aes_kv_ready_gen
+        always_comb kv_ready = kv_fsm_ready & (error_code == KV_SUCCESS) & ~validated_read_en;
+    end
+endgenerate

 `CALIPTRA_ASSERT_KNOWN(READ_METRICS_X,  read_metrics, clk, !rst_b)

