+//======================================================================
+//
+// hmac_core.v
+// --------
+// working on HMAC-384 configuration
+//
+//
+//======================================================================
+
+module hmac_core
+(
+      // Clock and reset.
+      input logic            clk,
+      input logic            reset_n,
+      input logic            zeroize,
+      
+      // Control.
+      input logic            init_cmd,
+      input logic            next_cmd,
+      input logic            mode_cmd,
