diff --git a/src/aes/rtl/aes_clp_wrapper.sv b/src/aes/rtl/aes_clp_wrapper.sv
index 1b52c968..d1738841 100644
--- a/src/aes/rtl/aes_clp_wrapper.sv
+++ b/src/aes/rtl/aes_clp_wrapper.sv
@@ -22,6 +22,9 @@
 // 
 //======================================================================

+`include "caliptra_reg_field_defines.svh"
+`include "kv_macros.svh"
+
 module aes_clp_wrapper
   import aes_pkg::*;
   import kv_defines_pkg::*;
@@ -143,7 +146,7 @@ keymgr_pkg::hw_key_req_t keymgr_key;
 assign error_intr = '0; // Unused
 assign notif_intr = '0;  // Unused 

-assign busy_o = caliptra_prim_mubi_pkg::mubi4_test_false_loose(aes_idle);
+assign busy_o = caliptra_prim_mubi_pkg::mubi4_test_false_loose(aes_idle) & ~kv_key_ready & ~kv_write_ready;
 assign status_idle_o = caliptra_prim_mubi_pkg::mubi4_test_true_loose(aes_idle);


@@ -509,13 +512,19 @@ genvar g_dword;
 genvar g_byte;
 generate
   for (g_dword = 0; g_dword < keymgr_pkg::KeyWidth/32; g_dword++) begin
+    logic [$bits(kv_key_write_offset)-1:0] local_g_dword;
+    assign local_g_dword = 3'(g_dword);
     for (g_byte = 0; g_byte < 4; g_byte++) begin
       always_ff @(posedge clk or negedge reset_n) begin
         if (~reset_n) begin
           kv_key_reg[g_dword][g_byte] <= '0;
         end else if(debugUnlock_or_scan_mode_switch) begin
           kv_key_reg[g_dword][g_byte] <= '0;
-        end else if (kv_key_write_en && (kv_key_write_offset == g_dword)) begin
+        // zeroize the buffered KeyVault value when reading in a new key
+        // On the first beat, the least-sig dword is set, all other dwords set to 0
+        end else if (kv_key_write_en && |local_g_dword && (kv_key_write_offset <  local_g_dword)) begin
+          kv_key_reg[g_dword][g_byte] <= 0;
+        end else if (kv_key_write_en && (kv_key_write_offset == local_g_dword)) begin
           kv_key_reg[g_dword][g_byte] <= kv_key_write_data[3-g_byte];
         end
       end
diff --git a/src/keyvault/rtl/kv_read_client.sv b/src/keyvault/rtl/kv_read_client.sv
index 2828a22b..5e9f81a0 100644
--- a/src/keyvault/rtl/kv_read_client.sv
+++ b/src/keyvault/rtl/kv_read_client.sv
@@ -110,7 +110,11 @@ always_ff @(posedge clk or negedge rst_b) begin
         error_code <= KV_SUCCESS;
     end
     else begin
-        error_code <= validated_read_en & ~read_allow ? KV_READ_FAIL :
+        // On first beat of kv read, latch any error conditions.
+        // On subsequent beats of kv read, preserve any error that was previously
+        // flagged or decode new error conditions
+        error_code <= validated_read_en && |write_offset && (error_code != KV_SUCCESS) ? error_code :
+                      validated_read_en & ~read_allow ? KV_READ_FAIL :
                       validated_read_en & kv_resp.error ? KV_READ_FAIL : 
                       validated_read_en & ~kv_resp.error ? KV_SUCCESS : error_code;
     end
diff --git a/src/keyvault/rtl/kv_write_client.sv b/src/keyvault/rtl/kv_write_client.sv
index bdcc5941..13377c1d 100644
--- a/src/keyvault/rtl/kv_write_client.sv
+++ b/src/keyvault/rtl/kv_write_client.sv
@@ -112,7 +112,11 @@ always_ff @(posedge clk or negedge rst_b) begin
         error_code <= KV_SUCCESS;
     end
     else begin
-        error_code <= dest_data_avail & write_ctrl_reg.write_en & !write_allow ? KV_WRITE_FAIL :
+        // On first beat of kv write, latch any error conditions.
+        // On subsequent beats of kv write, preserve any error that was previously
+        // flagged or decode new error conditions
+        error_code <= dest_write_en && |dest_write_offset && (error_code != KV_SUCCESS) ? error_code : 
+                      dest_data_avail & write_ctrl_reg.write_en & !write_allow ? KV_WRITE_FAIL :
                       dest_write_en & kv_resp.error ? KV_WRITE_FAIL : 
                       dest_write_en & ~kv_resp.error ? KV_SUCCESS : error_code;
     end
