+
   initial begin
     if ($value$plusargs("HMAC_DRBG_TEST=%s", hmac_drbg_test_to_run)) begin
       $display("%m: Running hmac_drbg test = %s", hmac_drbg_test_to_run);
@@ -246,6 +248,8 @@ module hmac_drbg_tb();
       lfsr_seed_tb      = 384'h0;
