diff --git a/src/integration/rtl/caliptra_reg_field_defines.svh b/src/integration/rtl/caliptra_reg_field_defines.svh
index 12cc46f3..d097c4de 100644
--- a/src/integration/rtl/caliptra_reg_field_defines.svh
+++ b/src/integration/rtl/caliptra_reg_field_defines.svh
@@ -1343,6 +1343,33 @@
 `ifndef AES_CLP_REG_AES_VERSION_1
 `define AES_CLP_REG_AES_VERSION_1                                                                   (32'hc)
 `endif
+`ifndef AES_CLP_REG_ENTROPY_IF_SEED_0
+`define AES_CLP_REG_ENTROPY_IF_SEED_0                                                               (32'h110)
+`endif
+`ifndef AES_CLP_REG_ENTROPY_IF_SEED_1
+`define AES_CLP_REG_ENTROPY_IF_SEED_1                                                               (32'h114)
