+
+// Declarations for internal signal probing  
+logic [31:0] fuse_uds_seed [0:11]; 
+logic [31:0] fuse_field_entropy [0:7]; 
+logic [31:0] fuse_vendor_pk_hash [0:11]; 
+logic [3:0]  fuse_ecc_revocation; 
