diff --git a/src/aes/rtl/aes_cipher_control_fsm.sv b/src/aes/rtl/aes_cipher_control_fsm.sv
index 25ec2d83..6de2acbe 100644
--- a/src/aes/rtl/aes_cipher_control_fsm.sv
+++ b/src/aes/rtl/aes_cipher_control_fsm.sv
@@ -1,4 +1,4 @@
-// Copyright lowRISC contributors.
+// Copyright lowRISC contributors (OpenTitan project).
 // Licensed under the Apache License, Version 2.0, see LICENSE for details.
 // SPDX-License-Identifier: Apache-2.0
 //
@@ -8,9 +8,7 @@

 `include "caliptra_prim_assert.sv"

-module aes_cipher_control_fsm 
