diff --git a/src/sha256/rtl/sha256.sv b/src/sha256/rtl/sha256.sv
index 6ff98534..bacea469 100644
--- a/src/sha256/rtl/sha256.sv
+++ b/src/sha256/rtl/sha256.sv
@@ -100,7 +100,7 @@ module sha256
