+  function automatic reg [63:0] ROT14 (input reg [63:0] x);
     return {x[18 : 0], x[63 : 19]} ^ // ROTR19
            {x[60 : 0], x[63 : 61]} ^ // ROTR61
            {6'b000000, x[63 : 6]};   // SHR6          
   endfunction

-  function masked_reg_t masked_sum (input masked_reg_t x, y);
