+        //kv_rst_agent_poweron_seq_2 = kv_rst_agent_poweron_sequence_t::type_id::create("kv_rst_agent_poweron_seq_2");
+    endfunction
+
+    virtual task body();
+    
+        kv_rst_agent_scan_on_seq.start(configuration.kv_rst_agent_config.sequencer);
+                        
+    endtask
+endclass
\ No newline at end of file
