+    endtask
+  
+  
+    //==========================================
+    // Name:        body
+    // Description: Run the main functionality
+    //==========================================
+    virtual task body();
+
+  
+      // Run ctrl seq
+      run_ctrl_seq();
+  
+      
+  
+    endtask
+  
+  endclass
