+
+  task _read_special_register(access_t modifier, string regname, int tid);
+
+    begin
+      case (regname)
+        "INTERNAL_RV_MTIME_L": read_reg_chk_inrange(modifier, regname, tid, cycle_ctr_since_pwrgood - 'd1 , cycle_ctr_since_pwrgood + 'd20); 
