+                    input [383 : 0] expected
+                  );
+    begin
+
+      $display("*** TC%01d - zeroize test started.", tc_ctr);
+
+      // First test: assert zeroize when engine is working
+      write_key(key);
+      
+      write_block(block0);
+
+      write_seed(seed);
+
