diff --git a/src/sha512/coverage/sha512_ctrl_cov_if.sv b/src/sha512/coverage/sha512_ctrl_cov_if.sv
new file mode 100644
index 00000000..9484d560
--- /dev/null
+++ b/src/sha512/coverage/sha512_ctrl_cov_if.sv
@@ -0,0 +1,88 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+`ifndef VERILATOR
+
+interface sha512_ctrl_cov_if     
+    (
+    input logic           clk,
+    input logic           reset_n,
+    input logic           cptra_pwrgood
+
+);
+
+    logic init;
+    logic next;
+    logic [1 : 0] mode;
+    logic zeroize;
+    logic ready;
+    logic valid;
+    
+    logic pcr_sign_we;
+    logic gen_hash_start;
+    logic gen_hash_ip;
+    logic dest_data_avail;
+
+    logic [1 : 0] hash_cmd;
+    
+    assign init = sha512_ctrl.sha512_inst.init_reg;
+    assign next = sha512_ctrl.sha512_inst.next_reg;
+    assign mode = sha512_ctrl.sha512_inst.mode_reg;
+    assign zeroize = sha512_ctrl.sha512_inst.zeroize_reg;
+    assign ready = sha512_ctrl.sha512_inst.ready_reg;
+    assign valid = sha512_ctrl.sha512_inst.digest_valid_reg;
+
+    assign pcr_sign_we = sha512_ctrl.sha512_inst.pcr_sign_we;
+    assign gen_hash_start = sha512_ctrl.sha512_inst.gen_hash_start;
+    assign gen_hash_ip = sha512_ctrl.sha512_inst.gen_hash_ip;
+    assign dest_data_avail = sha512_ctrl.sha512_inst.dest_data_avail;
+
+    assign hash_cmd = {next, init};
+
+    covergroup sha512_ctrl_cov_grp @(posedge clk);
+        reset_cp: coverpoint reset_n;
+        cptra_pwrgood_cp: coverpoint cptra_pwrgood;
+
+        init_cp: coverpoint init;
+        next_cp: coverpoint next;
+        mode_cp: coverpoint mode;
+        zeroize_cp: coverpoint zeroize;
+        ready_cp: coverpoint ready;
+        valid_cp: coverpoint valid;
+
+        pcr_sign_we_cp: coverpoint pcr_sign_we;
+        gen_hash_start_cp: coverpoint gen_hash_start;
+        gen_hash_ip_cp: coverpoint gen_hash_ip;
+        dest_data_avail_cp: coverpoint dest_data_avail;
+
+        hash_cmd_cp: coverpoint hash_cmd  {bins cmd[]   = (0, 0 => 1, 2 => 0, 0);}
+
+        init_ready_cp: cross ready, init;
+        next_ready_cp: cross ready, next;
+        zeroize_ready_cp: cross ready, zeroize;
+        mode_ready_cp: cross ready, mode;
+        pcr_ready_cp: cross ready, gen_hash_start;
+        pcr_init_cp: cross gen_hash_start, init;
+        pcr_next_cp: cross gen_hash_start, next;
+        zeroize_pcr_cp: cross zeroize, gen_hash_start;
+        zeroize_init_cp: cross zeroize, init;
+        zeroize_next_cp: cross zeroize, next;
+
+    endgroup
+
+    sha512_ctrl_cov_grp sha512_ctrl_cov_grp1 = new();
+
+endinterface
+
+`endif
\ No newline at end of file
diff --git a/src/sha512/tb/sha512_ctrl_32bit_tb.sv b/src/sha512/tb/sha512_ctrl_32bit_tb.sv
index cc212f03..5c743ac6 100644
--- a/src/sha512/tb/sha512_ctrl_32bit_tb.sv
+++ b/src/sha512/tb/sha512_ctrl_32bit_tb.sv
@@ -160,6 +160,9 @@ module sha512_ctrl_32bit_tb
   reg [31 : 0]  read_data;
   reg [511 : 0] digest_data;

+  //bind coverage file
+  sha512_ctrl_cov_bind i_sha512_ctrl_cov_bind();
+
   //----------------------------------------------------------------
   // Device Under Test.
   //----------------------------------------------------------------
@@ -564,6 +567,8 @@ module sha512_ctrl_32bit_tb
       end_time = cycle_ctr - start_time;
       $display("*** Single block test processing time = %01d cycles", end_time);

+      write_single_word(ADDR_CTRL, {28'h0, 1'b1, 4'b0}); //zeroize
+
       mask = get_mask(mode);
       masked_data = digest_data & mask;

@@ -651,7 +656,8 @@ module sha512_ctrl_32bit_tb
       $display("*** Double block test processing time = %01d cycles", end_time);
       read_digest();

-      
+      write_single_word(ADDR_CTRL, {28'h0, 1'b1, 4'b0}); //zeroize
+
       masked_data1 = digest_data & mask;

       if (masked_data1 == expected1)
@@ -736,6 +742,88 @@ module sha512_ctrl_32bit_tb
   endtask // double_block_test


+  //----------------------------------------------------------------
+  // continuous_cmd_test()
+  //
+  //
+  // Perform test of a double block digest.
+  //----------------------------------------------------------------
+  task continuous_cmd_test(input [7 : 0]    tc_number,
+                         input [1 : 0]    mode,
+                         input [1023 : 0] block0,
+                         input [1023 : 0] block1,
+                         input [511 : 0]  expected
+                        );
+    reg [511 : 0] mask;
+    reg [511 : 0] masked_data;
+    reg [31 : 0] start_time;
+    reg [31 : 0] end_time;
+
+    begin
+      $display("*** TC%01d - continuous command test started.", tc_ctr);
+
+      // First block
+      write_block(block0);
+      write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_INIT_VALUE});
+      start_time = cycle_ctr;
+      #CLK_PERIOD;
+      hsel_i_tb       = 0;
+
+      #(CLK_PERIOD);
+
+      for (int i=0; i<10; i++)
+        begin
+          write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_INIT_VALUE});
+          #CLK_PERIOD;
+          write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_NEXT_VALUE});
+          #CLK_PERIOD;
+        end
+
+      wait_ready();
+
+      write_block(block1);
+
+      // Final block
+      write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_NEXT_VALUE});
+      #CLK_PERIOD;
+      hsel_i_tb       = 0;
+
+      #(CLK_PERIOD);
+
+      for (int i=0; i<10; i++)
+        begin
+          write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_INIT_VALUE});
+          #CLK_PERIOD;
+          write_single_word(ADDR_CTRL, {28'h0, mode, CTRL_NEXT_VALUE});
+          #CLK_PERIOD;
+        end
+
+      wait_ready();
+
+      end_time = cycle_ctr - start_time;
+      $display("*** Continuous command test processing time = %01d cycles", end_time);
+      read_digest();
+
+      mask = get_mask(mode);
+      masked_data = digest_data & mask;
+
+      if (masked_data == expected)
+        begin
+          $display("TC%01d final block: OK.", tc_ctr);
+        end
+      else
+        begin
+          $display("TC%01d: ERROR in final digest", tc_ctr);
+          $display("TC%01d: Expected: 0x%0128x", tc_ctr, expected);
+          $display("TC%01d: Got:      0x%0128x", tc_ctr, masked_data);
+          error_ctr = error_ctr + 1;
+        end
+
+      $display("*** TC%01d - Continuous command test done.", tc_ctr);
+      tc_ctr = tc_ctr + 1;
+    end
+  endtask // continuous_cmd_test
+
   //----------------------------------------------------------------
   // sha512_test
   // The main test functionality.
@@ -815,6 +903,8 @@ module sha512_ctrl_32bit_tb

       double_block_test_pipelined(8'h09, MODE_SHA_512, double_block_one, double_block_two, tc6_expected);

+      continuous_cmd_test(8'h0a, MODE_SHA_384, double_block_one, double_block_two, tc12_expected);
+
       display_test_result();

       $display("   -- Testbench for sha512 done. --");

