-  prim_flop #(
+  caliptra_prim_flop #(
     .Width      ( 8  ),
     .ResetValue ( '0 )
-  ) u_prim_flop_prd1_q (
+  ) u_caliptra_prim_flop_prd1_q (
     .clk_i  ( clk_i  ),
     .rst_ni ( rst_ni ),
     .d_i    ( prd1_d ),
