@@ -163,21 +163,28 @@ always_comb arc_MBOX_EXECUTE_SOC_MBOX_EXECUTE_UC = (mbox_fsm_ps == MBOX_EXECUTE_
 //move back to IDLE and unlock when force unlock is set
