-always_comb mbox_dlen_in_dws_q = (mbox_dlen_in_dws > MBOX_SIZE_IN_DW) ? MBOX_SIZE_IN_DW : mbox_dlen_in_dws; 
-
- // Restrict mailbox dataout read once the DLEN in "DWORDS" is reached
