-            work_factor_ctr_reg <= work_factor_ctr_new;
-
           if (ready_we)
             ready_reg <= ready_new;

@@ -483,30 +469,6 @@ module sha512_core(
     end // round_ctr


-  //----------------------------------------------------------------
-  // work_factor_ctr
