 // ****************************************************************************
@@ -70,6 +75,7 @@ class caliptra_top_environment  extends uvmf_environment_base #(
     super.build_phase(phase);
     soc_ifc_subenv = soc_ifc_subenv_t::type_id::create("soc_ifc_subenv",this);
