+            `uvm_info("CPTRA_RESET_WAIT", "Caliptra core reset is still asserted, continuing to poll...", UVM_MEDIUM)
+        else
+            `uvm_info("CPTRA_RESET_WAIT", "Detected Caliptra core reset deassertion", UVM_LOW)
+    end


   endtask
