+    uvm_object obj;
+    super.new(name);
+    obj = soc_ifc_ctrl_reset_warm_sequence_t::get_type().create_object("soc_ifc_ctrl_reset_warm_seq");
+    if (!$cast(soc_ifc_ctrl_seq,obj))
+        `uvm_fatal("SOC_IFC_RST_WARM", "Failed to create warm reset sequence!")
+  endfunction
+
+endclass
