+                        wait_cycles_from_seq <= 100;
+                    };
+
+                    std::randomize(clear_secrets_data); //wren, debug_value0/1
+
+                    //Wait for random delay before starting debug txn
+                    configuration.kv_rst_agent_config.wait_for_num_clocks(wait_cycles_from_seq);
+
