@@ -0,0 +1,53 @@
+// Copyright lowRISC contributors.
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+//
+// Serial Peripheral Interface (SPI) Device module.
+//
+
+package spi_device_pkg;
+
+  typedef logic [7:0] spi_byte_t;
+
+  typedef enum spi_byte_t {
+    CmdNone = 8'h 00,
+
+    CmdWriteStatus1 = 8'h 01,
+    CmdWriteStatus2 = 8'h 31,
+    CmdWriteStatus3 = 8'h 11,
+
+    CmdReadStatus1 = 8'h 05,
+    CmdReadStatus2 = 8'h 35,
+    CmdReadStatus3 = 8'h 15,
+
+    CmdJedecId = 8'h 9F,
+
+    CmdPageProgram     = 8'h 02,
+    CmdQuadPageProgram = 8'h 32, // Not supported
+
+    CmdSectorErase  = 8'h 20, // 4kB erase
+    CmdBlockErase32 = 8'h 52, // 32kB
+    CmdBlockErase64 = 8'h D8, // 64kB
+
+    CmdReadData   = 8'h 03,
+    CmdReadFast   = 8'h 0B, // with Dummy
+    CmdReadDual   = 8'h 3B,
+    CmdReadQuad   = 8'h 6B,
+    CmdReadDualIO = 8'h BB,
+    CmdReadQuadIO = 8'h EB,
+
+    CmdWriteDisable = 8'h 04,
+    CmdWriteEnable  = 8'h 06,
+
+    CmdEn4B = 8'h B7,
+    CmdEx4B = 8'h E9,
+
+    CmdReadSfdp = 8'h 5A,
+
+    CmdChipErase = 8'h C7,
+
+    CmdEnableReset = 8'h 66,
+    CmdResetDevice = 8'h 99
+  } spi_cmd_e;
+
+endpackage : spi_device_pkg
diff --git a/src/spi_host/tb/spi_host_tb.sv b/src/spi_host/tb/spi_host_tb.sv
new file mode 100644
index 00000000..cc4b223d
--- /dev/null
+++ b/src/spi_host/tb/spi_host_tb.sv
@@ -0,0 +1,614 @@
+// SPDX-License-Identifier: Apache-2.0
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+// http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+//
+//======================================================================
+//
+// spi_host_tb.sv
+// --------
+// Integration test bench to ensure read/write through AHB is working
+// with spi_host ip.
+//
+//======================================================================
+
+module spi_host_tb
+  import spi_host_reg_pkg::*;
+  import spi_device_pkg::*;
+  import prim_mubi_pkg::mubi8_t;
+(
+`ifdef VERILATOR
+  input bit clk_tb
+`endif
+  );
+
+  //----------------------------------------------------------------
+  // Internal constant and parameter definitions.
+  //----------------------------------------------------------------
+  parameter DEBUG = 0;
+  parameter NUM_HOSTS = 2;
+
+  parameter CLK_HALF_PERIOD = 2;
+
+  parameter AHB_HTRANS_IDLE     = 0;
+  parameter AHB_HTRANS_BUSY     = 1;
+  parameter AHB_HTRANS_NONSEQ   = 2;
+  parameter AHB_HTRANS_SEQ      = 3;
+
+  parameter AHB_ADDR_WIDTH = 32;
+  parameter AHB_DATA_WIDTH = 32;
+
+  typedef struct packed {
+    logic       ready;     // spi host ready to receive command
+    logic       active;    // processing previously issued command
+    logic       txfull;    // tx fifo is full
+    logic       txempty;   // tx fifo is empty
+    logic       txstall;   // transaction has stalled due to lack of data in the tx fifo
+    logic       txwm;      // tx watermark
+    logic       rxfull;    // rx fifo is full
+    logic       rxempty;   // rx fifo is empty
+    logic       rxstall;   // ongoing transaction stalled due to lack of space in rx fifo
+    logic       byteorder; // value of ByteOrder parameter
+    logic       reserved;
+    logic       rxwm;      // rx watermark
+    logic [3:0] cmdqd;     // command queue depth
+    logic [7:0] rxqd;      // receive queue depth
+    logic [7:0] txqd;      // transmit queue depth
+  } spi_host_status_t;
+
+  //----------------------------------------------------------------
+  // Register and Wire declarations.
+  //----------------------------------------------------------------
+  reg [31 : 0] cycle_ctr;
+  reg [31 : 0] error_ctr;
+  reg [31 : 0] tc_ctr;
+  logic        generate_rng;
+
+
+`ifndef VERILATOR
+  reg           clk_tb;
+`endif
+  reg           reset_n_tb;
+
+  reg [AHB_ADDR_WIDTH-1:0]  haddr_i_tb;
+  reg [AHB_DATA_WIDTH-1:0]  hwdata_i_tb;
+  reg           hsel_i_tb;
+  reg           hwrite_i_tb;
+  reg           hready_i_tb;
+  reg [1:0]     htrans_i_tb;
+  reg [2:0]     hsize_i_tb;
+
+  wire          hresp_o_tb;
+  wire          hreadyout_o_tb;
+  logic  [AHB_DATA_WIDTH-1:0] hrdata_o_tb;
+
+  reg [31 : 0]  read_data;
+  reg [255 : 0] digest_data;
+
+  //----------------------------------------------------------------
+  // Device Under Test.
+  //----------------------------------------------------------------
+  wire  [3:0] spi_flash_sd;
+  logic       spi_flash_sck;
+  logic [1:0] spi_flash_csb;
+
+  logic             cio_sck_o;
+  logic             cio_sck_en_o;
+  logic [NumCS-1:0] cio_csb_o;
+  logic [NumCS-1:0] cio_csb_en_o;
+  logic [3:0]       cio_sd_o;
+  logic [3:0]       cio_sd_en_o;
+  logic [3:0]       cio_sd_i;
+
+  assign spi_flash_sck = cio_sck_o;
+  assign spi_flash_csb = cio_csb_o;
+  assign spi_flash_sd[3] = cio_sd_en_o[3] ? cio_sd_o[3] : 1'bz;
+  assign spi_flash_sd[2] = cio_sd_en_o[2] ? cio_sd_o[2] : 1'bz;
+  assign spi_flash_sd[1] = cio_sd_en_o[1] ? cio_sd_o[1] : 1'bz;
+  assign spi_flash_sd[0] = cio_sd_en_o[0] ? cio_sd_o[0] : 1'bz;
+
+  assign cio_sd_i[3] = cio_sd_en_o[3] ? 1'bz : spi_flash_sd[3];
+  assign cio_sd_i[2] = cio_sd_en_o[2] ? 1'bz : spi_flash_sd[2];
+  assign cio_sd_i[1] = cio_sd_en_o[1] ? 1'bz : spi_flash_sd[1];
+  assign cio_sd_i[0] = cio_sd_en_o[0] ? 1'bz : spi_flash_sd[0];
+
+  spi_host #(
+    .AHBDataWidth(32),
+    .AHBAddrWidth(32)
+  ) dut (
+    .clk_i       (clk_tb),
+    .rst_ni      (reset_n_tb),
+
+    // AMBA AHB Lite Interface
+    .haddr_i     (haddr_i_tb),
+    .hwdata_i    (hwdata_i_tb),
+    .hsel_i      (hsel_i_tb),
+    .hwrite_i    (hwrite_i_tb),
+    .hready_i    (hready_i_tb),
+    .htrans_i    (htrans_i_tb),
+    .hsize_i     (hsize_i_tb),
+    .hresp_o     (hresp_o_tb),
+    .hreadyout_o (hreadyout_o_tb),
+    .hrdata_o    (hrdata_o_tb),
+
+    // Alerts
+    .alert_rx_i(prim_alert_pkg::ALERT_RX_DEFAULT),
+    .alert_tx_o(),
+
+    // SPI Interface
+    .cio_sck_o    (cio_sck_o),
+    .cio_sck_en_o (cio_sck_en_o),
+    .cio_csb_o    (cio_csb_o),
+    .cio_csb_en_o (cio_csb_en_o),
+    .cio_sd_o     (cio_sd_o),
+    .cio_sd_en_o  (cio_sd_en_o),
+    .cio_sd_i     (cio_sd_i),
+
+    .intr_error_o(),
+    .intr_spi_event_o()
+  );
+
+  localparam logic [15:0] DeviceId0 = 16'hBA5E;
+  localparam logic [15:0] DeviceId1 = 16'h5AFE;
+
+  spiflash #(
+    .DeviceId(DeviceId0)
+  ) spiflash0 (
+    .sck (spi_flash_sck),
+    .csb (spi_flash_csb[0]),
+    .sd  (spi_flash_sd)
+  );
+
+  spiflash #(
+    .DeviceId(DeviceId1)
+  ) spiflash1 (
+    .sck (spi_flash_sck),
+    .csb (spi_flash_csb[1]),
+    .sd  (spi_flash_sd)
+  );
+
+  //----------------------------------------------------------------
+  // clk_gen
+  //
+  // Clock generator process.
+  //----------------------------------------------------------------
+`ifndef VERILATOR
+  always
+    begin : clk_gen
+      #CLK_HALF_PERIOD
+      clk_tb = !clk_tb;
+    end // clk_gen
+`endif
+
+  //----------------------------------------------------------------
+  // sys_monitor
+  //
+  // Generates a cycle counter and displays information about
+  // the dut as needed.
+  //----------------------------------------------------------------
+  always_ff @(posedge clk_tb) begin : sys_monitor
+      cycle_ctr = cycle_ctr + 1;
+    end
+
+
+  //----------------------------------------------------------------
+  // reset_dut()
+  //
+  // Toggles reset to force the DUT into a well defined state.
+  //----------------------------------------------------------------
+    task reset_dut;
+    begin
+      $display("*** Toggle reset.");
+      reset_n_tb = 0;
+
+      repeat (2) @(posedge clk_tb);
+      reset_n_tb = 1;
+
+      repeat (2) @(posedge clk_tb);
+
+      $display("");
+    end
+  endtask // reset_dut
+
+
+  //----------------------------------------------------------------
+  // init_sim()
+  //
+  // Initialize all counters and testbed functionality as well
+  // as setting the DUT inputs to defined values.
+  //----------------------------------------------------------------
+  task init_sim;
+    begin
+      generate_rng = '0;
+      cycle_ctr    = '0;
+      error_ctr    = '0;
+      tc_ctr       = '0;
+`ifndef VERILATOR
+      clk_tb       = 0;
+`endif
+      reset_n_tb   = 0;
+
+      haddr_i_tb   = 0;
+      hwdata_i_tb  = 0;
+      hsel_i_tb    = 0;
+      hwrite_i_tb  = 0;
+      hready_i_tb  = 0;
+      htrans_i_tb  = AHB_HTRANS_IDLE;
+      hsize_i_tb   = 3'b011;
+    end
+  endtask // init_dut
+
+
+  //----------------------------------------------------------------
+  // display_test_result()
+  //
+  // Display the accumulated test results.
+  //----------------------------------------------------------------
+  task display_test_result;
+    begin
+      if (error_ctr == 0)
+        begin
+          $display("*** All %02d test cases completed successfully.", tc_ctr);
+          $display("* TESTCASE PASSED");
+        end
+      else
+        begin
+          $display("*** %02d test cases completed.", tc_ctr);
+          $display("*** %02d errors detected during testing.", error_ctr);
+          $display("* TESTCASE FAILED");
+        end
+    end
+  endtask // display_test_result
+
+  //----------------------------------------------------------------
+  // write_single_word()
+  //
+  // Write the given word to the DUT using the DUT interface.
+  //----------------------------------------------------------------
+  task write_single_word(
+    input [spi_host_reg_pkg::BlockAw-1: 0]  addr,
+    input [31 : 0] word
+  );
+
+    logic [31:0] address;
+    address = {{32-spi_host_reg_pkg::BlockAw{1'b0}}, addr};
+
+    $display("[%t] write_single_word(addr=0x%x, word=0x%x)", $time, address, word);
+    hsel_i_tb       = 1;
+    haddr_i_tb      = address;
+    hwdata_i_tb     = word;
+    hwrite_i_tb     = 1;
+    hready_i_tb     = 1;
+    htrans_i_tb     = AHB_HTRANS_NONSEQ;
+    hsize_i_tb      = 3'b010;
+
+    @(posedge clk_tb);
+    hwdata_i_tb     = word;
+    hwrite_i_tb     = 0;
+    htrans_i_tb     = AHB_HTRANS_IDLE;
+    wait(hreadyout_o_tb == 1'b1);
+
+    @(posedge clk_tb);
+    hsel_i_tb       = 0;
+  endtask // write_single_word
+
+  //----------------------------------------------------------------
+  // read_word()
+  //
+  // Read a data word from the given address in the DUT.
+  // the word read will be available in the global variable
+  // read_data.
+  //----------------------------------------------------------------
+  task read_single_word(input [spi_host_reg_pkg::BlockAw-1 : 0]  addr);
+    logic [31:0] address;
+    spi_host_status_t status;
+    address = {{32-spi_host_reg_pkg::BlockAw{1'b0}}, addr};
+
+    hsel_i_tb       = 1;
+    haddr_i_tb      = address;
+    hwrite_i_tb     = 0;
+    hready_i_tb     = 1;
+    htrans_i_tb     = AHB_HTRANS_NONSEQ;
+    hsize_i_tb      = 3'b010;
+
+    @(posedge clk_tb);
+    hwdata_i_tb     = 0;
+    haddr_i_tb      = 'Z;
+    htrans_i_tb     = AHB_HTRANS_IDLE;
+    read_data       = hrdata_o_tb;
+    wait(hreadyout_o_tb == 1'b1);
+
+    @(posedge clk_tb);
+    hsel_i_tb       = 0;
+
+    if (addr == spi_host_reg_pkg::SPI_HOST_STATUS_OFFSET) begin
+      status = read_data;
+`ifdef VERILATOR
+      $display("[%t] read_single_word(addr=0x%x) = %x {ready=%d active=%d rxqd=%d txqd=%d}",
+        $time, address, status, status.ready, status.active, status.rxqd, status.txqd);
+`else
+      $display("[%t] read_single_word(addr=0x%x) = %p", $time, address, status);
+`endif
+    end else begin
+      $display("[%t] read_single_word(addr=0x%x) = 0x%x", $time, address, read_data);
+    end
+
+  endtask // read_word
+
+  task set_spi_csid(input int id);
+    write_single_word(spi_host_reg_pkg::SPI_HOST_CSID_OFFSET, {31'h0, id[0]});
+  endtask : set_spi_csid
+
+  task spi_command (
+    input int len,
+    input logic csaat, // chip select active after transaction
+    input spi_host_cmd_pkg::speed_t speed,
+    input spi_host_cmd_pkg::reg_direction_t direction
+  );
+
+    logic [8:0] length;
+    spi_host_status_t status;
+    length = len[8:0];
+
+    // Wait for Status.ready
+    do begin
+      read_single_word(spi_host_reg_pkg::SPI_HOST_STATUS_OFFSET);
+      status = read_data;
+      if (!status.ready) begin
+        repeat(10) @(posedge clk_tb);
+      end
+    end while (!status.ready);
+
+    write_single_word(spi_host_reg_pkg::SPI_HOST_COMMAND_OFFSET, {18'h0,  // reserved
+                                     direction,
+                                     speed,
+                                     csaat,
+                                     length});
+  endtask : spi_command
+
+  task spi_command_wait();
+    spi_host_status_t status;
+    // Wait for Status.active
+    do begin
+      read_single_word(spi_host_reg_pkg::SPI_HOST_STATUS_OFFSET);
+      status = read_data;
+      if (status.active) begin
+        repeat(10) @(posedge clk_tb);
+      end
+    end while (status.active);
+
+  endtask : spi_command_wait
+
+  task write_tx_fifo (input logic [31:0] data);
+    write_single_word(spi_host_reg_pkg::SPI_HOST_TXDATA_OFFSET, data);
+  endtask : write_tx_fifo
+
+
+  task read_rx_fifo (output logic [31:0] data);
+    read_single_word(spi_host_reg_pkg::SPI_HOST_RXDATA_OFFSET);
+    data = read_data;
+  endtask : read_rx_fifo
+
+  // configure_spi_host enables the IP and sets the protocol behavior
+  task configure_spi_host(input int host);
+    logic [spi_host_reg_pkg::BlockAw-1:0] offset;
+    write_single_word(spi_host_reg_pkg::SPI_HOST_CONTROL_OFFSET, {1'b1,    // spi enable
+                                    1'b0,    // sw rst
+                                    1'b1,    // output enable
+                                    13'h0,   // reserved
+                                    8'h0,    // tx watermark
+                                    8'h7f}); // rx watermark
+    if (host == 0) begin
+      offset = spi_host_reg_pkg::SPI_HOST_CONFIGOPTS_0_OFFSET;
+    end else begin
+      offset = spi_host_reg_pkg::SPI_HOST_CONFIGOPTS_1_OFFSET;
+    end
+
+    write_single_word(offset, {1'b0, // Polarity
+                               1'b0, // Phase
+                               1'b0, // full cycle
+                               1'b0, // reserved
+                               4'h0, // cs_n lead time
+                               4'h0, // cs_n trail time
+                               4'h0, // minimum time between commands
+                               16'h0}); // core clock divider
+  endtask : configure_spi_host
+
+  //----------------------------------------------------------------
+  // run_jedec_id_test()
+  //
+  // Configures the spi_host to request the jedec id
+  // The spiflash device will return 7 bytes of continuous code ('h7f)
+  // followed by the JedecId ('h1f) and the DeviceId ('h1234)
+  //----------------------------------------------------------------
+  task run_jedec_id_test(input int host);
+    logic [31:0] rx_data;
+    logic [31:0] exp_data[3];
+    spi_host_status_t status;
+
+    exp_data[0] = 32'h7f7f7f7f;
+    exp_data[1] = 32'h1f7f7f7f;
+    if (host == 0) begin
+      exp_data[2] = {16'h0, DeviceId0};
+    end else begin
+      exp_data[2] = {16'h0, DeviceId1};
+    end
+
+    // Load the TX FIFO with instructions and data to be transmitted
+    write_tx_fifo({24'h0, CmdJedecId});
+
+    // Specify which device should receive the next command
+    set_spi_csid(host);
+
+    // Issue speed, direction and length details for the next command
+    // segment.  If a command consists of multiple segments, set csaat to one
+    // for all segments except the last one.
+    //
+    // Issue Command Instruction
+    spi_command(.len(0),
+                .csaat(1),
+                .speed(spi_host_cmd_pkg::Standard),
+                .direction(spi_host_cmd_pkg::WrOnly));
+
+    // spi flash will return 10 bytes for the jedec command
+    spi_command(.len(9), // Read Len+1 Bytes
+                .csaat(0),
+                .speed(spi_host_cmd_pkg::Standard),
+                .direction(spi_host_cmd_pkg::RdOnly));
+
+    // Wait for spi commands to finish before reading responses
+    spi_command_wait();
+
+    read_single_word(spi_host_reg_pkg::SPI_HOST_STATUS_OFFSET);
+    status = read_data;
+    // TODO: Replace with assertions when open source tooling is better
+    // supported.
+    if ({24'h0, status.rxqd} != $size(exp_data)) begin
+      error_ctr += 1;
+      $display("run_jedec_id_test: status.rxqd: Got: %d Want:%d", status.rxqd, $size(exp_data));
+    end
+
+    for (int ii = 0; ii < $size(exp_data); ii += 1) begin
+      read_rx_fifo(rx_data);
+      if (rx_data != exp_data[ii]) begin
+        error_ctr += 1;
+        $display("run_jedec_id_test: rx_data: Got: %d Want:%d", rx_data, exp_data[ii]);
+      end
+    end
+  endtask : run_jedec_id_test
+
+
+  //----------------------------------------------------------------
+  // run_read_test()
+  //
+  // Configures the spi_host to request data from the spi flash
+  // discoverable parameters (read)
+  // The spiflash device will return 7 bytes of continuous code ('h7f)
+  // followed by the JedecId ('h1f) and the DeviceId ('h1234)
+  //----------------------------------------------------------------
+  task run_read_test(input int host);
+    logic [31:0] rx_data;
+    logic [7:0]  rx_bytes[$] = {};
+    spi_host_status_t status;
+    logic [7:0]  spi_data;
+    logic [19:0] spi_offset;
+
+    localparam int NumBytes = 256;
+    localparam logic [23:0] SpiFlashAddr = 24'h00ABCD;
+
+    // Load the TX FIFO with instructions and data to be transmitted
+    write_tx_fifo({24'h0, CmdReadQuad});
+    // Upper Bytes are transmitted first, 8'h12 is ignored
+    write_tx_fifo({8'h12, SpiFlashAddr[7:0],
+                          SpiFlashAddr[15:8],
+                          SpiFlashAddr[23:16]});
+
+    // Specify which device should receive the next command
+    set_spi_csid(host);
+
+    // Issue speed, direction and length details for the next command
+    // segment.  If a command consists of multiple segments, set csaat to one
+    // for all segments except the last one.
+    //
+    // Issue Command Instruction
+    spi_command(.len(0),
+                .csaat(1),
+                .speed(spi_host_cmd_pkg::Standard),
+                .direction(spi_host_cmd_pkg::WrOnly));
+    // Issue 3 Byte Address - (Send the CmdEn4B if 4B is needed)
+    spi_command(.len(2),
+                .csaat(1),
+                .speed(spi_host_cmd_pkg::Standard),
+                .direction(spi_host_cmd_pkg::WrOnly));
+
+    // Issue 2 Dummy Cycles - This is derived from spiflash.DummyQuad-1
+    spi_command(.len(1),
+                .csaat(1),
+                .speed(spi_host_cmd_pkg::Quad),
+                .direction(spi_host_cmd_pkg::Dummy));
+
+    // Request 13 bytes of data
+    spi_command(.len(NumBytes-1), // Read Len+1 Bytes
+                .csaat(0),
+                .speed(spi_host_cmd_pkg::Quad),
+                .direction(spi_host_cmd_pkg::RdOnly));
+
+    // Wait for spi commands to finish before reading responses
+    spi_command_wait();
+
+    read_single_word(spi_host_reg_pkg::SPI_HOST_STATUS_OFFSET);
+    status = read_data;
+
+    // Store the bytes for comparison
+    for (int ii = 0; ii < status.rxqd; ii += 1) begin
+      read_rx_fifo(rx_data);
+      rx_bytes.push_back(rx_data[0+:8]);
+      rx_bytes.push_back(rx_data[8+:8]);
+      rx_bytes.push_back(rx_data[16+:8]);
+      rx_bytes.push_back(rx_data[24+:8]);
+    end
+
+    for (int ii = 0; ii < rx_bytes.size(); ii += 1) begin
+      if (ii >= NumBytes) begin
+        if (rx_bytes[ii] != 8'h0) begin
+          error_ctr += 1;
+          $display("Received Extra Non-Zero Bytes from SpiFlash.  Got: %d Want: %d Size:%d",
+            rx_bytes[ii], 0, rx_bytes.size());
+        end
+        continue;
+      end
+      spi_offset = SpiFlashAddr[0+:$bits(spi_offset)] +
+                             ii[0+:$bits(spi_offset)];
+      if (host == 0) begin
+        spi_data = spiflash0.storage[spi_offset];
+      end else begin
+        spi_data = spiflash1.storage[spi_offset];
+      end
+      if (rx_bytes[ii] != spi_data) begin
+        error_ctr += 1;
+        $display("[%d]spiflash.storage[%x] Got: %x Want: %x",
+          ii,
+          spi_offset,
+          rx_bytes[ii],
+          spi_data);
+      end
+    end
+  endtask : run_read_test
+
+  //----------------------------------------------------------------
+  // The main test functionality.
+  //----------------------------------------------------------------
+  initial
+    begin : main
+      $display("   -- Testbench for spi_host started --");
+
+      init_sim();
+      reset_dut();
+
+      for (int host = 0; host < NUM_HOSTS; host +=1) begin
+        configure_spi_host(host);
+        // Run Tests
+        run_jedec_id_test(host);
+        run_read_test(host);
+        run_read_test(host);
+        run_read_test(host);
+      end
+
+      display_test_result();
+
+      $finish;
+    end // main
+endmodule // spi_host_tb
+
+//======================================================================
+// EOF spi_host_tb.sv
+//======================================================================
diff --git a/src/spi_host/tb/spiflash.sv b/src/spi_host/tb/spiflash.sv
new file mode 100644
index 00000000..a3642b8a
--- /dev/null
+++ b/src/spi_host/tb/spiflash.sv
@@ -0,0 +1,509 @@
+// Copyright lowRISC contributors.
+// Licensed under the Apache License, Version 2.0, see LICENSE for details.
+// SPDX-License-Identifier: Apache-2.0
+//
+// Behavioral model of SPI Flash
+// Modifications:
+// Removed all forked processes behavior since verilator doesn't support
+// disable fork.  This also means that the ability to detect early termination
+// is removed as well.
+
+module spiflash #(
+  parameter int unsigned FlashSize = 1024*1024, // 1MB
+  parameter int unsigned PageSize = 256, // Bytes
+
+  parameter bit EnFastSim = 1'b 1, // Reduce the latencies
+
+  // Timing information               s_ ms_ us
+  // Program Latency
+  parameter int unsigned tPPTyp   =       1_000, // us
+  parameter int unsigned tPPMax   =       3_000, // us
+  // Sector Erase(4kB) Latency
+  parameter int unsigned tSETyp   =      45_000, // us
+  parameter int unsigned tSEMax   =     200_000, // us
+  // Block Erase 32kB Latency
+  parameter int unsigned tBE32Typ =     200_000, // us
+  parameter int unsigned tBE32Max =   1_000_000, // us
+  // Block Erase 64kB Latency
+  parameter int unsigned tBE64Typ =     400_000, // us
+  parameter int unsigned tBE64Max =   2_000_000, // us
+  // Chip Erase Latency
+  parameter int unsigned tCETyp   = 200_000_000, // us
+  parameter int unsigned tCEMax   = 320_000_000, // us
+
+  // Num of Repeating Continuous Code ('h7F)
+  parameter int unsigned CcNum    = 7,
+  parameter logic [7:0]  JedecId  = 8'h 1F,
+  parameter logic [15:0] DeviceId = 16'h 1234,
+
+  // Command Support
+  parameter bit EnFastReadDual = 1'b 1,
+  parameter bit EnFastReadQuad = 1'b 1,
+
+  // Dummy Cycle
+  parameter int unsigned DummySizeNormal = 8,
+  parameter int unsigned DummySizeDual   = 4,
+  parameter int unsigned DummySizeQuad   = 2
+) (
+  input logic sck,
+  input logic csb,
+  inout [3:0] sd
+  // TODO: Add WP
+);
+
+  // Local parameter : affected by EnFastSim
+
+  // Timing information               s_ ms_ us
+  localparam int unsigned tPPDiv   = (EnFastSim) ?      1_000 : 1;
+  localparam int unsigned tSEDiv   = (EnFastSim) ?      5_000 : 1;
+  localparam int unsigned tBE32Div = (EnFastSim) ?     10_000 : 1;
+  localparam int unsigned tBE64Div = (EnFastSim) ?    100_000 : 1;
+  localparam int unsigned tCEDiv   = (EnFastSim) ? 10_000_000 : 1;
+  // Program Latency
+  localparam int unsigned LocalPPTyp   = tPPTyp   / tPPDiv; // us
+  localparam int unsigned LocalPPMax   = tPPMax   / tPPDiv; // us
+  // Sector Erase(4kB) Latency
+  localparam int unsigned LocalSETyp   = tSETyp   / tSEDiv; // us
+  localparam int unsigned LocalSEMax   = tSEMax   / tSEDiv; // us
+  // Block Erase 32kB Latency
+  localparam int unsigned LocalBE32Typ = tBE32Typ / tBE32Div; // us
+  localparam int unsigned LocalBE32Max = tBE32Max / tBE32Div; // us
+  // Block Erase 64kB Latency
+  localparam int unsigned LocalBE64Typ = tBE64Typ / tBE64Div; // us
+  localparam int unsigned LocalBE64Max = tBE64Max / tBE64Div; // us
+  // Chip Erase Latency
+  localparam int unsigned LocalCETyp   = tCETyp   / tCEDiv; // us
+  localparam int unsigned LocalCEMax   = tCEMax   / tCEDiv; // us
+
+
+  typedef enum int unsigned {
+    Addr3B,
+    Addr4B,
+    AddrCfg
+  } addr_mode_e;
+
+  // Return Output mode
+  typedef enum int unsigned {
+    IoSingle = 1,
+    IoDual   = 2,
+    IoQuad   = 4
+  } io_mode_e;
+
+  typedef logic [7:0] spiflash_byte_t;
+
+  localparam spiflash_byte_t Cc = 8'h 7F;
+
+  localparam int unsigned StorageAw = $clog2(FlashSize);
+
+  // Status Bit Location
+  typedef enum int unsigned {
+    StatusBUSY = 0,
+    StatusWEL  = 1,
+    StatusBP0  = 2,
+    StatusBP1  = 3,
+    StatusBP2  = 4,
+    StatusBP3  = 5,
+    StatusQE   = 6, // Quad Enable
+    StatusSRWD = 7  // Status Register Write Protect
+  } status_bit_e;
+
+  // spiflash_addr_t is the smallest address width to represent FlashSize bytes
+  typedef logic [StorageAw-1:0] spiflash_addr_t;
+
+  logic [3:0] sd_out, sd_en;
+
+  assign sd[0] = sd_en[0] ? sd_out[0] : 1'b z;
+  assign sd[1] = sd_en[1] ? sd_out[1] : 1'b z;
+  assign sd[2] = sd_en[2] ? sd_out[2] : 1'b z;
+  assign sd[3] = sd_en[3] ? sd_out[3] : 1'b z;
+
+  // SPI Flash internal state variables
+  addr_mode_e     addr_mode;
+  spiflash_byte_t [2:0] status; // 24 bit
+  spiflash_byte_t storage[spiflash_addr_t]; // Associative Array to store data
+
+  spiflash_byte_t page_buffer[PageSize]; // page buffer to be used
+  int unsigned    page_buffer_size;
+
+  spiflash_byte_t sfdp[256]; // SFDP storage 256Byte
+
+  initial begin
+    logic [31:0] random_data;
+    print_banner();
+
+    // Init values
+    status = '0;
+
+    // SFDP initialization
+    // FIXME: Appropriate SFDP table rather than random data
+    foreach(sfdp[i]) begin
+      random_data = $urandom_range(255, 0);
+      sfdp[i] = random_data[7:0];
+    end
+
+    main();
+  end
+
+  function automatic void print_banner();
+    $display("/////////////////////");
+    $display("// SPI Flash Model //");
+    $display("/////////////////////");
+
+    // Print current config
+    $display("");
+    $display("Configurations:");
+    $display("  JEDEC ID:  ID(0x%2X) CC_NUM (%2d)  DEVICE ID: (0x%x)", JedecId, CcNum, DeviceId);
+    $display("  Capacity:  %s", print_capacity(FlashSize));
+    $display("  Fast Read: %s/ Dummy Cycle (%1d)",
+      "Enabled", DummySizeNormal);
+    $display("  Dual Mode:%s/ Dummy Cycle (%1d)",
+      (EnFastReadDual) ? "Enabled" : "Disabled", DummySizeDual);
+    $display("  Quad Mode:%s/ Dummy Cycle (%1d)",
+      (EnFastReadQuad) ? "Enabled" : "Disabled", DummySizeQuad);
+  endfunction : print_banner
+
+  function automatic string print_capacity(int unsigned size);
+    string str;
+    // Get the highest unit (GB, MB, kB)
+    automatic int unsigned quotient;
+    automatic int unsigned order; // 0: B, 1: kB, 2: MB, 3: GB
+    automatic string unit;
+    quotient = size;
+    forever begin
+      if (quotient < 1024) break;
+      quotient = quotient / 1024;
+      order = order + 1;
+    end
+
+    case (order)
+      0: unit = "B";
+      1: unit = "kB";
+      2: unit = "MB";
+      3: unit = "GB";
+      4: unit = "TB";
+      default: unit = "Unsupported";
+    endcase
+
+    str = $sformatf("%0d%s", quotient, unit);
+    return str;
+  endfunction : print_capacity
+
+  task static main();
+    // Main function
+    forever begin
+      automatic spiflash_byte_t opcode;
+      automatic int unsigned    excessive_sck = 0;
+      // Indication of process needed after CSb release
+      automatic bit             process_after_csb = 1'b 0;
+      // Big loop. Wait transaction
+      sd_en = 4'h 0; // Off the output by default
+      wait(csb == 1'b 0);
+
+      // Main
+      cmdparse(opcode); // Store incoming into opcod
+      process_cmd(opcode, process_after_csb);
+
+      // Float the line
+      sd_en = 4'h 0;
+    end
+  endtask : main
+
+  task automatic cmdparse(
+    output spiflash_byte_t opcode
+  );
+    automatic spiflash_byte_t spi_byte = 0;
+    get_byte(IoSingle, spi_byte);
+    $display("SPIFlash: Command(%2Xh) received", spi_byte);
+    opcode = spi_byte;
+  endtask : cmdparse
+
+  task automatic process_cmd(
+    input spiflash_byte_t opcode,
+    output bit en_backend
+  );
+    // Main case block to call subtasks depending on the opcode
+    en_backend = 1'b 0;
+    case (opcode)
+      spi_device_pkg::CmdReadStatus1: begin
+        // Return status data
+        return_status(0); // 0-2
+      end
+
+      spi_device_pkg::CmdJedecId: begin
+        return_jedec();
+      end
+
+      spi_device_pkg::CmdReadSfdp: begin
+        return_sfdp();
+      end
+
+      spi_device_pkg::CmdReadData, spi_device_pkg::CmdReadFast,
+      spi_device_pkg::CmdReadDual, spi_device_pkg::CmdReadQuad: begin
+        read(opcode);
+      end
+
+      spi_device_pkg::CmdEn4B, spi_device_pkg::CmdEx4B: begin
+        addr_4b(opcode);
+      end
+
+      spi_device_pkg::CmdWriteEnable, spi_device_pkg::CmdWriteDisable: begin
+        wel(opcode);
+      end
+
+      // TODO: SectorErase
+      // TODO: BlockErase32
+      // TODO: BlockErase64
+      default: begin
+        $display("Unrecognized Opcode (%2Xh) received", opcode);
+      end
+    endcase
+
+  endtask : process_cmd
+
+  task automatic process_cmd_after_csb(
+
+  );
+  endtask : process_cmd_after_csb
+
+  task automatic get_byte(
+    input  io_mode_e       io_mode,
+    output spiflash_byte_t data
+  );
+    // Receive a byte on SPI
+    // Expected to be called @(negedge sck);
+    automatic spiflash_byte_t spi_byte = 0;
+    // Receive first 8 beats and decoding the byte, call subsequence tasks.
+    repeat(8/io_mode) begin
+      @(posedge sck);
+      case (io_mode)
+        IoSingle: spi_byte = {spi_byte[6:0], sd[  0]};
+        IoDual:   spi_byte = {spi_byte[5:0], sd[1:0]};
+        IoQuad:   spi_byte = {spi_byte[3:0], sd[3:0]};
+        default:  spi_byte = {spi_byte[6:0], sd[  0]};
+      endcase
+    end
+    @(negedge sck); // Wait the data line fully completed
+    data = spi_byte;
+  endtask : get_byte
+
+  task automatic get_address(
+    input  io_mode_e    imode,
+    input  addr_mode_e  amode,
+    output logic [31:0] addr
+  );
+    automatic spiflash_byte_t spi_byte;
+    automatic addr_mode_e mode;
+    case (amode)
+      AddrCfg: mode = addr_mode;
+      Addr3B, Addr4B: mode = amode;
+      default: mode = Addr3B;
+    endcase
+
+    if (mode == Addr4B) begin
+      // Get upper byte
+      get_byte(imode, spi_byte);
+      addr[31:24] = spi_byte;
+    end else begin
+      addr[31:24] = 8'h 0;
+    end
+
+    for(int i = 2; i >= 0; i--) begin
+      get_byte(imode, spi_byte);
+      addr[8*i+:8] = spi_byte;
+    end
+
+  endtask : get_address
+
+  task automatic return_byte(spiflash_byte_t data, io_mode_e io_mode);
+    // Assume the task is called at @(negedge sck);
+    automatic int unsigned rails;
+    automatic logic [7:0]  lines;
+    case (io_mode)
+      IoSingle: begin
+        rails = 1;
+        sd_en = 4'b 0010;
+      end
+      IoDual: begin
+        rails = 2;
+        sd_en = 4'b 0011;
+      end
+      IoQuad: begin
+        rails = 4;
+        sd_en = 4'b 1111;
+      end
+      default: begin
+        rails = 1;
+        sd_en = 4'b 0010;
+      end
+    endcase
+
+    lines = data;
+    repeat(8/rails) begin
+      case (io_mode)
+        IoSingle: begin
+          sd_out[1] = lines[7];
+          lines = {lines[6:0], 1'b 0};
+        end
+        IoDual: begin
+          sd_out[1:0] = lines[7:6];
+          lines = {lines[5:0], 2'b 00};
+        end
+        IoQuad: begin
+          sd_out[3:0] = lines[7:4];
+          lines = {lines[3:0], 4'b 0000};
+        end
+        default: begin
+          sd_out[1] = lines[7];
+          lines = {lines[6:0], 1'b 0};
+        end
+      endcase
+      fork
+        begin
+          @(negedge sck);
+        end
+        begin
+          wait(csb);
+        end
+      join_any
+
+      if (csb) begin
+        break;
+      end
+    end
+  endtask : return_byte
+
+  task automatic dummy(int unsigned cycle);
+    // Assume the task is called @(negedge sck);
+    sd_en = 4'b 0000;
+    repeat (cycle) @(negedge sck);
+  endtask : dummy
+
+  task automatic return_status(int unsigned idx);
+    // Starting from the index and wraps %3 until host releases CSb
+    automatic int unsigned s_idx = idx;
+
+    // Copy the status into internal variable to not be corrupted by on-going
+    // backend tasks.
+    automatic spiflash_byte_t [2:0] committed_status = status;
+    forever begin
+      return_byte(committed_status[s_idx], IoSingle);
+      s_idx = (s_idx + 1)%3;
+      if (csb) begin
+        break;
+      end
+    end
+  endtask : return_status
+
+  task automatic return_jedec();
+    // Repeat CcNum then JedecId and DeviceId(MSB to LSB)
+    repeat (CcNum) begin
+      return_byte(Cc, IoSingle);
+    end
+    return_byte(JedecId, IoSingle);
+    return_byte(DeviceId[ 7:0], IoSingle);
+    return_byte(DeviceId[15:8], IoSingle);
+    // Float
+  endtask : return_jedec
+
+  task automatic return_sfdp();
+    automatic logic [31:0] address;
+    // Get address field
+    get_address(IoSingle, Addr3B, address);
+    $display("%d] SPIFlash: SFDP Address %6Xh", $time, address);
+
+    // dummy byte
+    dummy(8); // 8 cycle dummy
+
+    // fetch data and return
+    forever begin
+      return_byte(sfdp[address++], IoSingle);
+      if (csb) begin
+        break;
+      end
+    end
+  endtask : return_sfdp
+
+  task static read(
+    input spiflash_byte_t opcode
+  );
+    // Return Read data
+    automatic logic [31:0]    address;
+    automatic spiflash_addr_t spi_addr;
+    automatic io_mode_e       io_mode     = IoSingle;
+    automatic int unsigned    dummy_cycle = 0;
+    automatic logic [31:0]    random_data;
+
+    // get address field
+    get_address(IoSingle, AddrCfg, address);
+    $display("T:%0d] SPIFlash: Read Address %8Xh", $time, address);
+    if (address[31:StorageAw] != '0) begin
+      $display("Out-of-Bound Address received: %8Xh", address);
+      $display("  Keep returning garbage data");
+    end
+
+    spi_addr = address[0+:StorageAw];
+
+    // Dummy cycle?
+    case (opcode)
+      spi_device_pkg::CmdReadData: begin
+        io_mode     = IoSingle;
+        dummy_cycle = 0;
+      end
+
+      spi_device_pkg::CmdReadFast: begin
+        io_mode     = IoSingle;
+        dummy_cycle = DummySizeNormal;
+      end
+
+      spi_device_pkg::CmdReadDual: begin
+        io_mode     = IoDual;
+        dummy_cycle = DummySizeDual;
+      end
+
+      spi_device_pkg::CmdReadQuad: begin
+        io_mode     = IoQuad;
+        dummy_cycle = DummySizeQuad;
+      end
+      default: $display("read: Unrecognized Cmd (%2Xh)", opcode);
+    endcase
+
+    if (dummy_cycle != 0) dummy(dummy_cycle);
+
+    // fetch from storage and return
+    while (address <= FlashSize && !csb) begin
+      // Check if exists, if not fill with random data
+      random_data = $urandom_range(255,0);
+      if (storage.exists(spi_addr) == 0) storage[spi_addr] = random_data[0+:8];
+      return_byte(storage[spi_addr++], io_mode);
+    end
+
+    $display("read completed");
+  endtask : read
+
+  task automatic addr_4b(spiflash_byte_t opcode);
+    // Set / clear addr_mode
+    case (opcode)
+      spi_device_pkg::CmdEn4B: addr_mode = Addr4B;
+      spi_device_pkg::CmdEx4B: addr_mode = Addr3B;
+      default: $display("addr_4b: Unrecognized Cmd (%2Xh)", opcode);
+    endcase
+  endtask : addr_4b
+
+  task automatic wel(spiflash_byte_t opcode);
+    // TODO: Set only when CSb is deasserted right after 8th beat
+    case (opcode)
+      spi_device_pkg::CmdWriteEnable:  status[0][StatusWEL] = 1'b 1;
+      spi_device_pkg::CmdWriteDisable: status[0][StatusWEL] = 1'b 0;
+      default: $display("WEL: Unrecognized Cmd (%2Xh)", opcode);
+    endcase
+  endtask : wel
+
+  initial begin
+    assert(PageSize == 256)
+      else begin
+        $display("SPIFlash currently supports 256B Page only");
+        $finish();
+      end
+  end
+
+endmodule: spiflash

design_diff:
diff --git a/src/aes/rtl/aes_cipher_control.sv b/src/aes/rtl/aes_cipher_control.sv
index 4d083896..2e9745d1 100644
--- a/src/aes/rtl/aes_cipher_control.sv
+++ b/src/aes/rtl/aes_cipher_control.sv
@@ -476,7 +476,7 @@ module aes_cipher_control import aes_pkg::*;
   ////////////////

   // Selectors must be known/valid
-  `ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
+  `CALIPTRA_ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
       CIPH_FWD,
       CIPH_INV
       })
diff --git a/src/aes/rtl/aes_cipher_control_fsm.sv b/src/aes/rtl/aes_cipher_control_fsm.sv
index 837a0bac..3bc03708 100644
--- a/src/aes/rtl/aes_cipher_control_fsm.sv
+++ b/src/aes/rtl/aes_cipher_control_fsm.sv
@@ -483,23 +483,23 @@ module aes_cipher_control_fsm import aes_pkg::*;
   ////////////////

   // Create a lint error to reduce the risk of accidentally disabling the masking.
-  `ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecMaskingNonDefault, SecMasking == 1)
+  `CALIPTRA_ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecMaskingNonDefault, SecMasking == 1)

   // Create a lint error to reduce the risk of accidentally using a less secure SBox
   // implementation.
-  `ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecSBoxImplNonDefault, SecSBoxImpl == SBoxImplDom)
+  `CALIPTRA_ASSERT_STATIC_LINT_ERROR(AesCipherControlFsmSecSBoxImplNonDefault, SecSBoxImpl == SBoxImplDom)

   // Selectors must be known/valid
-  `ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
+  `CALIPTRA_ASSERT(AesCiphOpValid, cfg_valid_i |-> op_i inside {
       CIPH_FWD,
       CIPH_INV
       })
-  `ASSERT(AesKeyLenValid, cfg_valid_i |-> key_len_i inside {
+  `CALIPTRA_ASSERT(AesKeyLenValid, cfg_valid_i |-> key_len_i inside {
       AES_128,
       AES_192,
