         rand kv_status_reg HMAC384_KV_RD_KEY_STATUS;
         rand kv_read_ctrl_reg HMAC384_KV_RD_BLOCK_CTRL;
@@ -682,6 +697,13 @@ package hmac_reg_uvm;
